window.AUREA_CATALOG = {"A001":{"category_key":"furniture","title_it":"Console Luigi XV intarsiata con mensola estraibile e cassetto laterale","title_en":"Louis XV Style Inlaid Console with Pull-Out Shelf and Side Drawer","title_fr":"Console marquetée de style Louis XV avec tablette coulissante et tiroir latéral","category_it":"Mobili","category_en":"Furniture","category_fr":"Mobilier","dimensions":"H 73 × L 81 × P 40 cm","description_it":"Elegante console in stile Luigi XV, caratterizzata da una ricca decorazione ad intarsio floreale e sinuose gambe mosse.\nIl mobile è dotato di una pratica mensola estraibile frontale e di un cassetto laterale, dettagli che ne aumentano la funzionalità senza alterarne l’eleganza.\nLe proporzioni armoniose e la qualità delle lavorazioni la rendono ideale come console d’ingresso, scrittoio occasionale o elemento d’arredo per ambienti classici e raffinati.","description_en":"Italian Louis XV style console with floral marquetry, a central drawer and a practical pull-out shelf.","description_fr":"Console italienne de style Louis XV avec marqueterie florale, tiroir central et tablette coulissante.","images":["assets/images/A001/A001-01.webp","assets/images/A001/A001-02.webp","assets/images/A001/A001-03.webp","assets/images/A001/A001-04.webp","assets/images/A001/A001-05.webp","assets/images/A001/A001-06.webp"],"status":"available","epoch_it":"XX secolo","style_it":"Luigi XV","material_it":"Legni pregiati intarsiati","specs_it":[{"label":"Epoca","value":"XX secolo"},{"label":"Stile","value":"Luigi XV"},{"label":"Materiali","value":"Legni pregiati intarsiati"}]},"A002":{"category_key":"mirrors","title_it":"Specchiera Luigi XV in legno intagliato e dorato","title_en":"Antique Giltwood Mirror","title_fr":"Miroir ancien en bois doré","category_it":"Specchi","category_en":"Mirrors","category_fr":"Miroirs","dimensions":"H 115 × L 90 cm","description_it":"Elegante specchiera in stile Luigi XV, caratterizzata da una ricca cornice in legno intagliato e dorato a foglia oro. La cornice presenta una raffinata decorazione a rilievo con motivi vegetali e ornamentali che percorrono l’intero perimetro.\n\nParticolarmente elaborata la cimasa superiore, finemente scolpita con ampie volute contrapposte e motivi fogliacei, organizzati simmetricamente attorno a un elemento centrale sagomato. L’andamento mosso e sinuoso della parte superiore conferisce alla specchiera la leggerezza e l’eleganza tipiche del gusto Luigi XV.\n\nLa superficie dorata conserva una patina naturale, con variazioni di tono e segni del tempo coerenti con l’età dell’oggetto. Lo specchio antico originale presenta diffuse ossidazioni, soprattutto lungo i margini, e alterazioni della superficie riflettente che ne testimoniano l’autenticità e contribuiscono al fascino storico dell’insieme.\n\nLe proporzioni verticali e l’importante apparato decorativo ne fanno un elemento di forte presenza, adatto a ingressi, salotti, camere o ambienti di rappresentanza, sia in contesti classici sia come elemento antico di contrasto in interni contemporanei.\n\nEPOCA\nSeconda metà XVIII secolo\n\nSTILE\nLuigi XV\n\nMATERIALE\nLegno intagliato e dorato a foglia oro, specchio antico originale\n\nDIMENSIONI","description_en":"Large decorative mirror with a gilt floral and scroll frame, crowned by an elaborate pierced crest.","description_fr":"Grand miroir décoratif à cadre doré de motifs floraux et volutes, surmonté d’un fronton ajouré.","images":["assets/images/A002/A002-01.webp","assets/images/A002/A002-02.webp","assets/images/A002/A002-03.webp","assets/images/A002/A002-04.webp","assets/images/A002/A002-05.webp","assets/images/A002/A002-06.webp"],"status":"available","specs_it":[]},"A003":{"category_key":"seating","title_it":"Coppia di poltroncine con tessuto operato e passamaneria Cannetta Milano","title_en":"Pair of Antique Embroidered Armchairs","title_fr":"Paire de fauteuils anciens brodés","category_it":"Sedute e salotti","category_en":"Seating","category_fr":"Sièges","dimensions":"H 87 × L 55 × P 52 cm (cad.)","description_it":"Elegante coppia di poltroncine di epoca metà XX secolo, rivestite in un elegante tessuto operato a motivo geometrico, caratterizzato dall’alternanza di tonalità di verde scuro e verde chiaro.\n\nLa lavorazione, interamente eseguita a mano dallo storico Cannetta di Milano, è impreziosita da una raffinata passamaneria con frange e nappe intrecciate, che esalta il gusto classico e l’eleganza delle forme.","description_en":"Pair of enveloping armchairs with shaped backs and refined geometric-pattern upholstery.","description_fr":"Paire de fauteuils enveloppants à dossiers galbés et élégant revêtement à motif géométrique.","images":["assets/images/A003/A003-01.webp","assets/images/A003/A003-02.webp","assets/images/A003/A003-03.webp","assets/images/A003/A003-04.webp","assets/images/A003/A003-05.webp","assets/images/A003/A003-06.webp"],"status":"available","epoch_it":"Metà XX secolo","style_it":"Classico","material_it":"Struttura in legno, imbottitura, tessuto operato, passamaneria con frange e nappe","specs_it":[{"label":"Epoca","value":"Metà XX secolo"},{"label":"Stile","value":"Classico"},{"label":"Lavorazione","value":"Artigianale, eseguita a mano da Cannetta, Milano"},{"label":"Materiale","value":"Struttura in legno, imbottitura, tessuto operato, passamaneria con frange e nappe"}]},"A004":{"category_key":"paintings","title_it":"Coppia di nature morte floreali a olio su tela firmate A. Persico","title_en":"Pair of Floral Still Lifes","title_fr":"Paire de natures mortes florales","category_it":"Dipinti","category_en":"Paintings","category_fr":"Peintures","dimensions":"H 60 × L 50 cm (cad.)","description_it":"Coppia di nature morte floreali a olio su tela, raffiguranti ricche composizioni di fiori disposti in vaso su fondo scuro.\n\nLe opere presentano bouquet differenti ma armoniosamente abbinati, caratterizzati da rose, margherite e altri fiori nelle tonalità del rosa, rosso, giallo e bianco, valorizzati dal contrasto con il fondo bruno.\n\nEntrambi i dipinti recano la firma “A. Persico” e sono conservati nelle rispettive cornici.","description_en":"Pair of floral oil paintings signed A. Persico and presented in their original frames.","description_fr":"Paire de compositions florales à l’huile, signées A. Persico et présentées dans leurs cadres d’origine.","images":["assets/images/A004/A004-01.webp","assets/images/A004/A004-02.webp","assets/images/A004/A004-03.webp","assets/images/A004/A004-04.webp","assets/images/A004/A004-05.webp","assets/images/A004/A004-06.webp","assets/images/A004/A004-07.webp"],"status":"available","specs_it":[{"label":"Tecnica","value":"Olio su tela"},{"label":"Soggetto","value":"Nature morte floreali"},{"label":"Firma","value":"A. Persico"},{"label":"Cornici","value":"Presenti"}]},"A005":{"category_key":"furniture","title_it":"Tavolino in alabastro e bronzo massiccio stile Luigi XV","title_en":"Louis XV Style Alabaster and Bronze Coffee Table","title_fr":"Table basse de style Louis XV en albâtre et bronze","category_it":"Mobili","category_en":"Furniture","category_fr":"Mobilier","dimensions":"H 44 × L 120 × P 55 cm","description_it":"Elegante tavolino da salotto con piano in alabastro naturale lucidato e struttura in bronzo massiccio finemente lavorato, realizzato in stile Luigi XV.\n\nIl piano in alabastro presenta splendide venature naturali nei toni del verde, miele e rosato, caratteristiche tipiche di questa pietra decorativa e che rendono ogni pezzo unico. La base è riccamente decorata con motivi rocaille e gambe cabriole, tipiche dello stile francese Luigi XV.\n\nStruttura molto solida e pesante, tavolino elegante e scenografico, ideale per salotti classici o ambienti di rappresentanza.","description_en":"Louis XV style table with a natural alabaster top and a richly worked bronze frame.","description_fr":"Table de style Louis XV avec plateau en albâtre naturel et structure en bronze richement ouvragée.","images":["assets/images/A005/A005-01.webp","assets/images/A005/A005-02.webp","assets/images/A005/A005-03.webp","assets/images/A005/A005-04.webp","assets/images/A005/A005-05.webp","assets/images/A005/A005-06.webp","assets/images/A005/A005-07.webp","assets/images/A005/A005-08.webp"],"status":"available","epoch_it":"XX secolo","style_it":"Luigi XV","material_it":"Alabastro naturale lucidato e bronzo massiccio finemente lavorato","specs_it":[{"label":"Epoca","value":"XX secolo"},{"label":"Stile","value":"Luigi XV"},{"label":"Materiale","value":"Alabastro naturale lucidato e bronzo massiccio finemente lavorato"}]},"A006":{"category_key":"clocks","title_it":"Pendola francese «A Paris» in marmo e bronzo dorato","title_en":"French “A Paris” Marble and Gilt-Bronze Portico Clock","title_fr":"Pendule portique française « A Paris » en marbre et bronze doré","category_it":"Orologi","category_en":"Decorative Objects","category_fr":"Objets décoratifs","dimensions":"H 50 × L 32 × P 9 cm","description_it":"Elegante pendola da camino francese del XIX secolo, realizzata in stile neoclassico / Luigi XVI, con struttura in marmo bianco e marmo nero impreziosita da ricche applicazioni ornamentali in bronzo dorato.\n\nL’orologio presenta la caratteristica architettura a portico, tipica delle pendules portique francesi, con colonne che sostengono il corpo centrale dell’orologio in una composizione decorativa elegante e simmetrica.\n\nIl quadrante in smalto bianco presenta numeri arabi e reca la dicitura “A Paris”, indicazione tipica degli orologi prodotti a Parigi nel XIX secolo. Particolarmente raffinate le lancette traforate in stile francese e la lancetta dei minuti con caratteristico terminale a stella, elementi riconducibili al gusto dell’epoca Restaurazione / Carlo X, circa 1820–1840.\n\nLa struttura è composta da una base in marmo bianco con inserti decorativi in bronzo, colonne in marmo nero e bianco ed elaborati elementi ornamentali in bronzo dorato. Completano la decorazione sottili catene sospese con piccole nappine, fregi applicati alle colonne e alla base e un importante elemento floreale in bronzo dorato posto sulla sommità.\n\nSul retro è visibile il classico movimento francese “Paris”, di forma rotonda e realizzato in ottone, protetto da uno sportello con vetro. All’interno è presente la campana per il rintocco delle ore, caratteristica degli orologi francesi da camino dell’epoca.","description_en":"French “A Paris” clock in white and black marble, enriched with gilt-bronze mounts.","description_fr":"Pendule française « A Paris » en marbre blanc et noir, ornée de bronzes dorés.","images":["assets/images/A006/A006-01.webp","assets/images/A006/A006-02.webp","assets/images/A006/A006-03.webp","assets/images/A006/A006-04.webp","assets/images/A006/A006-05.webp","assets/images/A006/A006-06.webp","assets/images/A006/A006-07.webp","assets/images/A006/A006-08.webp","assets/images/A006/A006-09.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XIX secolo, circa 1820–1860"},{"label":"Periodo stilistico","value":"Restaurazione / Carlo X"},{"label":"Stile","value":"Neoclassico / Luigi XVI"},{"label":"Origine","value":"Francia, Parigi"},{"label":"Materiale","value":"Marmo bianco, marmo nero, bronzo dorato, ottone e smalto"},{"label":"Movimento","value":"Movimento meccanico francese “Paris” con campana per il rintocco delle ore"},{"label":"Quadrante","value":"Smalto bianco con numeri arabi e dicitura “A Paris”"}],"epoch_it":"XIX secolo, circa 1820–1860","style_it":"Restaurazione / Carlo X","material_it":"Marmo bianco, marmo nero, bronzo dorato, ottone e smalto"},"A007":{"category_key":"seating","title_it":"Set di 6 sedie laccate e dorate in stile Luigi XVI","title_en":"Set of Six Italian Louis XVI Style Chairs","title_fr":"Suite de six chaises italiennes de style Louis XVI","category_it":"Sedute e salotti","category_en":"Seating","category_fr":"Sièges","dimensions":"H 93 × L 50 × P 46 cm circa, ciascuna","description_it":"Elegante set di sei sedie in legno intagliato, laccato verde salvia e dorato, realizzate in stile Luigi XVI.\n\nLe sedie presentano schienale ovale sormontato da un motivo floreale intagliato e dorato, gambe anteriori tornite e scanalate e fascia della seduta decorata con motivi a rilievo dorati. La laccatura verde, impreziosita dai dettagli in oro, conferisce all’insieme un carattere raffinato e decorativo.\n\nSedute e schienali sono rivestiti in tessuto nei toni dell’ocra, decorato con composizioni floreali ricamate coordinate. La passamaneria chiara rifinisce il perimetro dell’imbottitura.\n\nLe fotografie del retro e della parte inferiore mostrano la struttura lignea e il sistema tradizionale di sostegno della seduta con fasce intrecciate.\n\nIl set conserva evidenti tracce del tempo e dell’uso, con usure, abrasioni e mancanze della laccatura e della doratura, piccole fessurazioni e difetti localizzati della struttura e degli elementi decorativi. Tali caratteristiche sono documentate nelle fotografie di dettaglio e risultano coerenti con l’età e l'utilizzo degli arredi.","description_en":"Set of six Italian Louis XVI style chairs, green-painted and upholstered in Cannetta Milano floral needlework.","description_fr":"Suite de six chaises italiennes de style Louis XVI, laquées vert et garnies d’une broderie florale Cannetta Milan.","images":["assets/images/A007/A007-01.webp","assets/images/A007/A007-02.webp","assets/images/A007/A007-03.webp","assets/images/A007/A007-04.webp","assets/images/A007/A007-05.webp","assets/images/A007/A007-06.webp","assets/images/A007/A007-07.webp","assets/images/A007/A007-08.webp","assets/images/A007/A007-09.webp","assets/images/A007/A007-10.webp","assets/images/A007/A007-11.webp","assets/images/A007/A007-12.webp","assets/images/A007/A007-13.webp","assets/images/A007/A007-14.webp","assets/images/A007/A007-15.webp","assets/images/A007/A007-16.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XIX–XX secolo, da verificare"},{"label":"Stile","value":"Luigi XVI"},{"label":"Lavorazione","value":"legno intagliato, laccato e dorato"},{"label":"Materiale","value":"legno, tessuto, imbottitura e passamaneria"}],"epoch_it":"XIX–XX secolo, da verificare","style_it":"Luigi XVI","material_it":"legno, tessuto, imbottitura e passamaneria"},"A008":{"category_key":"decorative_panels","title_it":"Insieme di cinque pannelli decorativi dipinti con paesaggi","title_en":"Important Set of Five Decorative Painted Landscape Panels","title_fr":"Important ensemble de cinq panneaux décoratifs peints de paysages","category_it":"Pannelli decorativi","category_en":"Decorative Panels","category_fr":"Panneaux décoratifs","dimensions":"Da misurare","description_it":"Insieme decorativo composto da cinque pannelli dipinti, costituito da un grande pannello centrale e quattro elementi laterali più stretti, originariamente concepiti per l’inserimento in porte, boiserie o rivestimenti decorativi.\n\nI pannelli sono realizzati con la tecnica del succo d’erba o tempera magra e raffigurano raffinati paesaggi di gusto romantico, con alberi, vegetazione, corsi d’acqua e vedute campestri. Le composizioni sono eseguite prevalentemente nei toni del verde, del bruno e dell’azzurro, su un delicato fondo grigio-verde.\n\nOgni scena è racchiusa entro un’elegante cornice ornamentale dipinta, caratterizzata da volute, elementi vegetali e decori di gusto rocaille. I quattro pannelli verticali, stretti e slanciati, creano una piacevole continuità decorativa, mentre il pannello di maggiori dimensioni presenta una veduta paesaggistica più ampia e articolata.\n\nL’insieme, di notevole impatto scenografico e dalle dimensioni monumentali, è particolarmente adatto alla realizzazione di una boiserie, all’inserimento in porte o armadiature oppure all’utilizzo dei singoli pannelli come elementi decorativi a parete.","description_en":"Set of five hand-painted decorative panels: one monumental lake landscape and four narrow vertical panels originally used as decorative doors, all with coordinated landscapes and trompe-l'œil ornamental borders.","description_fr":"Ensemble de cinq panneaux décoratifs peints à la main : un grand paysage lacustre et quatre panneaux verticaux étroits, autrefois utilisés comme portes, avec bordures en trompe-l’œil.","images":["assets/images/A008/A008-01.webp","assets/images/A008/A008-02.webp","assets/images/A008/A008-03.webp","assets/images/A008/A008-04.webp","assets/images/A008/A008-05.webp","assets/images/A008/A008-06.webp","assets/images/A008/A008-07.webp","assets/images/A008/A008-08.webp","assets/images/A008/A008-09.webp","assets/images/A008/A008-10.webp","assets/images/A008/A008-11.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"da verificare"},{"label":"Stile","value":"gusto rocaille / Luigi XV"},{"label":"Tecnica","value":"pittura decorativa su pannello"},{"label":"Soggetto","value":"paesaggi alberati e vedute campestri"},{"label":"Composizione","value":"5 pannelli totali — 1 grande e 4 stretti"}],"epoch_it":"da verificare","style_it":"gusto rocaille / Luigi XV"},"A009":{"category_key":"lighting","title_it":"Grande applique estensibile a fisarmonica in metallo lavorato","title_en":"Large Adjustable Wrought Iron Scissor Wall Lamp","title_fr":"Grande applique murale extensible en fer forgé","category_it":"Illuminazione","category_en":"Lighting","category_fr":"Luminaires","dimensions":"Da misurare","description_it":"Grande e scenografica applique da parete caratterizzata da una struttura estensibile a fisarmonica in ferro battuto, che consente di allungare o richiudere il braccio modificandone considerevolmente la sporgenza dalla parete.\n\nLa struttura è composta da una successione di elementi metallici incrociati e snodati, impreziositi da numerose applicazioni a forma di rosetta in corrispondenza delle articolazioni. La lavorazione del metallo e la calda patina bruno-bronzea conferiscono alla lampada un marcato carattere decorativo.\n\nAll'estremità del braccio, un elemento sagomato sostiene tramite anelli un ampio paralume tronco-conico in tonalità beige, rifinito lungo i bordi.\n\nParticolarmente interessante per le generose dimensioni e per l'originale meccanismo estensibile, l'applique costituisce un complemento d'arredo di forte presenza, adatto a studi, biblioteche, soggiorni e ambienti di gusto classico o eclettico.","description_en":"Large adjustable wrought iron wall lamp with an accordion scissor mechanism and floral details at the joints. A functional and striking decorative piece.","description_fr":"Grande applique murale extensible en fer forgé, dotée d’un mécanisme en accordéon et de détails floraux aux articulations. Une pièce fonctionnelle et décorative de caractère.","images":["assets/images/A009/A009-01.webp","assets/images/A009/A009-02.webp","assets/images/A009/A009-03.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XX secolo"},{"label":"Tipologia","value":"applique da parete estensibile a fisarmonica"},{"label":"Materiale","value":"ferro battuto"},{"label":"Finitura","value":"patina bruno-bronzea"},{"label":"Decorazione","value":"rosette floreali sugli snodi"},{"label":"Paralume","value":"tessuto beige"}],"epoch_it":"XX secolo","material_it":"ferro battuto"},"A010":{"category_key":"furniture","title_it":"Scrivania direzionale di Osvaldo Borsani per Tecno modello T95","title_en":"Osvaldo Borsani T95 Executive Desk for Tecno","title_fr":"Bureau de direction T95 d’Osvaldo Borsani pour Tecno","category_it":"Mobili","category_en":"Furniture","category_fr":"Mobilier","dimensions":"Da misurare","description_it":"Grande scrivania direzionale italiana di Osvaldo Borsani per Tecno, proveniente dalla sede di via Monte Napoleone a Milano.\n\nL’ampio piano rettangolare in legno, dalle calde tonalità brune, è sostenuto da una struttura in metallo composta da due elementi a tre piedi: uno dotato di cassettiera girevole e l’altro provvisto di un piano di appoggio anch’esso girevole.\n\nQueste soluzioni funzionali e dinamiche testimoniano la particolare attenzione di Borsani per l’ergonomia, la versatilità e l’innovazione tecnica.\n\nIl piano, di dimensioni generose, offre un’ampia superficie di lavoro. Il raffinato contrasto tra il legno e gli elementi metallici conferisce alla scrivania un aspetto sobrio, elegante e rappresentativo, tipico di un arredo importante di alto design italiano.","description_en":"Large T95 executive desk designed by Osvaldo Borsani for Tecno, originally from offices on Via Monte Napoleone in Milan. Its broad rectangular wooden top rests on two three-footed metal structures: one incorporates a rotating drawer unit, while the other carries a pivoting auxiliary surface.","description_fr":"Grand bureau de direction modèle T95 dessiné par Osvaldo Borsani pour Tecno, provenant de bureaux situés via Monte Napoleone à Milan. Son vaste plateau rectangulaire en bois repose sur deux structures métalliques tripodes : l’une intègre un caisson pivotant et l’autre un plateau auxiliaire orientable.","images":["assets/images/A010/A010-01.webp","assets/images/A010/A010-02.webp","assets/images/A010/A010-03.webp","assets/images/A010/A010-04.webp"],"status":"available","specs_it":[{"label":"Designer","value":"Osvaldo Borsani"},{"label":"Produttore","value":"Tecno"},{"label":"Modello","value":"T95"},{"label":"Epoca","value":"seconda metà del XX secolo"},{"label":"Provenienza","value":"via Monte Napoleone, Milano"},{"label":"Materiali","value":"legno e metallo"}],"epoch_it":"seconda metà del XX secolo","material_it":"legno e metallo","style_it":"Design italiano moderno"},"A011":{"category_key":"furniture","title_it":"Grande libreria italiana su misura in legno con basi chiuse","title_en":"Large Bespoke Italian Wooden Bookcase","title_fr":"Grande bibliothèque italienne sur mesure en bois","category_it":"Mobili","category_en":"Furniture","category_fr":"Mobilier","dimensions":"Da misurare","description_it":"Importante libreria italiana realizzata su misura in legno, concepita per arredare un ampio studio o una biblioteca privata.\n\nLa composizione si sviluppa a tutta altezza ed è caratterizzata nella parte superiore da numerosi ripiani a giorno, disposti regolarmente per accogliere un'importante collezione di libri. La parte inferiore è invece costituita da una successione di capienti basi contenitore chiuse da ante, integrate armoniosamente nella struttura.\n\nIl disegno lineare ed essenziale mette in risalto le calde tonalità del legno e conferisce alla libreria un aspetto elegante e senza tempo. La realizzazione su misura permette di sfruttare l'intera parete, creando un insieme architettonico di notevole presenza e grande capacità contenitiva.\n\nUn arredo particolarmente indicato per biblioteca, studio professionale, ufficio, soggiorno o grande ambiente di rappresentanza.","description_en":"Impressive full-wall bespoke bookcase with numerous open shelves and a spacious closed-door base, ideal for a private library or executive study.","description_fr":"Importante bibliothèque murale réalisée sur mesure, avec de nombreuses étagères ouvertes et une base spacieuse à portes, idéale pour une bibliothèque privée ou un bureau.","images":["assets/images/A011/A011-01.webp","assets/images/A011/A011-02.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"seconda metà del XX secolo"},{"label":"Provenienza","value":"Italia"},{"label":"Tipologia","value":"grande libreria su misura / biblioteca"},{"label":"Materiale","value":"legno"},{"label":"Struttura","value":"ripiani a giorno e basi chiuse con ante"}],"epoch_it":"seconda metà del XX secolo","material_it":"legno"},"A012":{"category_key":"mirrors","title_it":"Grande specchio italiano in legno intagliato e dorato in stile Rocaille","title_en":"Large Italian Rocaille-Style Carved and Giltwood Mirror","title_fr":"Grand miroir italien de style rocaille en bois sculpté et doré","category_it":"Specchi","category_en":"Mirrors","category_fr":"Miroirs","dimensions":"Da misurare","description_it":"Grande specchio italiano in legno intagliato e dorato, caratterizzato da una ricca decorazione di gusto Rocaille.\n\nLa cornice, fortemente sagomata e di notevole impatto decorativo, è percorsa da elaborate volute, riccioli, elementi fogliacei e motivi a conchiglia. La grande cimasa presenta un'articolata composizione di volute contrapposte, riprese lungo i montanti laterali e nella parte inferiore della cornice.\n\nLa doratura, con variazioni di tonalità e leggere tracce di patina, enfatizza la profondità dell'intaglio e il movimento della decorazione.\n\nEsemplare particolarmente scenografico, di grandi dimensioni, riconducibile per linguaggio ornamentale alla tradizione Rocaille italiana.","description_en":"Grand statement mirror with a richly carved and gilded wooden frame, decorated with scrolls, foliage and an elaborate Rocaille-style crest.","description_fr":"Grand miroir spectaculaire à cadre en bois richement sculpté et doré, orné de volutes, feuillages et d’un important fronton de goût rocaille.","images":["assets/images/A012/A012-01.webp"],"status":"available","specs_it":[]},"A013":{"category_key":"lighting","title_it":"Coppia di appliques italiane a due luci in metallo dorato con pendenti sfaccettati","title_en":"Pair of Two-Light Gilt-Bronze and Crystal Wall Sconces","title_fr":"Paire d'appliques à deux lumières en bronze doré et cristal","category_it":"Illuminazione","category_en":"Lighting","category_fr":"Luminaires","dimensions":"Da misurare","description_it":"Elegante coppia di appliques italiane a due luci, caratterizzate da una struttura in metallo dorato e da una ricca decorazione di pendenti trasparenti sfaccettati, presumibilmente in cristallo.\n\nCiascuna applique presenta una placca centrale lavorata con motivi ornamentali e fogliacei, dalla quale si sviluppano due bracci sinuosi. Le luci sono accompagnate da bobeches sagomate in vetro trasparente e da numerose gocce pendenti di diverse forme e dimensioni, che conferiscono all'insieme luminosità e movimento.\n\nIl disegno dei bracci, le volute e la decorazione vegetale richiamano il gusto Luigi XV e rocaille, reinterpretato secondo la tradizione dell'illuminazione decorativa italiana del Novecento.\n\nUna coppia elegante e scenografica, particolarmente adatta ai lati di uno specchio o di un dipinto, sopra una console oppure come illuminazione decorativa per ingresso, salone o camera da letto.","description_en":"Elegant pair of two-arm wall sconces with gilt-bronze frames, shaped glass drip pans and abundant faceted crystal drops.","description_fr":"Élégante paire d’appliques à deux bras, en bronze doré, avec bobèches en verre moulé et riche pendeloquerie en cristal taillé.","images":["assets/images/A013/A013-01.webp","assets/images/A013/A013-02.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XX secolo"},{"label":"Provenienza","value":"Italia"},{"label":"Stile","value":"Luigi XV / gusto rocaille"},{"label":"Materiali","value":"metallo dorato, vetro e pendenti trasparenti sfaccettati in cristallo"},{"label":"Tipologia","value":"coppia di appliques a due luci"}],"epoch_it":"XX secolo","style_it":"Luigi XV / gusto rocaille","material_it":"metallo dorato, vetro e pendenti trasparenti sfaccettati in cristallo"},"A014":{"category_key":"paintings","title_it":"Battaglia di Ponte Milvio, attribuita al Cavalier d’Arpino","title_en":"The Battle of the Milvian Bridge, attributed to Cavaliere d’Arpino","title_fr":"La Bataille du pont Milvius, attribuée au Cavalier d’Arpin","category_it":"Dipinti","category_en":"Old Master Paintings","category_fr":"Peintures anciennes","dimensions":"H 108 × L 255 cm","description_it":"Imponente dipinto raffigurante la Battaglia di Ponte Milvio, attribuito a Giuseppe Cesari, detto il Cavalier d’Arpino (Arpino, 1568 – Roma, 1640).\n\nLa vasta composizione raffigura lo scontro tra gli eserciti di Costantino e Massenzio, sviluppato attraverso una fitta successione di cavalieri, soldati, cavalli e figure cadute, con un intenso senso di movimento e drammaticità. Nella parte superiore, figure angeliche emergono nel cielo sopra il campo di battaglia.\n\nL'opera riveste particolare interesse documentario in quanto risulta pubblicata come Fig. 13 con la didascalia: «Cavalier d’Arpino (attribuita a), Battaglia di Ponte Milvio. Milano, collezione privata». Il relativo testo critico mette la composizione in relazione con l’attività del Cavalier d’Arpino e riferisce che Federico Zeri considerava la ripresa dell’opera «diretta, grandiosa, rielaborata e meditata».\n\nLa pubblicazione colloca l'opera negli anni finali dell'attività dell'artista, indicativamente tra il 1635 e il 1640.\n\nIl dipinto è conservato entro un'ampia cornice dorata modanata, coerente con il carattere monumentale della composizione.","description_en":"Monumental oil on canvas depicting the Battle of the Milvian Bridge, published as a work attributed to Cavaliere d’Arpino and formerly in a Milanese private collection.","description_fr":"Monumentale huile sur toile représentant la Bataille du pont Milvius, publiée comme œuvre attribuée au Cavalier d’Arpin et provenant d’une collection privée milanaise.","subtitle_it":"Opera pubblicata come attribuita a Giuseppe Cesari, detto il Cavalier d’Arpino","subtitle_en":"Published as a work attributed to Giuseppe Cesari, called Cavaliere d’Arpino","subtitle_fr":"Œuvre publiée comme attribuée à Giuseppe Cesari, dit le Cavalier d’Arpin","images":["assets/images/A014/A014-01.webp","assets/images/A014/A014-02.webp","assets/images/A014/A014-03.webp","assets/images/A014/A014-04.webp","assets/images/A014/A014-05.webp","assets/images/A014/A014-06.webp"],"status":"available","special_request_it":"Richiedi informazioni e documentazione sull’opera","special_request_en":"Request information and documentation about the work","special_request_fr":"Demander des informations et la documentation sur l’œuvre","detail_sections_it":[{"title":"Descrizione storico-artistica","paragraphs":["Monumentale composizione di battaglia sviluppata in formato orizzontale, animata da una moltitudine di cavalieri, soldati, cavalli impennati, figure cadute e gruppi in combattimento. La scena è tradizionalmente identificata con la vittoria di Costantino su Massenzio presso Ponte Milvio.","La costruzione narrativa è dominata dal movimento concitato delle figure e dei cavalli, dalle armature all’antica, dagli elmi crestati e dalle insegne militari. Nella parte superiore compaiono figure alate in volo; sullo sfondo si distinguono rilievi montuosi e masse di armati.","La tavolozza, fondata su bruni, rossi, verdi e accenti dorati, e il forte impianto chiaroscurale collocano l’opera nel linguaggio della grande pittura storica romana."]},{"title":"Pubblicazione e attribuzione","paragraphs":["L’opera è riprodotta in una pubblicazione specialistica come «Fig. 13 – Cavalier d’Arpino (attribuita a), Battaglia di Ponte Milvio. Milano, collezione privata».","Nel testo, la composizione viene posta in rapporto con la Battaglia di Costantino. Sono richiamate le osservazioni di Arnauld Brejon de Lavergnée sull’«accentuazione del ritmo» e sulla «molteplicità di movimenti», nonché il giudizio di Federico Zeri, secondo il quale la ripresa del Cavalier d’Arpino sarebbe stata «diretta, grandiosa, rielaborata e meditata».","La pagina illustrata è riprodotta nella galleria fotografica. Il riferimento bibliografico completo e l’ulteriore documentazione sono disponibili su richiesta."]},{"title":"Rapporto con la tradizione raffaellesca","paragraphs":["Il dipinto riprende la celebre invenzione della Battaglia di Costantino, sviluppando la scena con modifiche, spostamenti e rielaborazioni compositive. La pubblicazione sottolinea il rapporto con prototipi creati da Raffaello e dalla sua cerchia.","La formulazione pubblicata è «attribuita a» Cavalier d’Arpino; pertanto il sito riporta fedelmente questa qualifica, senza trasformarla in un’attribuzione definitiva."]},{"title":"Tecnica, cornice e conservazione","paragraphs":["Olio su tela entro grande cornice lignea modanata e dorata. Dalle fotografie si osservano craquelure, patina e segni del tempo compatibili con l’età, oltre a usure della doratura.","La valutazione dello stato conservativo richiede un esame diretto. Fotografie del retro, del telaio, di eventuali etichette e una relazione conservativa potranno integrare la documentazione."]},{"title":"Provenienza e documentazione","paragraphs":["Collezione privata italiana di famiglia; la pubblicazione indica Milano, collezione privata.","Sono disponibili su richiesta la riproduzione bibliografica e ulteriori informazioni relative all’opera."]}],"detail_sections_en":[{"title":"Art-historical description","paragraphs":["A monumental horizontal battle composition animated by horsemen, soldiers, rearing horses, fallen figures and densely intertwined groups. The scene is traditionally identified with Constantine’s victory over Maxentius at the Milvian Bridge.","The narrative is driven by the vigorous movement of figures and horses, classical armour, crested helmets and military standards. Winged figures appear above, while mountains and massed troops recede into the distance."]},{"title":"Publication and attribution","paragraphs":["The work is reproduced in a specialist publication as “Fig. 13 – Cavaliere d’Arpino (attributed to), Battle of the Milvian Bridge. Milan, private collection.”","The text relates the composition to the Battle of Constantine and cites comments by Arnauld Brejon de Lavergnée and Federico Zeri. The published qualification is “attributed to” and is retained exactly on this website.","The illustrated publication page appears in the image gallery. Full bibliographic details and further documentation are available on request."]},{"title":"Technique and condition","paragraphs":["Oil on canvas in a large moulded and gilded wooden frame. Photographs show craquelure, age-related patina and wear to the gilding. A direct inspection is required for a formal condition assessment."]},{"title":"Provenance","paragraphs":["Private Italian family collection; the publication records the work in a Milan private collection."]}],"detail_sections_fr":[{"title":"Description historico-artistique","paragraphs":["Monumentale composition de bataille au format horizontal, animée de cavaliers, soldats, chevaux cabrés, figures tombées et groupes étroitement mêlés. La scène est traditionnellement identifiée à la victoire de Constantin sur Maxence au pont Milvius.","Le récit est porté par le mouvement vigoureux des figures et des chevaux, les armures à l’antique, les casques à crête et les enseignes militaires. Des figures ailées apparaissent dans le ciel, tandis que montagnes et troupes se déploient à l’arrière-plan."]},{"title":"Publication et attribution","paragraphs":["L’œuvre est reproduite dans une publication spécialisée sous la légende : « Fig. 13 – Cavalier d’Arpin (attribuée à), Bataille du pont Milvius. Milan, collection privée ».","Le texte met la composition en relation avec la Bataille de Constantin et cite Arnauld Brejon de Lavergnée ainsi que Federico Zeri. La qualification publiée « attribuée à » est fidèlement conservée sur ce site.","La page illustrée figure dans la galerie. Les références bibliographiques complètes et la documentation complémentaire sont disponibles sur demande."]},{"title":"Technique et état","paragraphs":["Huile sur toile dans un grand cadre en bois mouluré et doré. Les photographies montrent une craquelure, une patine liée à l’âge et des usures de la dorure. Un examen direct est nécessaire pour établir un constat d’état."]},{"title":"Provenance","paragraphs":["Collection familiale privée italienne ; la publication situe l’œuvre dans une collection privée milanaise."]}],"specs_it":[{"label":"Autore","value":"attribuito a Giuseppe Cesari, detto il Cavalier d’Arpino"},{"label":"Soggetto","value":"Battaglia di Ponte Milvio"},{"label":"Epoca","value":"1635–1640 circa, secondo la pubblicazione"},{"label":"Tecnica","value":"olio su tela"},{"label":"Provenienza documentata nella pubblicazione","value":"Milano, collezione privata"},{"label":"Bibliografia","value":"pubblicato e riprodotto come Fig. 13"},{"label":"Riferimenti critici","value":"Federico Zeri citato nel testo relativo all’opera"},{"label":"Cornice","value":"legno dorato"}],"epoch_it":"1635–1640 circa, secondo la pubblicazione"},"A015":{"category_key":"architectural","title_it":"Coppia di porte italiane in legno con pannelli intagliati a raggiera","title_en":"Pair of Italian Carved Wood Doors with Sunburst Panels","title_fr":"Paire de portes italiennes en bois à panneaux sculptés en rayons","category_it":"Elementi architettonici","category_en":"Architectural Elements","category_fr":"Éléments architecturaux","dimensions":"Da misurare","description_it":"Interessante coppia di porte italiane in legno, caratterizzate da una struttura a riquadri e da un'elegante decorazione geometrica intagliata. Ciascuna porta presenta ampi pannelli lavorati con fitte scanalature verticali, intervallati da un caratteristico pannello centrale con motivo intagliato a raggiera.\n\nCiascuna anta presenta due ampi pannelli rettangolari lavorati con fitte scanalature verticali, separati da un pannello centrale intagliato con un motivo a raggiera, sviluppato simmetricamente attorno a un piccolo elemento ovale.\n\nLe superfici conservano una calda tonalità bruna e una piacevole patina, con tracce d'uso e irregolarità coerenti con l'età. Sono presenti inoltre le antiche bocchette metalliche delle serrature, differenti nelle due ante, che contribuiscono al fascino dell'insieme.\n\nLa coppia può essere utilizzata come elemento architettonico, come porta a doppio battente oppure reinterpretata come pannellatura decorativa in un progetto d'interni.","description_en":"Pair of Italian solid-wood interior doors with fluted panels and finely carved central sunburst motifs.","description_fr":"Paire de portes intérieures italiennes en bois massif, à panneaux cannelés et motifs rayonnants sculptés. Ferrures anciennes et belle patine d’usage.","images":["assets/images/A015/A015-01.webp"],"status":"available","detail_sections_it":[{"title":"Perché questo pezzo è speciale","paragraphs":["La decorazione geometrica a raggiera, la costruzione in massello e la presenza della ferramenta antica trasformano queste porte in veri elementi architettonici, particolarmente adatti a restauri e progetti d’interior design."]}],"detail_sections_en":[{"title":"Why this piece is special","paragraphs":["The carved sunburst decoration, solid construction and surviving period hardware make these doors distinctive architectural elements, ideal for restoration and interior-design projects."]}],"detail_sections_fr":[{"title":"Pourquoi cette pièce est spéciale","paragraphs":["Le décor rayonnant sculpté, la construction massive et les ferrures anciennes font de ces portes de véritables éléments architecturaux, adaptés aux restaurations et aux projets d’architecture intérieure."]}],"specs_it":[{"label":"Epoca","value":"XIX secolo"},{"label":"Tipologia","value":"coppia di ante / elementi architettonici"},{"label":"Materiale","value":"legno, ferramenta metallica"},{"label":"Decorazione","value":"pannelli scanalati e motivo centrale intagliato a raggiera"}],"epoch_it":"XIX secolo","material_it":"legno, ferramenta metallica"},"A016":{"category_key":"seating","title_it":"Divano in legno intagliato con braccioli a voluta e rivestimento floreale","title_en":"Italian Carved Walnut Sofa with Scroll Arms","title_fr":"Canapé italien en noyer sculpté à accotoirs en volute","category_it":"Sedute e salotti","category_en":"Seating","category_fr":"Sièges","dimensions":"Da misurare","description_it":"Elegante divano a tre posti caratterizzato da un'importante struttura in legno intagliato e da ampi braccioli sagomati a voluta.\n\nLo schienale presenta un profilo mosso e sinuoso, impreziosito nella parte superiore da una cimasa centrale intagliata con motivi vegetali, volute e piccoli elementi floreali. Particolarmente scenografici i sostegni laterali dei braccioli, modellati con grandi riccioli contrapposti che proseguono fino alla base.\n\nLa fascia inferiore è lineare e termina lateralmente in robusti piedi riccamente intagliati, completati da motivi a voluta e decorazioni vegetali.\n\nSeduta, schienale e braccioli sono interamente imbottiti e rivestiti in tessuto a motivo floreale nei delicati toni del rosa, verde e avorio, creando un piacevole contrasto con la calda tonalità del legno.\n\nUn arredo di forte presenza decorativa, ispirato ai modelli ottocenteschi e particolarmente indicato per salone, ingresso, studio o ambiente di gusto classico ed eclettico.","description_en":"Elegant Italian carved-walnut sofa with a shaped crest, generous scroll arms and richly carved feet. Later floral upholstery.","description_fr":"Élégant canapé italien en noyer sculpté, à fronton chantourné, grands accotoirs en volute et pieds richement travaillés. Tissu floral postérieur.","images":["assets/images/A016/A016-01.webp","assets/images/A016/A016-02.webp"],"status":"available","detail_sections_it":[{"title":"Perché questo pezzo è speciale","paragraphs":["L’ampiezza dei braccioli scolpiti, la cimasa ondulata e la forte presenza della struttura lignea conferiscono al divano un carattere scenografico, adatto sia ad ambienti storici sia a interni contemporanei."]}],"detail_sections_en":[{"title":"Why this piece is special","paragraphs":["Its deeply carved scroll arms, shaped crest and substantial wooden frame give the sofa a striking presence suited to historic and contemporary interiors alike."]}],"detail_sections_fr":[{"title":"Pourquoi cette pièce est spéciale","paragraphs":["Les grands accotoirs sculptés, le fronton ondulé et la forte présence de la structure en bois donnent au canapé un caractère spectaculaire."]}],"specs_it":[{"label":"Epoca","value":"XIX secolo"},{"label":"Stile","value":"gusto Luigi Filippo / revival ottocentesco"},{"label":"Tipologia","value":"divano a tre posti"},{"label":"Materiali","value":"legno intagliato, imbottitura e tessuto"},{"label":"Decorazione","value":"volute, riccioli e motivi vegetali intagliati"}],"epoch_it":"XIX secolo","style_it":"gusto Luigi Filippo / revival ottocentesco","material_it":"legno intagliato, imbottitura e tessuto"},"A017":{"category_key":"furniture","title_it":"Grande console rustica italiana in legno massello","title_en":"Large Italian Rustic Solid-Wood Console","title_fr":"Grande console rustique italienne en bois massif","category_it":"Mobili","category_en":"Consoles","category_fr":"Consoles","dimensions":"Da misurare","description_it":"Particolare console in legno caratterizzata da una struttura solida e lineare e da un ampio pannello posteriore lavorato a intreccio, in paglia di Vienna.\n\nIl mobile presenta un piano rettangolare spesso e leggermente aggettante, delimitato da una semplice cornice modanata. La struttura è sostenuta da robusti montanti squadrati, collegati lateralmente da traverse orizzontali.\n\nL'elemento più caratteristico è il grande pannello centrale a trama fitta e regolare, che crea un piacevole contrasto materico con la struttura lignea.\n\nLa superficie del legno conserva una marcata patina, con variazioni cromatiche, usure, graffi e irregolarità che ne sottolineano il carattere vissuto e l'aspetto autenticamente rustico.\n\nUn mobile versatile e decorativo, utilizzabile come console, elemento da ingresso o complemento d'arredo in ambienti rustici, country o eclettici.","description_en":"Large Italian solid-wood console with architectural proportions, a thick top, robust rectangular legs and a pronounced aged patina.","description_fr":"Grande console italienne en bois massif, aux proportions architecturales, avec plateau épais, pieds robustes et patine ancienne marquée.","images":["assets/images/A017/A017-01.webp","assets/images/A017/A017-02.webp"],"status":"available","detail_sections_it":[{"title":"Perché questo pezzo è speciale","paragraphs":["La semplicità della costruzione mette in primo piano la materia e i segni del tempo. È un mobile autentico e versatile, utilizzabile come console, banco espositivo o tavolo da parete."]}],"detail_sections_en":[{"title":"Why this piece is special","paragraphs":["Its restrained construction highlights the material and natural signs of age. It is an authentic and versatile piece for use as a console, display counter or wall table."]}],"detail_sections_fr":[{"title":"Pourquoi cette pièce est spéciale","paragraphs":["La sobriété de la construction met en valeur la matière et les traces du temps. Une pièce authentique et polyvalente."]}],"specs_it":[{"label":"Epoca","value":"XIX – inizi XX secolo"},{"label":"Tipologia","value":"console"},{"label":"Materiale","value":"legno e pannello intrecciato, presumibilmente paglia di Vienna"},{"label":"Stile","value":"rustico / tradizionale"}],"epoch_it":"XIX – inizi XX secolo","style_it":"rustico / tradizionale","material_it":"legno e pannello intrecciato, presumibilmente paglia di Vienna"},"A018":{"category_key":"furniture","title_it":"Scrivania italiana in noce con piano in pelle e due cassetti","title_en":"Italian Walnut Desk with Leather Writing Surface and Two Drawers","title_fr":"Bureau italien en noyer à plateau gainé de cuir et deux tiroirs","category_it":"Mobili","category_en":"Desks","category_fr":"Bureaux","dimensions":"Da misurare","description_it":"Elegante scrivania italiana in legno, caratterizzata da proporzioni equilibrate e da un ampio piano rettangolare con inserto centrale scuro, presumibilmente rivestito in pelle.\n\nLa fascia frontale ospita due cassetti simmetrici, incorniciati da semplici modanature e dotati di pomelli circolari in metallo. La struttura poggia su quattro gambe tornite, impreziosite da anelli modanati e raccordate nella parte inferiore da traverse in legno, che conferiscono stabilità e un piacevole ritmo architettonico all'insieme.\n\nIl legno presenta una calda tonalità bruna e conserva una marcata patina, con usure e variazioni cromatiche che testimoniano l'utilizzo nel tempo. Il contrasto tra il piano scuro e la struttura lignea ne accentua il carattere sobrio ed elegante.\n\nUna scrivania versatile e di piacevole presenza, adatta sia a uno studio classico sia a un ambiente contemporaneo come elemento d'accento.","description_en":"Elegant Italian walnut desk with a dark leather writing surface, two front drawers, turned legs and stabilising stretchers.","description_fr":"Élégant bureau italien en noyer, avec écritoire en cuir sombre, deux tiroirs, pieds tournés et entretoises.","images":["assets/images/A018/A018-01.webp","assets/images/A018/A018-02.webp"],"status":"available","detail_sections_it":[{"title":"Perché questo pezzo è speciale","paragraphs":["Unisce la calda patina del noce alla praticità del piano in pelle e dei due cassetti. Le quattro facce e le proporzioni equilibrate la rendono ideale anche come scrivania da centro stanza."]}],"detail_sections_en":[{"title":"Why this piece is special","paragraphs":["It combines warm walnut patina with the practicality of a leather writing surface and two drawers, making it particularly suitable as a freestanding desk."]}],"detail_sections_fr":[{"title":"Pourquoi cette pièce est spéciale","paragraphs":["Elle associe la patine chaleureuse du noyer à la fonctionnalité d’un plateau en cuir et de deux tiroirs."]}],"specs_it":[{"label":"Epoca","value":"fine XIX – inizi XX secolo"},{"label":"Provenienza","value":"Italia"},{"label":"Tipologia","value":"scrivania a due cassetti"},{"label":"Materiale","value":"legno; piano con inserto in pelle; pomelli in metallo"},{"label":"Struttura","value":"quattro gambe tornite raccordate da traverse"}],"epoch_it":"fine XIX – inizi XX secolo","material_it":"legno; piano con inserto in pelle; pomelli in metallo"},"A019":{"category_key":"furniture","title_it":"Grande vetrina rustica italiana in legno a quattro ante","title_en":"Large Italian Wall-Mounted Glazed Cabinet with Four Doors","title_fr":"Grande vitrine murale italienne à quatre portes","category_it":"Mobili","category_en":"Glazed Cabinets and Bookcases","category_fr":"Vitrines et bibliothèques","dimensions":"Da misurare","description_it":"Grande vetrina italiana in legno, caratterizzata da una costruzione robusta e lineare e da quattro ante frontali vetrate che consentono di lasciare completamente a vista il contenuto interno.\n\nLa struttura presenta montanti squadrati, un'importante cornice superiore leggermente aggettante e una base modanata. L'interno è organizzato con ripiani in legno, offrendo un'ampia superficie per l'esposizione e la conservazione di libri, ceramiche, oggetti da collezione o suppellettili.\n\nParticolarmente interessante la ferramenta metallica, semplice e funzionale, che insieme alla superficie irregolare del legno contribuisce al carattere autenticamente rustico del mobile.\n\nIl legno conserva una marcata patina del tempo, con variazioni cromatiche, usure, graffi e irregolarità che ne valorizzano l'aspetto vissuto.\n\nUn mobile di grande presenza e notevole capacità contenitiva, adatto sia ad ambienti rustici e tradizionali sia a interni contemporanei, dove può essere utilizzato come elemento di contrasto.","description_en":"Large Italian wall-mounted wooden cabinet with four glazed doors and internal shelves. Its restrained design highlights the wood grain and practical storage.","description_fr":"Grande vitrine murale italienne en bois, à quatre portes vitrées et étagères intérieures. Ses lignes sobres mettent en valeur le bois et sa fonctionnalité.","images":["assets/images/A019/A019-01.webp"],"status":"available","detail_sections_it":[{"title":"Perché questo pezzo è speciale","paragraphs":["La grande larghezza e le quattro ante vetrate offrono una notevole capacità espositiva senza appesantire visivamente l’ambiente. Ideale per libri, porcellane e collezioni."]}],"detail_sections_en":[{"title":"Why this piece is special","paragraphs":["Its generous width and four glazed doors provide substantial display capacity without visually overwhelming a room."]}],"detail_sections_fr":[{"title":"Pourquoi cette pièce est spéciale","paragraphs":["Sa grande largeur et ses quatre portes vitrées offrent une importante capacité d’exposition tout en conservant une présence sobre."]}],"specs_it":[{"label":"Epoca","value":"XIX – inizi XX secolo"},{"label":"Provenienza","value":"Italia"},{"label":"Tipologia","value":"vetrina / mobile espositore a quattro ante"},{"label":"Materiale","value":"legno, vetro e ferramenta metallica"}],"epoch_it":"XIX – inizi XX secolo","material_it":"legno, vetro e ferramenta metallica"},"A020":{"category_key":"seating","title_it":"Salotto veneziano in noce con ricami floreali Cannetta Milano","title_en":"Venetian Walnut Salon Suite with Handworked Needlepoint","title_fr":"Salon vénitien en noyer à broderie au petit point","category_it":"Sedute e salotti","category_en":"Salon Suites","category_fr":"Salons","dimensions":"Da misurare","description_it":"Elegante salotto veneziano composto da una panca e quattro poltroncine con braccioli, realizzato in noce e impreziosito da raffinati rivestimenti ricamati da Cannetta Milano.\n\nLe strutture presentano profili sinuosi e armoniosi, con schienali sagomati, braccioli ricurvi, gambe mosse e delicati motivi intagliati. La panca, di proporzioni generose, è caratterizzata da un ampio schienale sagomato con elemento ornamentale centrale e da una fascia inferiore finemente lavorata.\n\nLe quattro poltroncine coordinate riprendono il medesimo disegno della panca, formando un insieme omogeneo e particolarmente scenografico.\n\nDi particolare pregio la decorazione tessile, realizzata con ricchi motivi floreali nei toni del rosa, rosso, verde e avorio, con bouquet di fiori e girali ornamentali. Il ricamo, eseguito da Cannetta Milano, conferisce all'insieme un ulteriore elemento di qualità e interesse.\n\nLe linee mosse, gli intagli e le gambe arcuate richiamano la tradizione dell'arredo veneziano di gusto Luigi XV e rocaille.","description_en":"Salon suite comprising a three-seat sofa and four matching walnut armchairs, upholstered with refined floral handworked needlepoint.","description_fr":"Salon composé d’un canapé trois places et de quatre fauteuils assortis en noyer, garnis d’une fine broderie florale réalisée à la main au petit point.","images":["assets/images/A020/A020-02.webp","assets/images/A020/A020-14.webp"],"status":"available","detail_sections_it":[{"title":"Perché questo pezzo è speciale","paragraphs":["La completezza dell’insieme e l’esteso ricamo floreale a punto cannetta, eseguito a mano sul divano e sulle quattro poltroncine, costituiscono il principale elemento di rarità e pregio."]}],"detail_sections_en":[{"title":"Why this piece is special","paragraphs":["The completeness of the suite and the extensive handworked floral needlepoint covering both the sofa and four armchairs are its principal marks of rarity and quality."]}],"detail_sections_fr":[{"title":"Pourquoi cette pièce est spéciale","paragraphs":["La complétude de l’ensemble et l’importante broderie florale au petit point réalisée à la main constituent ses principaux éléments de rareté."]}],"specs_it":[{"label":"Epoca","value":"XX secolo"},{"label":"Provenienza","value":"Italia"},{"label":"Stile","value":"veneziano, gusto Luigi XV / rocaille"},{"label":"Composizione","value":"1 panca e 4 poltroncine con braccioli"},{"label":"Materiale","value":"noce, imbottitura e tessuto ricamato"},{"label":"Ricamo","value":"Cannetta Milano"}],"epoch_it":"XX secolo","style_it":"veneziano, gusto Luigi XV / rocaille","material_it":"noce, imbottitura e tessuto ricamato"},"A021":{"category_key":"lighting","title_it":"Lampada da soffitto “Lucellino” di Ingo Maurer con lampadine alate","title_en":"Ingo Maurer Ceiling Light with Winged Bulbs","title_fr":"Plafonnier Ingo Maurer à ampoules ailées","category_it":"Illuminazione","category_en":"Designer Lighting","category_fr":"Luminaires design","dimensions":"Da misurare","description_it":"Iconica lampada da soffitto di design firmata Ingo Maurer, caratterizzata dalla celebre interpretazione poetica della lampadina trasformata in un elemento leggero e quasi sospeso grazie alle caratteristiche ali bianche.\n\nLa composizione si sviluppa liberamente nello spazio attraverso numerosi sottili elementi metallici curvilinei che si diramano dal rosone centrale, creando un disegno volutamente irregolare e dinamico. Alle estremità sono disposte le lampadine, ciascuna accompagnata da una coppia di delicate ali decorative.\n\nL'accostamento tra la struttura metallica, i dettagli dorati e le ali bianche crea il caratteristico effetto scenografico e giocoso del linguaggio di Ingo Maurer, nel quale la sorgente luminosa diventa protagonista dell'oggetto.\n\nUna lampada di forte impatto visivo, particolarmente adatta ad ambienti contemporanei, eclettici e a collezioni dedicate al design internazionale del secondo Novecento.\n\nDesigner: Ingo Maurer\nProduzione: Ingo Maurer GmbH","description_en":"Sculptural ceiling light associated with Ingo Maurer, formed by a free, dynamic metal structure carrying numerous bulbs with distinctive white wings. A poetic and playful icon of contemporary lighting design.","description_fr":"Plafonnier sculptural associé à la production d’Ingo Maurer, composé d’une structure métallique libre portant de nombreuses ampoules aux ailes blanches. Une création poétique et ludique du design lumineux contemporain.","images":["assets/images/A021/A021-01.webp","assets/images/A021/A021-02.webp"],"status":"available","detail_sections_it":[{"title":"Perché questo pezzo è speciale","paragraphs":["Le lampadine trasformate in piccoli esseri alati rendono la luce parte di una vera installazione scultorea. L’identificazione del modello e l’originalità dovranno essere confermate tramite etichetta o marchio."]}],"detail_sections_en":[{"title":"Why this piece is special","paragraphs":["The winged bulbs turn the light into a sculptural installation. The exact model and authenticity should be confirmed through its label or maker’s mark."]}],"detail_sections_fr":[{"title":"Pourquoi cette pièce est spéciale","paragraphs":["Les ampoules ailées transforment le luminaire en installation sculpturale. Le modèle exact et l’authenticité devront être confirmés par l’étiquette ou la marque."]}],"specs_it":[{"label":"Designer","value":"Ingo Maurer"},{"label":"Produzione","value":"Ingo Maurer GmbH"},{"label":"Epoca","value":"design contemporaneo / fine XX – XXI secolo"},{"label":"Tipologia","value":"lampada da soffitto a più luci"},{"label":"Materiali","value":"metallo, componenti elettrici e ali decorative"}],"epoch_it":"design contemporaneo / fine XX – XXI secolo","material_it":"metallo, componenti elettrici e ali decorative"},"A022":{"category_key":"seating","title_it":"Grande panca-divano in noce con schienale traforato e seduta ricamata Cannetta Milano","title_en":"Large Walnut Settee with Pierced Back and Needlepoint Seat","title_fr":"Grande banquette en noyer à dossier ajouré et assise brodée","category_it":"Sedute e salotti","category_en":"Seating","category_fr":"Sièges","dimensions":"H 120 × L 200 × P 60 cm","description_it":"Grande ed elegante panca-divano italiana in noce, caratterizzata da un raffinato schienale traforato a giorno e da un’ampia seduta imbottita con ricami floreali realizzati da Cannetta Milano.\n\nLo schienale, particolarmente decorativo, è articolato in una successione di ampi riquadri dal profilo sinuoso, intervallati da tre elementi centrali intrecciati. Piccoli motivi intagliati impreziosiscono i punti di raccordo superiori, conferendo ulteriore eleganza alla struttura.\n\nI braccioli presentano un andamento curvilineo e armonioso, mentre la fascia inferiore della seduta è delicatamente sagomata e sostenuta da gambe mosse. La calda tonalità del noce mette in risalto il disegno leggero e arioso dello schienale.\n\nDi particolare pregio la lunga seduta imbottita, rivestita in tessuto color avorio e decorata con ricami floreali eseguiti da Cannetta Milano. La composizione presenta un grande bouquet centrale affiancato da due motivi floreali più piccoli, nei delicati toni del rosa, rosso, giallo e verde.\n\nLe importanti dimensioni e l’equilibrio tra la struttura traforata e la ricca lavorazione tessile rendono questa panca-divano un arredo di notevole presenza decorativa, ideale per un grande ingresso, salone o ambiente di rappresentanza.","description_en":"Elegant three-seat walnut settee with a broad pierced and shaped back, curving arms and cabriole-style legs. The long seat is upholstered in floral needlepoint.","description_fr":"Élégante banquette trois places en noyer, à grand dossier ajouré et chantourné, accotoirs courbes et pieds galbés. La longue assise est garnie d’une broderie florale.","images":["assets/images/A022/A022-01.webp","assets/images/A022/A022-02.webp"],"status":"available","detail_sections_it":[{"title":"Perché questo pezzo è speciale","paragraphs":["Lo schienale continuo, articolato da cartelle traforate, conferisce alla seduta leggerezza e grande presenza decorativa; il ricamo floreale a cannetta completa l’insieme con una lavorazione artigianale preziosa."]}],"detail_sections_en":[{"title":"Why this piece is special","paragraphs":["Its continuous pierced back gives the settee an unusually light and decorative profile, enhanced by the handworked floral needlepoint seat."]}],"detail_sections_fr":[{"title":"Pourquoi cette pièce est spéciale","paragraphs":["Le dossier continu et ajouré donne à la banquette une silhouette légère et décorative, complétée par la broderie florale de l’assise."]}],"specs_it":[{"label":"Provenienza","value":"Italia"},{"label":"Materiale","value":"noce, imbottitura e tessuto ricamato"},{"label":"Ricamo","value":"Cannetta Milano"},{"label":"Tipologia","value":"grande panca-divano con braccioli e schienale traforato"}],"material_it":"noce, imbottitura e tessuto ricamato"},"A023":{"category_key":"ceramics","title_it":"Coppia di grandi vasi giapponesi in porcellana policroma con scene di corte","title_en":"Pair of Large Japanese Polychrome Vases with Court Scenes","title_fr":"Paire de grands vases japonais polychromes à scènes de cour","category_it":"Ceramiche e porcellane","category_en":"Asian Ceramics","category_fr":"Céramiques asiatiques","dimensions":"H 66 × L max 25 cm; circonferenza max circa 78 cm ciascuno","description_it":"Importante coppia di grandi vasi ornamentali in porcellana policroma, caratterizzati da corpo slanciato a balaustro e ampio collo svasato con bordo ondulato.\n\nLa decorazione, particolarmente ricca, si sviluppa sull’intera superficie alternando grandi riserve figurate con personaggi in abiti tradizionali, scene di paesaggio e architetture, a composizioni floreali nei toni del rosso, blu, verde, rosa e arancio. Dettagli dorati sottolineano alcuni elementi ornamentali e il profilo del bordo superiore.\n\nSul fondo sono presenti caratteri dipinti in rosso, documentati fotograficamente. Sulla base delle sole fotografie non è prudente attribuire con certezza manifattura ed epoca attraverso il marchio; consiglierei quindi di mantenerlo documentato senza tradurlo o attribuirlo finché non viene verificato.\n\nLa coppia presenta un notevole impatto decorativo grazie alle dimensioni, alla forma slanciata e alla vivacità della decorazione policroma.","description_en":"Pair of tall polychrome porcelain vases with flared scalloped rims. Their rich decoration combines courtly figures, landscapes, flowers and geometric ornament. Each bears a red-painted mark requiring further identification.","description_fr":"Paire de grands vases élancés en porcelaine polychrome, à large bord festonné. Le décor associe personnages en costume, paysages, fleurs et motifs géométriques. Marque rouge sous la base, à identifier.","images":["assets/images/A023/A023-01.webp","assets/images/A023/A023-02.webp","assets/images/A023/A023-03.webp","assets/images/A023/A023-04.webp","assets/images/A023/A023-05.webp","assets/images/A023/A023-06.webp"],"status":"available","detail_sections_it":[{"title":"Perché questo pezzo è speciale","paragraphs":["La presenza della coppia, il grande formato e la qualità espressiva dei volti aumentano il valore decorativo. Il marchio sul fondo potrà fornire indicazioni decisive su manifattura ed epoca."]}],"detail_sections_en":[{"title":"Why this piece is special","paragraphs":["Their impressive scale, survival as a pair and expressive painted faces add considerable decorative appeal. The marks may provide decisive information about maker and date."]}],"detail_sections_fr":[{"title":"Pourquoi cette pièce est spéciale","paragraphs":["Le grand format, la conservation en paire et l’expressivité des visages renforcent leur intérêt décoratif. Les marques pourront préciser la manufacture et la datation."]}],"specs_it":[{"label":"Epoca","value":"presumibilmente XX secolo"},{"label":"Stile","value":"gusto orientale / giapponese"},{"label":"Lavorazione","value":"porcellana dipinta e decorata a mano con dettagli dorati"},{"label":"Materiale","value":"porcellana policroma"}],"epoch_it":"presumibilmente XX secolo","style_it":"gusto orientale / giapponese","material_it":"porcellana policroma"},"A024":{"category_key":"ceramics","title_it":"Coppia di grande vasi giapponesi dell’Ottocento con samurai","title_en":"Pair of Large Japanese Covered Vases with Samurai","title_fr":"Paire de grands vases couverts japonais à décor de samouraïs","category_it":"Ceramiche e porcellane","category_en":"Asian Ceramics","category_fr":"Céramiques asiatiques","dimensions":"H 57 × L max 36 cm; circonferenza max circa 103 cm","description_it":"Importante coppia di grandi vasi ornamentali giapponesi dell’Ottocento in porcellana policroma, riccamente decorati a mano e completi dei rispettivi coperchi.\n\nI corpi panciuti presentano ampie riserve figurate con guerrieri samurai in armatura, circondati da rami fioriti e da una fitta ornamentazione policroma nei toni del rosso, blu, arancio e nero, arricchita da dettagli dorati.\n\nDi particolare interesse è la natura pittorica della decorazione: le figure non risultano riprodotte in maniera perfettamente identica o simmetrica. I volti e, in particolare, gli sguardi dei samurai mostrano differenze da un lato all’altro, evidenziando l'esecuzione manuale della decorazione e conferendo individualità alle diverse raffigurazioni.\n\nUlteriori riserve raffigurano uccelli e fiori, alternate a motivi floreali e geometrici che ricoprono estesamente la superficie.\n\nSul fondo sono presenti caratteri orientali dipinti in rosso, documentati fotograficamente, la cui identificazione potrà contribuire a precisare ulteriormente manifattura e datazione.","description_en":"Important pair of large Japanese covered porcelain vases decorated in polychrome enamels and gilt highlights. The principal reserves depict armoured samurai, alternating with birds, flowers and dense ornamental patterns.","description_fr":"Importante paire de grands vases couverts japonais en porcelaine, décorés d’émaux polychromes et d’or. Les réserves principales représentent des samouraïs en armure, alternant avec oiseaux, fleurs et motifs serrés.","images":["assets/images/A024/A024-01.webp","assets/images/A024/A024-02.webp","assets/images/A024/A024-03.webp","assets/images/A024/A024-04.webp","assets/images/A024/A024-05.webp","assets/images/A024/A024-06.webp","assets/images/A024/A024-07.webp"],"status":"available","detail_sections_it":[{"title":"Perché questo pezzo è speciale","paragraphs":["La pittura dei volti e degli sguardi dei samurai è accurata e caratterizzante. La completezza della coppia e la presenza dei coperchi ne rafforzano l’impatto collezionistico."]},{"title":"Condizioni","paragraphs":["Uno dei due coperchi è stato restaurato. Il restauro deve essere fotografato e documentato nel dettaglio."]}],"detail_sections_en":[{"title":"Why this piece is special","paragraphs":["The carefully painted faces and gazes of the samurai are particularly distinctive. Their survival as a complete pair with covers strengthens their collecting appeal."]},{"title":"Condition","paragraphs":["One of the two covers has been restored. The restoration should be photographed and fully documented."]}],"detail_sections_fr":[{"title":"Pourquoi cette pièce est spéciale","paragraphs":["La qualité des visages et des regards des samouraïs est particulièrement remarquable. La conservation de la paire avec ses couvercles renforce son intérêt."]},{"title":"État","paragraphs":["L’un des deux couvercles a été restauré. Cette restauration devra être photographiée et documentée."]}],"specs_it":[{"label":"Epoca","value":"XIX secolo"},{"label":"Provenienza","value":"Giappone"},{"label":"Stile","value":"tradizionale giapponese"},{"label":"Lavorazione","value":"decorazione policroma eseguita a mano con dettagli dorati"},{"label":"Materiale","value":"porcellana"}],"epoch_it":"XIX secolo","style_it":"tradizionale giapponese","material_it":"porcellana"},"A025":{"category_key":"vintage_collectibles","title_it":"Registratore a bobine portatile Grundig TK 42 nella valigia originale","title_en":"Grundig TK 42 Reel-to-Reel Recorder in Its Original Case","title_fr":"Magnétophone à bandes Grundig TK 42 dans sa valise d’origine","category_it":"Vintage e collezionismo","category_en":"Vintage Audio and Design","category_fr":"Audio vintage et design","dimensions":"Da misurare","description_it":"Interessante registratore a bobine vintage Grundig modello TK 42, apparecchio portatile di produzione tedesca risalente agli anni Sessanta, conservato nella caratteristica custodia rigida a valigetta.\n\nIl registratore presenta il tipico design tecnico dell'epoca, con pannello di comando nei toni del grigio, comandi a tasti, manopole di regolazione e alloggiamenti per le bobine. Sul frontale sono chiaramente visibili il marchio Grundig e la sigla del modello TK 42.\n\nLa custodia è rivestita esternamente in materiale scuro, con profili metallici, chiusura centrale e maniglia per il trasporto. L'interno del coperchio presenta il rivestimento originale chiaro.\n\nUn interessante esempio di tecnologia audio domestica del secondo dopoguerra, oggi apprezzabile sia come apparecchio da collezione sia come oggetto decorativo dal caratteristico design vintage.\n\nMarca: Grundig","description_en":"Grundig TK 42 reel-to-reel tape recorder, made in Germany during the 1960s and housed in its original portable case with built-in speakers and mechanical controls. Includes one reel.","description_fr":"Magnétophone à bandes Grundig TK 42, fabriqué en Allemagne dans les années 1960, présenté dans sa valise d’origine avec haut-parleurs intégrés et commandes mécaniques. Une bobine incluse; fonctionnement non testé.","images":["assets/images/A025/A025-01.webp","assets/images/A025/A025-02.webp"],"status":"available","detail_sections_it":[{"title":"Perché questo pezzo è speciale","paragraphs":["Il registratore conserva la valigia, il pannello comandi e l’estetica originale del design industriale tedesco del dopoguerra. Una revisione tecnica e la presenza di accessori originali potrebbero aumentarne l’interesse collezionistico."]}],"detail_sections_en":[{"title":"Why this piece is special","paragraphs":["It retains its original case, control panel and characteristic post-war German industrial design. A technical service and surviving original accessories could enhance its collecting appeal."]}],"detail_sections_fr":[{"title":"Pourquoi cette pièce est spéciale","paragraphs":["Il conserve sa valise, son panneau de commande et l’esthétique du design industriel allemand d’après-guerre. Une révision et des accessoires d’origine pourraient accroître son intérêt."]}],"specs_it":[{"label":"Marca","value":"Grundig"},{"label":"Modello","value":"TK 42"},{"label":"Tipologia","value":"registratore a bobine / magnetofono portatile"},{"label":"Epoca","value":"anni 1960 circa"},{"label":"Provenienza","value":"Germania"},{"label":"Materiali","value":"metallo, materiale plastico, componenti elettronici e custodia rivestita"}],"epoch_it":"anni 1960 circa","material_it":"metallo, materiale plastico, componenti elettronici e custodia rivestita"},"A026":{"category_key":"paintings","title_it":"Paesaggio fiammingo attribuito a David Teniers con monogramma DT","title_en":"Flemish Landscape Attributed to David Teniers, Monogrammed DT","title_fr":"Paysage flamand attribué à David Teniers, monogrammé DT","category_it":"Dipinti","category_en":"Old Master Paintings","category_fr":"Peintures anciennes","dimensions":"H 105 × L 128 cm","description_it":"Suggestivo paesaggio di gusto fiammingo attribuito a David Teniers, caratterizzato da un’ampia veduta campestre animata da piccoli personaggi e da un villaggio immerso nella vegetazione.\n\nLa composizione si sviluppa in profondità attraverso un paesaggio articolato: in primo piano un sentiero attraversa una zona boscosa, popolata da figure e animali; al centro compaiono edifici rurali e un piccolo borgo, mentre sullo sfondo la veduta si apre verso una vallata luminosa e rilievi montuosi. Le grandi masse arboree ai lati incorniciano la scena e guidano lo sguardo verso la parte centrale, creando un marcato contrasto tra le zone in ombra e la luminosità del paesaggio in lontananza.\n\nL’opera presenta il monogramma “DT”, visibile nella superficie pittorica. Tale elemento è compatibile con l’attribuzione tradizionale a David Teniers, che tuttavia, in assenza di documentazione o expertise specialistica, è opportuno indicare come attribuzione e non come autografia certa.\n\nIl dipinto è completato da un’importante cornice lignea intagliata e dorata, riccamente decorata con motivi vegetali e volute, che contribuisce alla notevole presenza decorativa dell’insieme.\n\nDimensioni complessive: H 105 × L 128 cm","description_en":"Large Flemish-style river landscape, described by the owner as oil on copper and bearing the monogram “DT”. The composition includes a village, shepherds, animals and figures beside the water, framed by dense woodland and an important carved and gilt wooden frame.","description_fr":"Grand paysage fluvial de goût flamand, décrit par la propriété comme une huile sur cuivre et portant le monogramme «DT». La scène réunit village, bergers, animaux et personnages au bord de l’eau, dans une importante cadre sculpté et doré.","images":["assets/images/A026/A026-01.webp","assets/images/A026/A026-02.webp"],"status":"available","detail_sections_it":[{"title":"Perché questo pezzo è speciale","paragraphs":["La composizione è ricca di piccoli episodi narrativi e dettagli pastorali. Il supporto metallico dichiarato e il monogramma DT rendono necessaria una verifica specialistica approfondita."]},{"title":"Attribuzione","paragraphs":["In assenza di expertise o documentazione pubblicata, l’opera viene presentata prudentemente come attribuita a David Teniers."]}],"detail_sections_en":[{"title":"Why this piece is special","paragraphs":["The composition contains numerous small narrative and pastoral details. The reported metal support and DT monogram warrant careful specialist examination."]},{"title":"Attribution","paragraphs":["In the absence of an expert report or published documentation, the work is cautiously presented as attributed to David Teniers."]}],"detail_sections_fr":[{"title":"Pourquoi cette pièce est spéciale","paragraphs":["La composition abonde en petits épisodes narratifs et détails pastoraux. Le support métallique déclaré et le monogramme DT justifient un examen spécialisé."]},{"title":"Attribution","paragraphs":["En l’absence d’expertise ou de documentation publiée, l’œuvre est prudemment présentée comme attribuée à David Teniers."]}],"specs_it":[{"label":"Dimensioni complessive","value":"H 105 × L 128 cm"},{"label":"Soggetto","value":"paesaggio fiammingo con figure, animali e architetture"},{"label":"Attribuzione","value":"David Teniers"},{"label":"Firma/monogramma","value":"DT"},{"label":"Cornice","value":"legno intagliato e dorato"}]},"A029":{"category_key":"paintings","title_it":"Achille Savoia, Il ritorno del soldato ferito","title_en":"Scena d’interno familiare – olio su tela del XIX secolo","title_fr":"Scena d’interno familiare – olio su tela del XIX secolo","category_it":"Dipinti","category_en":"Dipinti","category_fr":"Dipinti","dimensions":"Dimensioni dipinto: H 67 × L 83 cm\nDimensioni con cornice: H 85 × L 101 cm","description_it":"Opera firmata di Achille Savoia, artista attivo a Piacenza, intitolata Il ritorno del soldato ferito.\n\nLa composizione raffigura il rientro di un giovane soldato ferito nell’ambiente familiare, riconoscibile dal braccio sostenuto da una fascia. Attorno a lui si sviluppa un’intima scena domestica, con una donna intenta alle attività quotidiane e due bambini seduti in un piccolo carretto.\n\nL’opera presenta una spiccata impostazione narrativa, arricchita dalla minuziosa descrizione degli abiti, degli arredi e degli oggetti dell’interno. La tavolozza calda e la resa naturalistica dei personaggi accentuano il carattere sentimentale e familiare della scena.\n\nL’opera è documentata in una valutazione redatta da Roeland Kollewijn per Bigli Art Broker, Milano, il 14 settembre 2009, nella quale è registrata come «Achille Savoia — Il ritorno del soldato ferito», firmata.","description_en":"Dipinto di genere con scena di vita quotidiana in un interno domestico, figure adulte e bambini, entro importante cornice lignea decorata. Firma, misure e datazione precisa da verificare.","description_fr":"Dipinto di genere con scena di vita quotidiana in un interno domestico, figure adulte e bambini, entro importante cornice lignea decorata. Firma, misure e datazione precisa da verificare.","images":["assets/images/A029/A029-01.webp","assets/images/A029/A029-02.webp","assets/images/A029/A029-03.webp","assets/images/A029/A029-04.webp","assets/images/A029/A029-05.webp","assets/images/A029/A029-06.webp"],"status":"available","specs_it":[{"label":"Autore","value":"Achille Savoia"},{"label":"Titolo","value":"Il ritorno del soldato ferito"},{"label":"Tecnica","value":"Gouache su cartone, secondo la documentazione del 2009"},{"label":"Firma","value":"Firmato"},{"label":"Documentazione","value":"Bigli Art Broker, Roeland Kollewijn, Milano, 14 settembre 2009"},{"label":"Dimensioni opera","value":"H 67 × L 83 cm"},{"label":"Dimensioni con cornice","value":"H 85 × L 101 cm"},{"label":"Cornice","value":"Legno modanato e dorato"}]},"A031":{"category_key":"paintings","title_it":"Natura morta floreale a olio su tela con vaso decorato","title_en":"Natura morta floreale con vaso decorato","title_fr":"Natura morta floreale con vaso decorato","category_it":"Dipinti","category_en":"Dipinti","category_fr":"Dipinti","dimensions":"H 82 × L 51 cm","description_it":"Elegante natura morta floreale a olio su tela, raffigurante una ricca composizione di fiori disposti all’interno di un vaso ornamentale.\n\nIl bouquet è composto da fiori nelle tonalità del rosa, porpora, bianco e crema, accompagnati da foglie verdi e disposti con andamento libero e naturale. La composizione emerge delicatamente dal fondo neutro, realizzato nelle calde tonalità del beige e dell’ocra.\n\nParticolarmente decorativo il vaso, dalla forma classicheggiante, ornato da motivi floreali policromi e dettagli verdi. La resa pittorica morbida e la tavolozza leggermente attenuata conferiscono all’opera un piacevole carattere decorativo e un’atmosfera d’epoca.\n\nIl dipinto è presentato entro un’importante cornice in legno riccamente decorata, con finitura dorata e brunita, che valorizza la composizione e ne accentua il carattere classico.","description_en":"Natura morta decorativa con ricco mazzo di fiori in vaso ornato, entro cornice lignea scura con profili dorati. Tecnica, firma, misure e datazione precisa da verificare.","description_fr":"Natura morta decorativa con ricco mazzo di fiori in vaso ornato, entro cornice lignea scura con profili dorati. Tecnica, firma, misure e datazione precisa da verificare.","images":["assets/images/A031/A031-01.webp","assets/images/A031/A031-02.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XX secolo, da verificare"},{"label":"Tecnica","value":"olio su tela"},{"label":"Soggetto","value":"natura morta floreale con vaso decorato"},{"label":"Dimensioni con cornice","value":"H 82 × L 51 cm"},{"label":"Cornice","value":"legno decorato con finitura dorata e brunita"}],"epoch_it":"XX secolo, da verificare"},"A032":{"category_key":"silver","title_it":"Servizio da tè e caffè in argento 800 – 5 pezzi","title_en":"Servizio da tè e caffè in argento con vassoio – 5 pezzi","title_fr":"Servizio da tè e caffè in argento con vassoio – 5 pezzi","category_it":"Argenti","category_en":"Argenti","category_fr":"Argenti","dimensions":"Da misurare","description_it":"Elegante servizio italiano da tè e caffè in argento 800, composto da cinque elementi coordinati caratterizzati da forme classiche, superfici lucide e proporzioni armoniose.\n\nIl servizio comprende una caffettiera alta, una teiera, una lattiera e due contenitori con coperchio, tutti realizzati secondo un disegno unitario. Le caffettiere presentano corpi bombati, piedi circolari modanati, becchi elegantemente ricurvi e coperchi sormontati da piccoli pomoli ornamentali.\n\nI manici scuri, realizzati in materiale isolante da verificare, creano un raffinato contrasto con la brillantezza dell'argento e permettono la presa degli elementi destinati alle bevande calde.\n\nI contenitori con coperchio sono impreziositi da piccoli manici laterali lavorati e riprendono le forme arrotondate e le modanature dell'intero servizio.\n\nSono visibili il punzone “800”, indicativo del titolo dell'argento, e ulteriori marchi numerici e di fabbricazione da identificare con precisione.\n\nIl servizio si distingue per l'eleganza delle proporzioni e per l'ottimo effetto decorativo delle superfici in argento lucidato.","description_en":"Servizio composto da caffettiera, teiera, lattiera, zuccheriera con coperchio e vassoio ovale. Argento massiccio dichiarato; punzoni, titolo e peso complessivo da verificare.","description_fr":"Servizio composto da caffettiera, teiera, lattiera, zuccheriera con coperchio e vassoio ovale. Argento massiccio dichiarato; punzoni, titolo e peso complessivo da verificare.","images":["assets/images/A032/A032-01.webp","assets/images/A032/A032-02.webp"],"status":"available","specs_it":[{"label":"Materiale","value":"argento 800; manici in materiale scuro da verificare"},{"label":"Epoca","value":"XX secolo"},{"label":"Provenienza","value":"Italia, da confermare attraverso i punzoni"},{"label":"Marchi","value":"punzone 800 e ulteriori punzoni visibili"}],"epoch_it":"XX secolo","material_it":"argento 800; manici in materiale scuro da verificare"},"A033":{"category_key":"silver","title_it":"Servizio da tè e caffè in argento 800 – 4 pezzi","title_en":"Servizio da tè e caffè in argento massiccio con vassoio","title_fr":"Servizio da tè e caffè in argento massiccio con vassoio","category_it":"Argenti","category_en":"Argenti","category_fr":"Argenti","dimensions":"Da misurare","description_it":"Elegante servizio italiano da tè e caffè in argento 800, composto da quattro elementi coordinati: caffettiera, teiera, lattiera e zuccheriera con coperchio.\n\nIl servizio presenta forme classiche e armoniose, con corpi bombati impostati su basi circolari modanate. La caffettiera e la teiera sono caratterizzate da becchi slanciati e manici scuri, mentre la lattiera riprende lo stesso motivo del manico. La zuccheriera è completata da due eleganti anse laterali lavorate.\n\nParticolarmente decorativi i coperchi, sormontati da pomoli cesellati, e gli elementi ornamentali in corrispondenza degli attacchi dei manici. La superficie lucida dell'argento valorizza le forme morbide e la lavorazione tradizionale del servizio.\n\nSono visibili i punzoni “800” e “1541 FI” accompagnati dalla stella, riferibili alla produzione argentiera italiana.\n\nIl vassoio raffigurato in alcune fotografie non fa parte del servizio e non è incluso.","description_en":"Servizio coordinato in argento massiccio con vassoio. La caffettiera visibile sullo sfondo nelle fotografie originali è esclusa dal lotto e dovrà essere catalogata separatamente.","description_fr":"Servizio coordinato in argento massiccio con vassoio. La caffettiera visibile sullo sfondo nelle fotografie originali è esclusa dal lotto e dovrà essere catalogata separatamente.","images":["assets/images/A033/A033-01.webp","assets/images/A033/A033-02.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XX secolo"},{"label":"Origine","value":"Italia"},{"label":"Materiale","value":"argento 800"},{"label":"Composizione","value":"4 pezzi"}],"epoch_it":"XX secolo","material_it":"argento 800"},"A035":{"category_key":"silver","title_it":"Coppia di candelabri neoclassici in argento","title_en":"Coppia di candelabri neoclassici in argento","title_fr":"Coppia di candelabri neoclassici in argento","category_it":"Argenti","category_en":"Argenti","category_fr":"Argenti","dimensions":"Da misurare","description_it":"Elegante coppia di candelabri a tre luci realizzati in argento 800, caratterizzati da una raffinata lavorazione di gusto classico.\n\nCiascun candelabro presenta un alto fusto scanalato impostato su una solida base quadrata a gradoni, decorata lungo il perimetro da una fascia baccellata. Dal capitello riccamente cesellato si sviluppano due bracci sinuosi, che insieme alla luce centrale formano una composizione equilibrata a tre fiamme.\n\nParticolarmente curati i portacandela, ornati da motivi vegetali e volute in rilievo, con ampie bobeches sagomate. La ricchezza della cesellatura contrasta elegantemente con le superfici lineari e scanalate del fusto.\n\nSul fondo è visibile il punzone “800” accompagnato dal marchio “1541 FI” con stella, riconducibile a una produzione italiana in argento di Firenze.\n\nLa coppia conserva una piacevole patina e lievi segni d'uso compatibili con l'età. Eleganti sia come elementi decorativi sia come centrotavola per una tavola importante.","description_en":"Coppia di candelabri a due fiamme con fusto scanalato, base quadrata modanata, bracci sinuosi e portacandele riccamente decorati. Punzoni e peso da verificare.","description_fr":"Coppia di candelabri a due fiamme con fusto scanalato, base quadrata modanata, bracci sinuosi e portacandele riccamente decorati. Punzoni e peso da verificare.","images":["assets/images/A035/A035-01.webp","assets/images/A035/A035-02.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XX secolo"},{"label":"Origine","value":"Italia, Firenze"},{"label":"Materiale","value":"argento 800"},{"label":"Composizione","value":"2 candelabri, 3 luci ciascuno"},{"label":"Punzonatura","value":"800 – 1541 FI con stella"},{"label":"Stile","value":"classico / neoclassico"}],"epoch_it":"XX secolo","style_it":"classico / neoclassico","material_it":"argento 800"},"A036":{"category_key":"silver","title_it":"Grande vaso cesellato in argento","title_en":"Grande vaso cesellato in argento","title_fr":"Grande vaso cesellato in argento","category_it":"Argenti","category_en":"Argenti","category_fr":"Argenti","dimensions":"Da misurare","description_it":"Importante vaso decorativo in argento, caratterizzato da una ricca lavorazione a sbalzo e cesello di gusto classico.\n\nIl corpo, ampio e sagomato, è scandito da riserve ornate da elaborati motivi floreali e vegetali in rilievo, alternati a volute e foglie d’acanto. Il collo si apre in un’elegante bocca svasata con profilo mosso e ondulato.\n\nLa base circolare, particolarmente elaborata, presenta una successione di elementi baccellati e motivi fogliacei che riprendono la decorazione del corpo e conferiscono all’insieme un aspetto ricco e monumentale.\n\nUn oggetto di forte presenza decorativa, interessante sia come elemento d’arredo sia per una collezione di argenteria.","description_en":"Grande vaso decorativo in argento con corpo mosso, bocca a corolla e ricca lavorazione floreale e fogliacea. Punzoni, peso, misure e manifattura da verificare.","description_fr":"Grande vaso decorativo in argento con corpo mosso, bocca a corolla e ricca lavorazione floreale e fogliacea. Punzoni, peso, misure e manifattura da verificare.","images":["assets/images/A036/A036-01.webp","assets/images/A036/A036-02.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XX secolo"},{"label":"Stile","value":"classico, di gusto barocco/rococò"},{"label":"Lavorazione","value":"sbalzo e cesello"},{"label":"Materiale","value":"argento"}],"epoch_it":"XX secolo","style_it":"classico, di gusto barocco/rococò","material_it":"argento"},"A037":{"category_key":"lighting","title_it":"Lampada “Fiori di Pesco” in stile Tiffany, Argentiere Vavassori Giacomo","title_en":"Lampada da tavolo floreale in vetro colorato","title_fr":"Lampada da tavolo floreale in vetro colorato","category_it":"Illuminazione","category_en":"Illuminazione","category_fr":"Illuminazione","dimensions":"H65xL36 con circonferenza del paralume 115cm","description_it":"Elegante lampada da tavolo “Fiori di Pesco” di fattura italiana, realizzata dall’argentiere Vavassori Giacomo, identificato dal marchio VA1211.\n\nIl grande paralume a cupola è composto da un raffinato mosaico di vetri colorati assemblati secondo la tecnica Tiffany. La decorazione raffigura fiori di pesco nelle delicate tonalità del rosa e del lilla, accompagnati da un fitto motivo di foglie verdi e da una fascia superiore in vetro chiaro.\n\nLa struttura è completata da un alto fusto e da una ricca base in argento/metallo argentato finemente lavorata a rilievo con motivi vegetali, in armonia con il carattere floreale del paralume.\n\nUn oggetto decorativo di notevole presenza, nel quale la tradizione italiana dell’argenteria si unisce alla tecnica del vetro a mosaico di ispirazione Tiffany.","description_en":"Lampada con paralume in vetro colorato a motivo floreale e base metallica decorata. Funzionamento, firma o marchio del produttore e misure da verificare.","description_fr":"Lampada con paralume in vetro colorato a motivo floreale e base metallica decorata. Funzionamento, firma o marchio del produttore e misure da verificare.","images":["assets/images/A037/A037-01.webp","assets/images/A037/A037-02.webp","assets/images/A037/A037-03.webp","assets/images/A037/A037-04.webp","assets/images/A037/A037-05.webp","assets/images/A037/A037-06.webp","assets/images/A037/A037-07.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XX secolo"},{"label":"Stile","value":"Tiffany / Liberty"},{"label":"Produttore","value":"Vavassori Giacomo"},{"label":"Marchio","value":"VA1211"},{"label":"Lavorazione","value":"mosaico di vetri secondo la tecnica Tiffany"},{"label":"Soggetto","value":"Fiori di pesco"},{"label":"Materiale","value":"vetro colorato, argento/metallo argentato"}],"epoch_it":"XX secolo","style_it":"Tiffany / Liberty","material_it":"vetro colorato, argento/metallo argentato"},"A038":{"category_key":"silver","title_it":"Grande legumiera ovale in argento 800 con coperchio e manici decorati","title_en":"Grande legumiera ovale in argento con coperchio","title_fr":"Grande legumiera ovale in argento con coperchio","category_it":"Argenti","category_en":"Argenti","category_fr":"Argenti","dimensions":"Da misurare","description_it":"Elegante e importante legumiera ovale italiana realizzata in argento 800, completa di coperchio e caratterizzata da una raffinata lavorazione di gusto classico.\n\nIl corpo presenta una superficie prevalentemente liscia e lucida, valorizzata da un ricco bordo perimetrale baccellato. Ai lati si sviluppano due manici sagomati con decorazioni vegetali e fogliacee in rilievo.\n\nIl grande coperchio bombato riprende la finitura lucida del corpo ed è impreziosito da una fascia baccellata e da un elaborato pomello terminale a motivo vegetale, finemente lavorato.\n\nSul pezzo sono chiaramente visibili il titolo “800” e il marchio italiano “1541 FI” accompagnato dalla stella, identificativo di un argentiere registrato nella provincia di Firenze.\n\nUn oggetto di argenteria importante, elegante e funzionale, adatto sia all'utilizzo in tavola sia come elemento da collezione.","description_en":"Legumiera ovale con coperchio bombato, pomolo decorativo e manici laterali lavorati. Punzoni, peso e dimensioni da verificare.","description_fr":"Legumiera ovale con coperchio bombato, pomolo decorativo e manici laterali lavorati. Punzoni, peso e dimensioni da verificare.","images":["assets/images/A038/A038-01.webp","assets/images/A038/A038-02.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XX secolo"},{"label":"Origine","value":"Italia, Firenze"},{"label":"Materiale","value":"argento 800"},{"label":"Lavorazione","value":"fusione, sbalzo/cesello e finitura lucida"},{"label":"Punzonatura","value":"800 – 1541 FI con stella"}],"epoch_it":"XX secolo","material_it":"argento 800"},"A041":{"category_key":"silver","title_it":"Scultura di gufo in argento","title_en":"Scultura di gufo in argento","title_fr":"Scultura di gufo in argento","category_it":"Argenti","category_en":"Argenti","category_fr":"Argenti","dimensions":"Da misurare","description_it":"Originale scultura decorativa raffigurante un gufo, realizzata in argento 800 e caratterizzata da una particolare costruzione stilizzata delle diverse parti del piumaggio.\n\nIl corpo presenta forme tondeggianti composte da elementi sovrapposti, mentre le ali sono definite da una serie di lunghe piume scanalate che creano un interessante effetto tridimensionale. Il volto, fortemente caratterizzato, è costruito attraverso ampie placche sagomate, grandi occhi circolari, sopracciglia marcate e un elemento centrale che definisce il becco.\n\nParticolarmente curati anche i piccoli artigli e la lavorazione delle piume, che conferiscono alla figura una forte personalità e un gusto decorativo decisamente originale.\n\nSul pezzo sono visibili il titolo “800” e il marchio italiano “1541 FI” con stella, riferibile a un argentiere registrato nella provincia di Firenze.\n\nUn oggetto insolito e molto decorativo, interessante sia come scultura da collezione sia per gli appassionati di argenteria italiana del Novecento.","description_en":"Scultura decorativa raffigurante un gufo con forme stilizzate e dettagli delle piume. Titolo, punzoni, peso e misure da verificare.","description_fr":"Scultura decorativa raffigurante un gufo con forme stilizzate e dettagli delle piume. Titolo, punzoni, peso e misure da verificare.","images":["assets/images/A041/A041-01.webp","assets/images/A041/A041-02.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XX secolo"},{"label":"Origine","value":"Italia, Firenze"},{"label":"Materiale","value":"argento 800"},{"label":"Soggetto","value":"gufo"},{"label":"Punzonatura","value":"800 – 1541 FI con stella"}],"epoch_it":"XX secolo","material_it":"argento 800"},"A042":{"category_key":"silver","title_it":"Scultura decorativa a forma di ape in argento 800 con ali cesellate","title_en":"Scultura di ape in argento","title_fr":"Scultura di ape in argento","category_it":"Argenti","category_en":"Argenti","category_fr":"Argenti","dimensions":"Da misurare","description_it":"Raffinata scultura decorativa raffigurante un’ape, realizzata in argento 800 e caratterizzata da una lavorazione particolarmente curata.\n\nIl corpo è costruito attraverso elementi bombati e articolati che riproducono testa, torace e addome dell’insetto, completati da sei zampe sagomate e dettagli del muso. Particolarmente decorative le ali sovrapposte, impreziosite da una fine lavorazione cesellata con motivi floreali e vegetali.\n\nLa superficie lucida dell’argento, insieme alla costruzione tridimensionale e alla ricchezza dei dettagli, conferisce all’oggetto una forte presenza scultorea e un carattere originale.\n\nSul pezzo sono presenti i punzoni “800” e “1541 FI” accompagnato dalla stella, riconducibili alla produzione argentiera italiana.\n\nUn curioso e raffinato oggetto da collezione, adatto anche come elemento decorativo per una scrivania, una libreria o una collezione di argenteria.","description_en":"Scultura decorativa raffigurante un’ape con ali incise e corpo articolato. Titolo, punzoni, peso e misure da verificare.","description_fr":"Scultura decorativa raffigurante un’ape con ali incise e corpo articolato. Titolo, punzoni, peso e misure da verificare.","images":["assets/images/A042/A042-01.webp","assets/images/A042/A042-02.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XX secolo"},{"label":"Materiale","value":"argento 800"},{"label":"Origine","value":"Italia"},{"label":"Punzone","value":"800 – 1541 FI con stella"}],"epoch_it":"XX secolo","material_it":"argento 800"},"A043":{"category_key":"silver","title_it":"Scultura decorativa a forma di elefante in argento 800 con dettagli cesellati","title_en":"Scultura di elefante in argento","title_fr":"Scultura di elefante in argento","category_it":"Argenti","category_en":"Argenti","category_fr":"Argenti","dimensions":"Da misurare","description_it":"Elegante scultura decorativa raffigurante un elefante, realizzata in argento 800 e caratterizzata da un interessante contrasto tra le superfici lisce e lucide del corpo e la ricca lavorazione della testa.\n\nLa figura presenta un corpo dalle forme arrotondate sostenuto da quattro robuste zampe cilindriche, lunga coda e caratteristiche zanne ricurve. La testa, le grandi orecchie e la proboscide sono finemente lavorate con motivi ornamentali incisi e cesellati, che conferiscono particolare ricchezza e carattere all'insieme.\n\nLa resa stilizzata del corpo si combina con la minuziosa decorazione della parte anteriore, creando un oggetto di forte presenza decorativa, ispirato alla tradizione dell'argenteria italiana del XX secolo.\n\nPresenti i punzoni “800” e “1541 FI” con stella.\n\nUn raffinato oggetto da collezione, particolarmente adatto a una collezione di argenteria o di soggetti zoomorfi.","description_en":"Scultura decorativa raffigurante un elefante con proboscide, zanne e orecchie lavorate. Titolo, punzoni, peso e misure da verificare.","description_fr":"Scultura decorativa raffigurante un elefante con proboscide, zanne e orecchie lavorate. Titolo, punzoni, peso e misure da verificare.","images":["assets/images/A043/A043-01.webp","assets/images/A043/A043-02.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XX secolo"},{"label":"Materiale","value":"argento 800"},{"label":"Origine","value":"Italia"},{"label":"Punzone","value":"800 – 1541 FI con stella"}],"epoch_it":"XX secolo","material_it":"argento 800"},"A044":{"category_key":"silver","title_it":"Vassoio rotondo in argento 800 sbalzato e cesellato con decoro floreale","title_en":"Vassoio rotondo sbalzato in argento","title_fr":"Vassoio rotondo sbalzato in argento","category_it":"Argenti","category_en":"Argenti","category_fr":"Argenti","dimensions":"Da misurare","description_it":"Elegante vassoio rotondo in argento 800, caratterizzato da una ricca lavorazione decorativa eseguita a sbalzo e cesello.\n\nL’ampio piano presenta una fitta decorazione incisa con motivi floreali, fogliati e volute disposti armoniosamente intorno al centro. Il bordo, particolarmente elaborato, è mosso e sagomato secondo il gusto rococò, con successione di volute, elementi vegetali e rilievi ornamentali.\n\nAl centro compare un motivo araldico coronato, che costituisce uno degli elementi più interessanti della composizione. Il vassoio poggia su piccoli piedini decorati, che lo sollevano leggermente dal piano d’appoggio.\n\nSul retro sono presenti i punzoni “800” e “1541 FI” con stella, riferibili alla produzione argentiera italiana.\n\nUn pezzo di notevole effetto decorativo, utilizzabile come vassoio da presentazione oppure esposto come elemento da collezione.","description_en":"Vassoio rotondo con bordo mosso e ricca decorazione a sbalzo e cesello. Punzoni, peso, diametro e manifattura da verificare.","description_fr":"Vassoio rotondo con bordo mosso e ricca decorazione a sbalzo e cesello. Punzoni, peso, diametro e manifattura da verificare.","images":["assets/images/A044/A044-01.webp","assets/images/A044/A044-02.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XX secolo"},{"label":"Materiale","value":"argento 800"},{"label":"Tecnica","value":"sbalzo, cesello e incisione"},{"label":"Stile","value":"rococò / classico"},{"label":"Origine","value":"Italia"},{"label":"Punzone","value":"800 – 1541 FI con stella"}],"epoch_it":"XX secolo","style_it":"rococò / classico","material_it":"argento 800"},"A045":{"category_key":"silver","title_it":"Coppia di salierine in argento 925 con cucchiaini","title_en":"Coppia di salierine in argento con cucchiaini","title_fr":"Coppia di salierine in argento con cucchiaini","category_it":"Argenti","category_en":"Argenti","category_fr":"Argenti","dimensions":"Da misurare","description_it":"Elegante coppia di salierine in argento 925, realizzate in stile neoclassico e accompagnate dai relativi cucchiaini.\n\nI corpi, dalla forma ovale e bombata, sono riccamente decorati a rilievo con motivi a conchiglia, volute e ornati vegetali. Ciascuna salierina poggia su piccoli piedini sagomati, che conferiscono leggerezza ed eleganza alla composizione.\n\nParticolarmente raffinato l’interno dorato, che crea un piacevole contrasto con la superficie esterna in argento. I cucchiaini presentano manici incisi con motivi decorativi coordinati.\n\nSul fondo è visibile il punzone “925” accompagnato dal marchio “BI”.","description_en":"Coppia di salierine decorate, complete di cucchiaini, con interni dorati e piedini mossi. Punzoni, titolo, peso e originalità dei cucchiaini da verificare.","description_fr":"Coppia di salierine decorate, complete di cucchiaini, con interni dorati e piedini mossi. Punzoni, titolo, peso e originalità dei cucchiaini da verificare.","images":["assets/images/A045/A045-01.webp","assets/images/A045/A045-02.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XX secolo"},{"label":"Materiale","value":"argento 925 con interno dorato"},{"label":"Composizione","value":"2 salierine + 2 cucchiaini"},{"label":"Dimensioni salierine","value":"circa L 8 × P 5 × H 4,5 cm"}],"epoch_it":"XX secolo","material_it":"argento 925 con interno dorato"},"A046":{"category_key":"silver","title_it":"Teiera in argento 800 con manico scuro","title_en":"Teiera neoclassica in argento","title_fr":"Teiera neoclassica in argento","category_it":"Argenti","category_en":"Argenti","category_fr":"Argenti","dimensions":"Da misurare","description_it":"Elegante teiera italiana in argento 800, caratterizzata da una ricca lavorazione di gusto neoclassico.\n\nIl corpo bombato presenta una marcata lavorazione a costolature verticali, impreziosita nella parte superiore da una fascia finemente cesellata con motivi floreali e vegetali. Il coperchio, anch’esso scanalato, è sormontato da un raffinato pomolo a forma di pigna.\n\nIl lungo beccuccio ricurvo è decorato con motivi fogliacei, mentre il grande manico scuro crea un elegante contrasto con la superficie lucida dell’argento. La teiera poggia su quattro piedini sagomati e decorati.\n\nAll’interno è visibile una tonalità dorata. Sul fondo sono presenti i punzoni “800”, “1541 FI” accompagnato dalla stella e “ITALY”, che ne attestano la manifattura italiana in argento 800.\n\nUn raffinato esempio di argenteria italiana del XX secolo, adatto sia all’uso sia come oggetto decorativo e da collezione.","description_en":"Teiera con corpo costolato, decoro fogliaceo, coperchio con pomolo e manico scuro isolante. Punzoni, titolo, peso e misure da verificare.","description_fr":"Teiera con corpo costolato, decoro fogliaceo, coperchio con pomolo e manico scuro isolante. Punzoni, titolo, peso e misure da verificare.","images":["assets/images/A046/A046-01.webp","assets/images/A046/A046-02.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XX secolo"},{"label":"Materiale","value":"argento 800"},{"label":"Origine","value":"Italia"},{"label":"Punzonatura","value":"800 – 1541 FI ★ – ITALY"}],"epoch_it":"XX secolo","material_it":"argento 800"},"A047":{"category_key":"silver","title_it":"Calamaio da scrivania in argento 800 con vaschette in vetro","title_en":"Calamaio neoclassico in argento con due vaschette","title_fr":"Calamaio neoclassico in argento con due vaschette","category_it":"Argenti","category_en":"Argenti","category_fr":"Argenti","dimensions":"Da misurare","description_it":"Elegante calamaio da scrivania italiano in argento 800, realizzato in stile neoclassico e caratterizzato da una ricca lavorazione decorativa.\n\nLa base rettangolare presenta bordo perlinato, angoli ornati da motivi fogliacei e quattro piedini baccellati. Sulla base sono collocate due vaschette cilindriche in vetro scanalato, inserite entro raffinate montature in argento decorate con festoni e motivi vegetali.\n\nLe due vaschette sono chiuse da coperchi bombati e cesellati, ciascuno sormontato da un elegante pomolo a pigna. La parte centrale presenta gli elementi destinati all'appoggio degli strumenti da scrittura, completando la composizione simmetrica tipica dei servizi da scrittoio di gusto classico.\n\nSul manufatto sono visibili i punzoni “800”, “1541 FI” con stella e “ITALY”, riconducibili a una manifattura italiana in argento 800.\n\nUn raffinato oggetto da scrivania, interessante sia come complemento d'arredo sia per una collezione di argenteria italiana.","description_en":"Calamaio composto da vassoio rettangolare, due vaschette con inserti in vetro e coperchi decorativi, più poggiapenne centrale. Punzoni, titolo, peso, misure e completezza da verificare.","description_fr":"Calamaio composto da vassoio rettangolare, due vaschette con inserti in vetro e coperchi decorativi, più poggiapenne centrale. Punzoni, titolo, peso, misure e completezza da verificare.","images":["assets/images/A047/A047-01.webp","assets/images/A047/A047-02.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XX secolo"},{"label":"Materiale","value":"argento 800 e vetro scanalato"},{"label":"Origine","value":"Italia"},{"label":"Punzonatura","value":"800 – 1541 FI ★ – ITALY"}],"epoch_it":"XX secolo","material_it":"argento 800 e vetro scanalato"},"A048":{"category_key":"paintings","category_it":"Dipinti","category_en":"Paintings","category_fr":"Peintures","title_it":"Paesaggio con vegetazione mediterranea e banano","title_en":"Mediterranean landscape in a gilt frame","title_fr":"Paysage méditerranéen dans un cadre doré","dimensions":"Da misurare","description_it":"Suggestivo dipinto raffigurante un rigoglioso paesaggio dominato da una ricca vegetazione, con un grande banano al centro della composizione, alberi e fioriture che animano il primo piano.\n\nLa pittura è caratterizzata da una pennellata materica e vivace, particolarmente evidente nella resa delle fronde, dell’erba e dei fiori. La varietà delle tonalità verdi è ravvivata dai delicati colori del cielo e dalle note rosse e rosate della vegetazione fiorita.\n\nLa composizione restituisce l’atmosfera luminosa e spontanea di un giardino mediterraneo o di un paesaggio dal clima mite, con un’impostazione naturalistica tipica della pittura di paesaggio tra la fine del XIX e la prima metà del XX secolo.\n\nIl dipinto è presentato entro un’importante cornice dorata modanata, che valorizza la luminosità dell’opera.\n\nDalla fotografia frontale non è visibile una firma; eviterei quindi, al momento, attribuzioni specifiche o una datazione troppo precisa.","description_en":"Landscape painting with lush vegetation, palms and trees, presented in a substantial moulded gilt frame.","description_fr":"Paysage à la végétation luxuriante, palmiers et arbres, présenté dans un important cadre doré mouluré.","images":["assets/images/A048/A048-01.webp"],"status":"available","specs_it":[{"label":"Tecnica","value":"presumibilmente olio su tela o tavola, da verificare dal retro"},{"label":"Soggetto","value":"paesaggio con vegetazione e banano"},{"label":"Epoca","value":"presumibilmente fine XIX – prima metà XX secolo Dimensioni con cornice:"},{"label":"Cornice","value":"legno dorato modanato"}],"epoch_it":"presumibilmente fine XIX – prima metà XX secolo Dimensioni con cornice:"},"A049":{"category_key":"paintings","category_it":"Dipinti","category_en":"Paintings","category_fr":"Peintures","title_it":"Paesaggio pastorale con figure e armenti","title_en":"Pastoral landscape with figures and livestock","title_fr":"Paysage pastoral avec figures et troupeaux","dimensions":"Dimensioni con cornice: H 61 × L 83 cm","description_it":"Ampio paesaggio di gusto classico raffigurante una veduta pastorale animata da figure, greggi e armenti.\n\nLa composizione si sviluppa in profondità: in primo piano, lungo un sentiero ombreggiato, alcuni pastori conducono gli animali; sulla destra un corso d’acqua accompagna lo sguardo verso la vallata, mentre sul rilievo in lontananza si distingue un borgo fortificato con architetture e torri.\n\nLa grande massa arborea sulla sinistra crea un efficace contrasto chiaroscurale con il cielo luminoso e con l’ampio orizzonte centrale. La costruzione scenografica del paesaggio, la presenza delle rovine e delle architetture lontane e le piccole figure pastorali richiamano la tradizione del paesaggio classico europeo.\n\nIl dipinto è racchiuso in un'importante cornice dorata riccamente modanata e decorata.\n\nDalla fotografia non è visibile una firma; eviterei quindi per il momento un’attribuzione specifica e anche una datazione troppo precisa senza esaminare retro, supporto e superficie pittorica.","description_en":"Expansive pastoral landscape with trees, water, figures and grazing animals, presented in a gilt frame.","description_fr":"Vaste paysage pastoral avec arbres, cours d’eau, personnages et animaux au pâturage, présenté dans un cadre doré.","images":["assets/images/A049/a049-01.webp"],"status":"available","specs_it":[{"label":"La composizione si sviluppa in profondità","value":"in primo piano, lungo un sentiero ombreggiato, alcuni pastori conducono gli animali; sulla destra un corso d’acqua accompagna lo sguardo verso la vallata, mentre sul rilievo in lontananza si distingue un borgo fortificato con architetture e torri. La grande massa arborea sulla sinistra crea un efficace contrasto chiaroscurale con il cielo luminoso e con l’ampio orizzonte centrale. La costruzione scenografica del paesaggio, la presenza delle rovine e delle architetture lontane e le piccole figure pastorali richiamano la tradizione del paesaggio classico europeo. Il dipinto è racchiuso in un'importante cornice dorata riccamente modanata e decorata. Dalla fotografia non è visibile una firma; eviterei quindi per il momento un’attribuzione specifica e anche una datazione troppo precisa senza esaminare retro, supporto e superficie pittorica."},{"label":"Tecnica","value":"presumibilmente olio su tela, da verificare"},{"label":"Soggetto","value":"paesaggio pastorale con figure, greggi, armenti e borgo fortificato"},{"label":"Stile","value":"paesaggio di gusto classico"},{"label":"Epoca","value":"da verificare"},{"label":"Dimensioni con cornice","value":"H 61 × L 83 cm"},{"label":"Cornice","value":"legno dorato riccamente modanato e decorato"}],"epoch_it":"da verificare","style_it":"paesaggio di gusto classico"},"A051":{"category_key":"decorative_panels","category_it":"Pannelli decorativi","category_en":"Decorative Panels","category_fr":"Panneaux décoratifs","title_it":"Coppia di grandi arazzi raffiguranti le Favole di Fedro","title_en":"Pair of large decorative panels with woodland landscapes","title_fr":"Paire de grands panneaux décoratifs à paysages boisés","dimensions":"H 230 × L 100 cm ciascuno","description_it":"Coppia di grandi arazzi verticali raffiguranti episodi tratti dalle Favole di Fedro.\n\nLe composizioni presentano scene narrative ambientate in paesaggi boschivi, con alberi, vegetazione, corsi d’acqua, architetture e figure animali. I due esemplari sono concepiti come pendant e sviluppano soggetti coordinati.\n\nLe notevoli dimensioni conferiscono alla coppia una forte presenza decorativa, adatta a grandi pareti e ambienti di rappresentanza.","description_en":"Pair of vertical painted panels with woodland landscapes, birds and vegetation, conceived as wall decoration.","description_fr":"Paire de panneaux verticaux peints de paysages boisés, oiseaux et végétation, conçus comme décor mural.","images":["assets/images/A051/A051-01.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"presumibilmente XIX secolo, da verificare"},{"label":"Soggetto","value":"paesaggi esotici con vegetazione, architetture e volatile"},{"label":"Stile","value":"gusto chinoiserie / paesaggistico decorativo"},{"label":"Tecnica","value":"da verificare"},{"label":"Composizione","value":"2 pannelli pendant"},{"label":"Cornice","value":"sottile cornice dorata"}],"epoch_it":"presumibilmente XIX secolo, da verificare","style_it":"gusto chinoiserie / paesaggistico decorativo"},"A052":{"category_key":"seating","category_it":"Sedute e salotti","category_en":"Seating","category_fr":"Sièges","title_it":"Salotto coordinato con divano a 3 posti, due poltrone e due ottomani","title_en":"Coordinated suite with sofa, two armchairs and two ottomans","title_fr":"Salon coordonné avec canapé, deux fauteuils et deux ottomans","dimensions":"Divano 3 posti: L 210 × P 90 × H 82 cm\n2 poltrone: L 89 × P 94 × H 82 cm ciascuna\n2 ottomani: L 89 × P 50 × H 37 cm ciascuno","description_it":"Elegante salotto coordinato composto da un divano a tre posti, due poltrone e due ottomani, interamente rivestiti nello stesso tessuto operato nei toni dell’azzurro polvere, avorio e verde salvia, con raffinati motivi vegetali e ornamentali.\n\nIl divano e le poltrone presentano linee classiche, ampi braccioli arrotondati e comode imbottiture, mentre i due ottomani sono caratterizzati da sedute imbottite con lavorazione capitonné e piccoli piedi sferici.\n\nL’insieme conserva una piacevole uniformità stilistica e costituisce un salotto completo di notevole presenza decorativa.\n\nIl tessuto presenta usura, in particolare in corrispondenza dei poggiabraccia, ed è pertanto consigliabile prevedere una nuova tappezzeria/rifoderatura.\n\nDIMENSIONI\n\nDivano 3 posti: L 210 × P 90 × H 82 cm\n2 poltrone: L 89 × P 94 × H 82 cm ciascuna\n2 ottomani: L 89 × P 50 × H 37 cm ciascuno","description_en":"Coordinated suite upholstered in pale blue patterned fabric, comprising a three-seat sofa, two armchairs and two large ottomans. Frames to be checked; the upholstery requires replacement.","description_fr":"Salon coordonné recouvert d’un tissu bleu clair à motif végétal, comprenant un canapé trois places, deux fauteuils et deux grands ottomans. Structures à vérifier ; tissu à refaire.","images":["assets/images/A052/A052-01.webp","assets/images/A052/A052-02.webp","assets/images/A052/A052-03.webp","assets/images/A052/A052-04.webp"],"status":"available","specs_it":[{"label":"Divano 3 posti","value":"L 210 × P 90 × H 82 cm"},{"label":"2 poltrone","value":"L 89 × P 94 × H 82 cm ciascuna"},{"label":"2 ottomani","value":"L 89 × P 50 × H 37 cm ciascuno"},{"label":"EPOCA","value":"XX secolo"},{"label":"STILE","value":"Classico"},{"label":"MATERIALE","value":"Struttura imbottita, tessuto operato"}],"epoch_it":"XX secolo","style_it":"Classico","material_it":"Struttura imbottita, tessuto operato"},"A053":{"category_key":"furniture","category_it":"Mobili","category_en":"Furniture","category_fr":"Mobilier","title_it":"Tavolino ovale piemontese-francese, periodo Luigi XVI","title_en":"Oval Piedmontese-French table, Louis XVI period","title_fr":"Table ovale piémontaise-française, époque Louis XVI","dimensions":"H 72 × L 99 × P 65 cm","description_it":"Elegante tavolino ovale piemontese-francese del periodo Luigi XVI, caratterizzato da raffinata lavorazione in legno impiallacciato e intarsiato. Il piano in marmo chiaro, dalle delicate venature naturali, è incorniciato da una ringhiera traforata in ottone. La fascia sottopiano, finemente decorata con riserve geometriche intarsiate, incorpora un cassetto centrale. Il mobile poggia su quattro eleganti gambe scanalate, rastremate verso il basso e impreziosite da dettagli metallici. Un raffinato esempio di ebanisteria di gusto neoclassico, nel quale si incontrano influenze piemontesi e francesi tipiche dell'epoca Luigi XVI.","description_en":"Oval veneered and inlaid table with pale marble top, pierced metal gallery, front drawer and tapering legs. Second half of the eighteenth century according to family documentation.","description_fr":"Table ovale plaquée et marquetée, plateau en marbre clair, galerie ajourée en métal, tiroir frontal et pieds fuselés. Seconde moitié du XVIIIe siècle selon la documentation familiale.","images":["assets/images/A053/A053-01.webp","assets/images/A053/A053-02.webp"],"status":"available","specs_it":[{"label":"EPOCA","value":"Fine XVIII secolo – periodo Luigi XVI"},{"label":"STILE","value":"Luigi XVI"},{"label":"PROVENIENZA","value":"Area piemontese-francese"},{"label":"MATERIALE","value":"Legno impiallacciato e intarsiato, marmo, ottone"}],"epoch_it":"Fine XVIII secolo – periodo Luigi XVI","style_it":"Luigi XVI","material_it":"Legno impiallacciato e intarsiato, marmo, ottone"},"A054":{"category_key":"furniture","category_it":"Mobili","category_en":"Furniture","category_fr":"Mobilier","title_it":"Scrittorio detto “Mazzarino”, Lombardia, inizi XVIII secolo","title_en":"Mazarine desk, Lombardy, early eighteenth century","title_fr":"Bureau dit Mazarine, Lombardie, début du XVIIIe siècle","dimensions":"Da misurare","description_it":"Importante scrittorio lombardo detto “Mazzarino”, risalente agli inizi del XVIII secolo, caratterizzato da una struttura architettonica articolata e da una ricca decorazione in radica e legni impiallacciati, elegantemente contrastati da elementi ebanizzati.\n\nIl fronte è organizzato attorno al vano centrale, affiancato da due corpi laterali con serie di cassetti a profilo mosso. La parte superiore è completata da un'alzata composta da numerosi piccoli cassetti, anch'essi impreziositi dalla ricca marezzatura della radica.\n\nLa struttura è scandita da montanti e gambe tornite ebanizzate, raccordate inferiormente da traverse sagomate. Le numerose bocchette decorative in metallo dorato arricchiscono ulteriormente il fronte e sottolineano il carattere prestigioso del mobile.\n\nDi particolare interesse la qualità dell'impiallacciatura, con venature della radica accuratamente selezionate e disposte secondo effetti simmetrici e decorativi. La lavorazione dei fianchi e l'articolazione della struttura conferiscono allo scrittorio una forte presenza scultorea e testimoniano l'alto livello dell'ebanisteria lombarda dell'epoca.","description_en":"Important Lombard Mazarine desk with richly figured veneer and numerous drawers arranged in the side sections and raised superstructure.","description_fr":"Important bureau Mazarine lombard, richement plaqué et muni de nombreux tiroirs dans les caissons latéraux et le gradin.","images":["assets/images/A054/A054-01.webp","assets/images/A054/A054-02.webp","assets/images/A054/A054-03.webp"],"status":"available","specs_it":[{"label":"EPOCA","value":"Inizi XVIII secolo"},{"label":"PROVENIENZA","value":"Lombardia"},{"label":"TIPOLOGIA","value":"Scrittorio detto “Mazzarino”"},{"label":"STILE","value":"Barocco lombardo"},{"label":"MATERIALE","value":"Legno, radica e legni impiallacciati, elementi ebanizzati, metallo dorato"}],"epoch_it":"Inizi XVIII secolo","style_it":"Barocco lombardo","material_it":"Legno, radica e legni impiallacciati, elementi ebanizzati, metallo dorato"},"A055":{"category_key":"seating","category_it":"Sedute e salotti","category_en":"Seating","category_fr":"Sièges","title_it":"Set di 4 sedie laccate con chinoiserie, Luigi XV","title_en":"Set of four lacquered chinoiserie chairs, Louis XV taste","title_fr":"Suite de quatre chaises laquées à chinoiseries, goût Louis XV","dimensions":"H 110 × L 60 × P 80 cm ciascuna","description_it":"Raffinato set di quattro sedie Luigi XV in legno laccato nero, impreziosite da elaborate decorazioni a chinoiserie policrome e dorate. Gli alti schienali sagomati e traforati presentano cartelle centrali riccamente dipinte con scene orientali animate da figure, architetture, paesaggi, elementi floreali e vegetali.\n\nLe gambe anteriori mosse, tipiche del gusto Luigi XV, sono raccordate da traverse sagomate e tornite. Le sedute imbottite sono rivestite in velluto rosso, creando un elegante contrasto con il fondo scuro della laccatura e le decorazioni dorate.\n\nIl set conserva una suggestiva patina, con usure e piccole mancanze della superficie decorata compatibili con l'età. Insieme completo di notevole impatto decorativo e particolare interesse per la ricchezza della lavorazione a chinoiserie.","description_en":"Four dark lacquered wooden chairs with polychrome and gilt chinoiserie decoration, open backs, cabriole legs and red velvet seats. Possible Lucca or Venetian origin, with Dutch influence, to be verified.","description_fr":"Quatre chaises en bois laqué sombre à décor polychrome et doré de chinoiseries, dossiers ajourés, pieds galbés et assises en velours rouge. Attribution lucquoise ou vénitienne, avec influence hollandaise possible, à vérifier. Patine et usures anciennes.","images":["assets/images/A055/A055-01.webp","assets/images/A055/A055-02.webp","assets/images/A055/A055-03.webp","assets/images/A055/A055-04.webp","assets/images/A055/A055-05.webp","assets/images/A055/A055-06.webp"],"status":"available","specs_it":[{"label":"EPOCA","value":"XVIII secolo"},{"label":"STILE","value":"Luigi XV / Chinoiserie"},{"label":"MATERIALE","value":"Legno laccato e dipinto, velluto"},{"label":"COMPOSIZIONE","value":"Set di 4 sedie"}],"epoch_it":"XVIII secolo","style_it":"Luigi XV / Chinoiserie","material_it":"Legno laccato e dipinto, velluto"},"A056":{"category_key":"seating","category_it":"Sedute e salotti","category_en":"Seating","category_fr":"Sièges","title_it":"Importante suite di 12 sedie intarsiate con figure mitologiche","title_en":"Important suite of twelve inlaid chairs with mythological figures","title_fr":"Importante suite de douze chaises marquetées à figures mythologiques","dimensions":"H 99 × L 50 × P 44 cm circa, ciascuna","description_it":"Importante suite di dodici sedie in legno finemente intarsiato, caratterizzata da una ricca decorazione figurativa e ornamentale che rende ciascun esemplare parte di un insieme particolarmente scenografico.\n\nGli alti schienali sagomati sono impreziositi da elaborate composizioni a intarsio con figure di ispirazione mitologica e classica, profili entro medaglioni, putti, creature fantastiche e motivi allegorici, accompagnati da racemi, volute ed elementi vegetali.\n\nParticolarmente interessante è la varietà dei soggetti raffigurati: le decorazioni cambiano da una sedia all’altra pur mantenendo un linguaggio stilistico e una struttura compositiva coerenti, creando una sequenza di dodici esemplari tra loro coordinati ma individualmente caratterizzati.\n\nLa lavorazione a intarsio prosegue sulle fasce delle sedute e sulle gambe anteriori, ornate da motivi floreali, vegetali e figurativi. Le sedute imbottite sono rivestite in tessuto chiaro a coste sottili.\n\nL’insieme presenta una raffinata combinazione di ebanisteria, decorazione figurativa e gusto antiquario, risultando particolarmente adatto a un’importante sala da pranzo o a un ambiente di rappresentanza.\n\nSono presenti segni e usure compatibili con l’età, con fessurazioni, piccoli sollevamenti e locali mancanze dell’impiallacciatura e degli intarsi, maggiormente visibili in alcuni esemplari.","description_en":"Suite of twelve veneered and finely inlaid chairs with cabriole legs, upholstered backs and decoration featuring classical figures, profiles, griffins, putti, coats of arms and foliage. Pale upholstery; age-related cracks and minor lifting to the veneer.","description_fr":"Suite de douze chaises plaquées et finement marquetées, pieds galbés, dossiers garnis et décors de figures classiques, profils, griffons, putti, armoiries et rinceaux. Garniture claire ; fissures et petits soulèvements du placage liés à l’âge.","images":["assets/images/A056/A056-01.webp","assets/images/A056/A056-02.webp","assets/images/A056/A056-03.webp","assets/images/A056/A056-04.webp","assets/images/A056/A056-05.webp","assets/images/A056/A056-06.webp","assets/images/A056/A056-07.webp","assets/images/A056/A056-08.webp","assets/images/A056/A056-09.webp","assets/images/A056/A056-10.webp","assets/images/A056/A056-11.webp","assets/images/A056/A056-12.webp","assets/images/A056/A056-13.webp","assets/images/A056/A056-14.webp","assets/images/A056/A056-15.webp","assets/images/A056/A056-16.webp","assets/images/A056/A056-17.webp","assets/images/A056/A056-18.webp","assets/images/A056/A056-19.webp","assets/images/A056/A056-20.webp","assets/images/A056/A056-21.webp","assets/images/A056/A056-22.webp","assets/images/A056/A056-23.webp","assets/images/A056/A056-24.webp","assets/images/A056/A056-Collage2.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"presumibilmente XIX secolo"},{"label":"Stile","value":"gusto neoclassico"},{"label":"Lavorazione","value":"intarsio figurativo e ornamentale"},{"label":"Materiale","value":"legni impiallacciati e intarsiati, tessuto"},{"label":"Quantità","value":"12 sedie"}],"epoch_it":"presumibilmente XIX secolo","style_it":"gusto neoclassico","material_it":"legni impiallacciati e intarsiati, tessuto"},"A057":{"category_key":"furniture","category_it":"Mobili","category_en":"Furniture","category_fr":"Mobilier","title_it":"Tavolo da gioco veneziano Luigi XV ad angoli lobati, XVIII secolo","title_en":"Venetian games table with lobed corners, eighteenth century","title_fr":"Table à jeux vénitienne à angles lobés, XVIIIe siècle","dimensions":"H 100 × L 100 × P 100 cm","description_it":"Raffinato tavolo da gioco veneziano di epoca Luigi XV, risalente al XVIII secolo, caratterizzato dall'elegante piano quadrangolare con profilo sagomato e caratteristici angoli lobati.\n\nIl piano è impreziosito da una ricca lavorazione a intarsio e impiallacciatura in essenze lignee pregiate, selezionate e disposte secondo un'articolata composizione geometrica. Le differenti venature della radica e dei legni creano un vivace effetto decorativo, con ampie riserve che seguono armoniosamente la particolare sagoma del mobile.\n\nLa fascia sottostante, anch'essa finemente impiallacciata, incorpora un cassetto centrale ed è sostenuta da quattro eleganti gambe mosse, coerenti con il gusto Luigi XV. Il bordo modanato segue l'andamento sinuoso del piano, accentuandone gli angoli lobati.\n\nUn pregevole esempio di ebanisteria veneziana settecentesca, nel quale l'eleganza delle forme si unisce alla ricchezza delle essenze lignee e alla qualità della lavorazione artigianale.","description_en":"Near-square games or writing table with refined veneered and inlaid top, lobed shaped corners, front drawer, cabriole legs and turned stretchers. Eighteenth-century Venetian production according to family documentation.","description_fr":"Table à jeux ou bureau de forme presque carrée, plateau plaqué et marqueté, angles lobés, tiroir frontal, pieds galbés et entretoises tournées. Production vénitienne du XVIIIe siècle selon la documentation familiale.","images":["assets/images/A057/A057-01.webp","assets/images/A057/A057-02.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XVIII secolo"},{"label":"Provenienza","value":"Venezia, Italia"},{"label":"Stile","value":"Luigi XV"},{"label":"Lavorazione","value":"Intarsio e impiallacciatura"},{"label":"Materiale","value":"Legno, radica ed essenze lignee pregiate"}],"epoch_it":"XVIII secolo","style_it":"Luigi XV","material_it":"Legno, radica ed essenze lignee pregiate"},"A058":{"category_key":"rugs_textiles","category_it":"Tappeti e tessili","category_en":"Rugs","category_fr":"Tapis","title_it":"Grande tappeto persiano annodato a mano con medaglioni floreali 635 × 390 cm","title_en":"Large hand-knotted Persian rug with floral medallions","title_fr":"Grand tapis persan noué main à médaillons floraux","dimensions":"635 × 390 cm","description_it":"A158 — Grande tappeto persiano annodato a mano a medaglioni 635 × 390 cm\n\nDESCRIZIONE\n\nImportante tappeto persiano di grandi dimensioni, interamente annodato a mano in lana di qualità e caratterizzato da una buona densità di nodi.\n\nIl vasto campo su fondo blu profondo è riccamente decorato da una fitta trama di motivi floreali e vegetali stilizzati. La composizione è dominata da un grande medaglione centrale nei toni dell’avorio e del bordeaux, circondato da numerosi medaglioni minori disposti armoniosamente all’interno del campo.\n\nParticolarmente elaborata la bordura multipla, scandita da grandi riserve polilobate alternate nei toni del bordeaux, verde salvia e avorio e accompagnate da fasce secondarie con motivi floreali continui.\n\nLa ricca tavolozza comprende blu profondo, bordeaux, rosso, avorio, rosa, verde, azzurro e tonalità ocra. La qualità della lavorazione, la complessità del disegno e le eccezionali dimensioni conferiscono al tappeto una notevole presenza decorativa e scenografica, ideale per grandi saloni e ambienti di rappresentanza.","description_en":"Imposing hand-knotted Persian wool rug with a midnight-blue field, polychrome medallions and a richly floral border in ivory, burgundy, sage and pale blue.","description_fr":"Imposant tapis persan en laine noué main, champ bleu nuit, médaillons polychromes et riche bordure florale ivoire, bordeaux, vert sauge et bleu clair. Patine et usures naturelles ; franges usées à restaurer.","images":["assets/images/A058/A058-01.webp","assets/images/A058/A058-02.webp","assets/images/A058/A058-03.webp","assets/images/A058/A058-04.webp","assets/images/A058/A058-05.webp","assets/images/A058/A058-06.webp","assets/images/A058/A058-07.webp","assets/images/A058/A058-08.webp","assets/images/A058/A058-09.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XX secolo"},{"label":"Materiale","value":"lana di alta qualità"},{"label":"Lavorazione","value":"annodato a mano, tessitura fine e ad alta densità di nodi"},{"label":"Superficie","value":"circa 24,8 m²"}],"epoch_it":"XX secolo","material_it":"lana di alta qualità"},"A059":{"category_key":"seating","category_it":"Sedute e salotti","category_en":"Seating","category_fr":"Sièges","title_it":"Coppia di poltroncine imbottite con rivestimento animalier","title_en":"Pair of leopard-print slipper chairs","title_fr":"Paire de chauffeuses imprimé léopard","dimensions":"H 76 × L 52 × P 47 cm ciascuna","description_it":"Coppia di eleganti poltroncine imbottite senza braccioli, caratterizzate da una linea compatta e avvolgente, con schienale leggermente sagomato e seduta ampia e confortevole. Il rivestimento presenta un motivo animalier leopardato nei toni del beige e nero, arricchito da profili decorativi a cordoncino intrecciato nero e oro che sottolineano i bordi della seduta e della struttura.\n\nLa parte inferiore è rifinita con una fascia tessile coordinata che copre la base, conferendo all’insieme un aspetto raffinato e decorativo. Le due poltroncine formano una coppia perfettamente coordinata, ideale sia in ambienti classici sia come elemento d’accento in interni più contemporanei.","description_en":"Coppia di poltroncine imbottite, rivestite in tessuto leopardato con passamaneria bicolore. Linea compatta e decorativa, ideali come sedute da conversazione o da camera.","description_fr":"Coppia di poltroncine imbottite, rivestite in tessuto leopardato con passamaneria bicolore. Linea compatta e decorativa, ideali come sedute da conversazione o da camera.","images":["assets/images/A059/A059-01.webp","assets/images/A059/A059-02.webp","assets/images/A059/A059-03.webp","assets/images/A059/A059-04.webp","assets/images/A059/A059-05.webp","assets/images/A059/A059-06.webp","assets/images/A059/A059-07.webp"],"status":"available","specs_it":[{"label":"EPOCA","value":"Seconda metà XX secolo"},{"label":"STILE","value":"Decorativo / Hollywood Regency"},{"label":"MATERIALE","value":"Struttura imbottita, tessuto animalier, passamaneria"}],"epoch_it":"Seconda metà XX secolo","style_it":"Decorativo / Hollywood Regency","material_it":"Struttura imbottita, tessuto animalier, passamaneria"},"A061":{"category_key":"lighting","category_it":"Illuminazione","category_en":"Lighting","category_fr":"Luminaires","title_it":"Catellani & Smith, grande lampadario Fil de Fer","title_en":"Catellani & Smith Fil de Fer ceiling light","title_fr":"Suspension Fil de Fer de Catellani & Smith","dimensions":"Da misurare","description_it":"Grande lampada a sospensione Fil de Fer di Catellani & Smith, uno dei modelli più riconoscibili della produzione della celebre azienda italiana di illuminazione.\n\nLa lampada è caratterizzata dalla scenografica struttura sferica composta da filo metallico modellato e intrecciato a mano, all’interno della quale sono distribuiti numerosi piccoli punti luce. La particolare costruzione crea un effetto luminoso suggestivo e una trama di ombre sulle superfici circostanti, trasformando la lampada in un vero elemento scultoreo.\n\nIl modello Fil de Fer, ideato da Enzo Catellani, è diventato una delle creazioni iconiche di Catellani & Smith ed è particolarmente apprezzato nelle versioni di grandi dimensioni.\n\nCompleta di rosone e sistema di sospensione. Dalle fotografie appare in buone condizioni generali e funzionante. Eventuali lievi segni sono compatibili con l'uso.\n\nDesigner: Enzo Catellani","description_en":"Scultura luminosa sferica in filo di alluminio intrecciato con numerosi punti luce, modello Fil de Fer di Catellani & Smith.","description_fr":"Scultura luminosa sferica in filo di alluminio intrecciato con numerosi punti luce, modello Fil de Fer di Catellani & Smith.","images":["assets/images/A061/A061-01.webp","assets/images/A061/A061-02.webp","assets/images/A061/A061-03.webp","assets/images/A061/A061-04.webp","assets/images/A061/A061-05.webp","assets/images/A061/A061-06.webp","assets/images/A061/A061-07.webp"],"status":"available","specs_it":[{"label":"Designer","value":"Enzo Catellani"},{"label":"Produttore","value":"Catellani & Smith"},{"label":"Modello","value":"Fil de Fer"},{"label":"Paese","value":"Italia"},{"label":"Epoca","value":"contemporaneo"},{"label":"Materiale","value":"filo metallico / alluminio"}],"epoch_it":"contemporaneo","material_it":"filo metallico / alluminio"},"A062":{"category_key":"musical","category_it":"Strumenti musicali","category_en":"Musical Instruments","category_fr":"Instruments de musique","title_it":"Pianoforte verticale Kawai BL-31 nero lucido con panchetta","title_en":"Kawai upright piano","title_fr":"Piano droit Kawai","dimensions":"H 124 × L 153 × P 61 cm","description_it":"Pianoforte verticale Kawai modello BL-31, realizzato in Giappone, con elegante mobile in finitura nera lucida. Strumento dalle linee classiche e sobrie, completo della propria panchetta coordinata.\n\nLe fotografie dell’interno mostrano chiaramente il marchio Kawai, l’indicazione del modello BL-31 e il numero di serie K939398. La meccanica interna completa con martelletti, corde e componenti originali visibili in fotografia.\n\nLa tastiera è composta da 88 tasti e il pianoforte presenta i tradizionali tre pedali. Sul lato della tastiera è inoltre presente l’etichetta dello storico rivenditore milanese D. Tagliabue, Via Meda 14, Milano.\n\nIl pianoforte poggia su quattro rotelle integrate ai piedi, che ne agevolano i piccoli spostamenti su superfici idonee\n\nIl mobile presenta una finitura nera lucida molto riflettente, con normali segni compatibili con l’uso e l’età. Il sedile della panchetta è rovinato ed è attualmente coperto da un tessuto nero di seta; si consiglia il rifacimento del rivestimento.","description_en":"Pianoforte verticale Kawai in finitura scura, completo di tastiera e mobile. Stato meccanico, accordatura e numero di serie da verificare.","description_fr":"Pianoforte verticale Kawai in finitura scura, completo di tastiera e mobile. Stato meccanico, accordatura e numero di serie da verificare.","images":["assets/images/A062/A062-01.webp","assets/images/A062/A062-02.webp","assets/images/A062/A062-03.webp","assets/images/A062/A062-04.webp","assets/images/A062/A062-05.webp","assets/images/A062/A062-06.webp","assets/images/A062/A062-07.webp","assets/images/A062/A062-08.webp","assets/images/A062/A062-09.webp","assets/images/A062/A062-10.webp","assets/images/A062/A062-11.webp"],"status":"available","specs_it":[{"label":"Marca","value":"Kawai"},{"label":"Modello","value":"BL-31"},{"label":"Numero di serie","value":"K939398"},{"label":"Produzione","value":"Giappone"},{"label":"Finitura","value":"nero lucido"},{"label":"Tastiera","value":"88 tasti"},{"label":"Pedali","value":"3"},{"label":"Base","value":"4 rotelle"},{"label":"Accessori","value":"panchetta coordinata, con seduta da rifoderare"}]},"A063":{"category_key":"furniture","category_it":"Mobili","category_en":"Furniture","category_fr":"Mobilier","title_it":"Grande testiera matrimoniale in legno dorato con ricamo floreale a mano – Cannetta Milano","title_en":"Decorative double headboard","title_fr":"Tête de lit double décorative","dimensions":"L 200 × H 155 × P 8 cm circa","description_it":"Importante testiera da letto matrimoniale di grandi dimensioni, caratterizzata da una ricca struttura lignea intagliata e dorata, con profilo mosso e scenografica cimasa superiore a volute e motivi vegetali.\n\nLa parte centrale è interamente rivestita in tessuto nei toni beige/rosa cipria, rifinito lungo il perimetro da cordonatura decorativa. Al centro spicca un elegante medaglione con composizione floreale, ricamato interamente a mano.\n\nIl lavoro tessile è stato realizzato a mano da Cannetta Milano, rinomata realtà milanese specializzata in ricami e lavorazioni decorative di pregio.\n\nL'insieme presenta un gusto elegante e fortemente decorativo, ispirato agli arredi rococò e Luigi XV, particolarmente adatto come elemento protagonista di una camera da letto classica o di un ambiente di rappresentanza.\n\nIl retro conserva la struttura lignea e permette di apprezzare la costruzione della testiera.","description_en":"Testiera matrimoniale imbottita con profilo sagomato e rivestimento decorativo.","description_fr":"Testiera matrimoniale imbottita con profilo sagomato e rivestimento decorativo.","images":["assets/images/A063/A063-01.webp","assets/images/A063/A063-02.webp"],"status":"available","specs_it":[{"label":"Materiali","value":"legno intagliato e dorato, tessuto, ricamo a mano"},{"label":"Stile","value":"Luigi XV / Rococò"},{"label":"Epoca","value":"XX secolo"},{"label":"Provenienza/lavorazione","value":"Cannetta, Milano"}],"epoch_it":"XX secolo","style_it":"Luigi XV / Rococò","material_it":"legno intagliato e dorato, tessuto, ricamo a mano"},"A064":{"category_key":"mirrors","category_it":"Specchi","category_en":"Mirrors","category_fr":"Miroirs","title_it":"Grande specchiera veneziana dorata in stile Rococò -  Luigi XV","title_en":"Ornate antique mirror","title_fr":"Miroir ancien ornementé","dimensions":"H 200 × L 120 × P 30 cm circa","description_it":"Grande specchiera decorativa di gusto veneziano, caratterizzata da un’imponente cornice sagomata e riccamente intagliata con motivi rocaille, volute, foglie e ornamenti floreali. La struttura presenta un profilo particolarmente elaborato, con cimasa mossa e numerosi elementi specchiati inseriti tra gli intagli della cornice.\n\nLa superficie dorata conserva una piacevole patina del tempo, con usure e variazioni cromatiche coerenti con l’età. Gli specchi presentano una marcata ossidazione e perdita dell’argentatura, particolarmente evidente nella grande lastra centrale e nei pannelli perimetrali, che conferisce all'insieme il tipico aspetto degli specchi antichi.\n\nEsemplare di grande presenza scenografica, adatto come elemento centrale sopra una console o un camino e particolarmente interessante per le dimensioni importanti e la ricchezza dell'apparato decorativo.","description_en":"Specchio antico con importante cornice scolpita e dorata, dal profilo mosso e riccamente ornato.","description_fr":"Specchio antico con importante cornice scolpita e dorata, dal profilo mosso e riccamente ornato.","images":["assets/images/A064/A064-01.webp","assets/images/A064/A064-02.webp","assets/images/A064/A064-03.webp","assets/images/A064/A064-04.webp","assets/images/A064/A064-05.webp","assets/images/A064/A064-06.webp","assets/images/A064/A064-07.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"Venezia, metà XVIII secolo"},{"label":"Stile","value":"Rococò / gusto veneziano"},{"label":"Materiale","value":"legno intagliato e dorato, vetro specchiato"}],"epoch_it":"Venezia, metà XVIII secolo","style_it":"Rococò / gusto veneziano","material_it":"legno intagliato e dorato, vetro specchiato"},"A065":{"category_key":"furniture","category_it":"Mobili","category_en":"Furniture","category_fr":"Mobilier","title_it":"Grande trumeau/secrétaire a ribalta in noce e radica con alzata a specchi – XIX secolo","title_en":"Antique bureau bookcase with mirrored doors","title_fr":"Bureau bibliothèque ancien à portes miroir","dimensions":"H 250 × L 120 × P 60 cm circa","description_it":"Imponente trumeau con secrétaire a ribalta, realizzato in legno di noce e ricche impiallacciature in radica, caratterizzato da una notevole altezza di circa 250 cm e da una struttura architettonica particolarmente scenografica.\n\nLa parte inferiore presenta un fronte mosso con tre ordini di cassetti, impreziositi dalla bella venatura della radica e da ferramenta decorativa in metallo. La ribalta si apre formando un ampio piano di scrittura rivestito in materiale scuro e rivela un interno organizzato con numerosi piccoli cassetti, vani e scomparti.\n\nLa parte superiore è costituita da un'alta alzata a due ante. Le ante sono dotate esternamente di grandi specchi sagomati e, una volta aperte, rivelano un vano interamente rivestito in tessuto damascato, suddiviso da ripiani. La cimasa superiore, di gusto architettonico, presenta profili curvilinei e pinnacoli torniti.\n\nMobile di grande presenza decorativa, interessante sia per la qualità e varietà delle venature del legno sia per la complessità della costruzione e la combinazione di secrétaire, cassettiera, specchiera e vano espositivo.\n\nDalle fotografie sono visibili segni di utilizzo e usura compatibili con l'età, in particolare sul piano della ribalta, sugli interni e in alcuni punti dell'impiallacciatura. Gli specchi mostrano ossidazioni e alterazioni della superficie riflettente, particolarmente evidenti lungo alcune zone. Questi elementi sono coerenti con un mobile antico e andrebbero documentati chiaramente nell'annuncio.","description_en":"Importante trumeau-scrittoio antico con fronte mosso, ricca impiallacciatura, ribalta attrezzata, numerosi cassetti e alzata a due ante specchiate.","description_fr":"Importante trumeau-scrittoio antico con fronte mosso, ricca impiallacciatura, ribalta attrezzata, numerosi cassetti e alzata a due ante specchiate.","images":["assets/images/A065/A065-01.webp","assets/images/A065/A065-02.webp","assets/images/A065/A065-03.webp","assets/images/A065/A065-04.webp","assets/images/A065/A065-05.webp","assets/images/A065/A065-06.webp","assets/images/A065/A065-07.webp","assets/images/A065/A065-08.webp","assets/images/A065/A065-09.webp","assets/images/A065/A065-10.webp","assets/images/A065/A065-11.webp","assets/images/A065/A065-12.webp","assets/images/A065/A065-13.webp"],"status":"available","specs_it":[{"label":"Materiali","value":"noce, radica e altri legni impiallacciati, specchio, tessuto, metallo"},{"label":"Tipologia","value":"trumeau / secrétaire a ribalta con alzata"},{"label":"Epoca","value":"probabilmente XIX secolo"},{"label":"Stile","value":"gusto Luigi Filippo / storicista, da verificare dal vivo"}],"epoch_it":"probabilmente XIX secolo","style_it":"gusto Luigi Filippo / storicista, da verificare dal vivo","material_it":"noce, radica e altri legni impiallacciati, specchio, tessuto, metallo"},"A066":{"category_key":"furniture","category_it":"Mobili","category_en":"Furniture","category_fr":"Mobilier","title_it":"Consolle cinese laccata nera con sostegni sagomati","title_en":"Black lacquer console table","title_fr":"Console en laque noire","dimensions":"H 81 × L 83 cm circa","description_it":"Elegante consolle di gusto cinese realizzata in legno laccato nero, caratterizzata da una linea essenziale ma fortemente decorativa.\n\nIl piano rettangolare presenta le caratteristiche estremità rialzate a voluta, mentre la fascia sottostante è arricchita da elementi sagomati e traforati ispirati alla tradizione dell'arredo orientale. Le alte gambe dritte sono collegate lateralmente da traverse decorative traforate.\n\nLa laccatura nera lucida è impreziosita da sottili profili nei toni del rosso, particolarmente visibili lungo i bordi e le parti intagliate.\n\nUn mobile versatile e di grande effetto decorativo, utilizzabile come consolle da ingresso, tavolo da parete o elemento d'accento in un ambiente sia classico sia contemporaneo.","description_en":"Consolle in legno laccato nero con piano rettangolare, quattro sostegni e profili sagomati di gusto orientale.","description_fr":"Consolle in legno laccato nero con piano rettangolare, quattro sostegni e profili sagomati di gusto orientale.","images":["assets/images/A066/A066-01.webp","assets/images/A066/A066-02.webp","assets/images/A066/A066-03.webp","assets/images/A066/A066-04.webp","assets/images/A066/A066-05.webp"],"status":"available","specs_it":[{"label":"Materiale","value":"legno laccato"},{"label":"Colore","value":"nero con profili rossi"},{"label":"Stile","value":"cinese / orientale"},{"label":"Paese d'origine","value":"Cina"},{"label":"Epoca","value":"XX secolo"}],"epoch_it":"XX secolo","style_it":"cinese / orientale","material_it":"legno laccato"},"A067":{"category_key":"prints_works_on_paper","category_it":"Stampe e opere su carta","category_en":"Paintings","category_fr":"Peintures","title_it":"Calligrafia cinese su carta con sigilli rossi, incorniciata","title_en":"Framed Chinese calligraphy scroll","title_fr":"Calligraphie chinoise encadrée","dimensions":"H 163 × L 50 cm","description_it":"Elegante opera calligrafica cinese di formato verticale, eseguita a inchiostro nero su carta e caratterizzata da più colonne di ideogrammi tracciati a pennello.\n\nLa composizione presenta diversi sigilli rossi, elemento tradizionalmente associato alla firma, all’autore o alla provenienza dell’opera. La calligrafia è montata su un supporto decorativo nei toni del grigio e conservata sotto vetro entro una sobria cornice nera, che ne valorizza lo sviluppo verticale.","description_en":"Calligrafia cinese su carta con sigilli rossi, montata su supporto decorativo e presentata entro cornice nera.","description_fr":"Calligrafia cinese su carta con sigilli rossi, montata su supporto decorativo e presentata entro cornice nera.","images":["assets/images/A067/A067-01.webp","assets/images/A067/A067-02.webp","assets/images/A067/A067-03.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XX secolo"},{"label":"Paese d’origine","value":"Cina"},{"label":"Tecnica/materiale","value":"inchiostro su carta, montaggio decorativo, vetro e cornice lignea nera"},{"label":"Dimensioni complessive","value":"H 163 × L 50 cm"}],"epoch_it":"XX secolo","material_it":"inchiostro su carta, montaggio decorativo, vetro e cornice lignea nera"},"A068":{"category_key":"lighting","category_it":"Illuminazione","category_en":"Lighting","category_fr":"Luminaires","title_it":"Lampada da tavolo a tre luci in ottone con paralume","title_en":"Three-light brass table lamp","title_fr":"Lampe de table en laiton à trois lumières","dimensions":"H 66 × Ø 34 cm circa","description_it":"Elegante lampada da tavolo a tre luci, realizzata in ottone e metallo con finitura brunita e dorata, ispirata ai modelli a candelabro di gusto Luigi XVI.\n\nLa struttura presenta una base sagomata e modanata, fusto tornito con elemento scanalato e tre bracci ricurvi con portalampada a finta candela color avorio. Completa la lampada un ampio paralume svasato in tessuto color prugna/bordeaux, bordato in metallo e sostenuto da una struttura superiore con terminale decorativo.\n\nUn complemento d'arredo elegante e scenografico, capace di inserirsi sia in ambienti classici sia in contesti contemporanei.\n\nCaratteristiche:","description_en":"Lampada da tavolo in ottone con fusto tornito, base sagomata e tre bracci curvilinei, completa di paralume color prugna.","description_fr":"Lampada da tavolo in ottone con fusto tornito, base sagomata e tre bracci curvilinei, completa di paralume color prugna.","images":["assets/images/A068/A068-01.webp","assets/images/A068/A068-02.webp","assets/images/A068/A068-03.webp","assets/images/A068/A068-04.webp","assets/images/A068/A068-05.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XX secolo"},{"label":"Stile","value":"Luigi XVI / Neoclassico"},{"label":"Materiale","value":"ottone e metallo, paralume in tessuto"},{"label":"Luci","value":"3"}],"epoch_it":"XX secolo","style_it":"Luigi XVI / Neoclassico","material_it":"ottone e metallo, paralume in tessuto"},"A069":{"category_key":"furniture","category_it":"Mobili","category_en":"Furniture","category_fr":"Mobilier","title_it":"Tavolino ottagonale in legno con ripiano inferiore","title_en":"Low octagonal occasional table","title_fr":"Table basse octogonale","dimensions":"H 55 × L 57 × P 57 cm","description_it":"Tavolino da appoggio in legno dalla caratteristica forma ottagonale, con piano superiore sagomato e ampio ripiano inferiore coordinato. La struttura è sostenuta da elementi verticali a sezione piatta, che conferiscono al mobile un disegno semplice e geometrico.\n\nLa linea essenziale e funzionale richiama il gusto del primo Novecento, con una costruzione sobria che mette in evidenza la tonalità calda e le venature naturali del legno. Adatto come tavolino laterale da salotto, comodino o elemento d’appoggio.\n\nIl mobile conserva la finitura d'epoca e presenta evidenti segni di utilizzo, soprattutto sui piani: graffi, aloni, piccole macchie e usura superficiale. Condizioni coerenti con l'età e l'uso e suscettibili di miglioramento con un intervento di pulitura e lucidatura.","description_en":"Tavolino basso di forma ottagonale in legno, con quattro sostegni laterali e ripiano inferiore, senza piano intermedio.","description_fr":"Tavolino basso di forma ottagonale in legno, con quattro sostegni laterali e ripiano inferiore, senza piano intermedio.","images":["assets/images/A069/A069-01.webp","assets/images/A069/A069-02.webp","assets/images/A069/A069-03.webp","assets/images/A069/A069-04.webp","assets/images/A069/A069-05.webp","assets/images/A069/A069-06.webp","assets/images/A069/A069-07.webp","assets/images/A069/A069-08.webp","assets/images/A069/A069-09.webp","assets/images/A069/A069-10.webp","assets/images/A069/A069-11.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"prima metà del XX secolo"},{"label":"Stile","value":"Art Déco / gusto razionalista"},{"label":"Materiale","value":"legno"}],"epoch_it":"prima metà del XX secolo","style_it":"Art Déco / gusto razionalista","material_it":"legno"},"A070":{"category_key":"furniture","category_it":"Mobili","category_en":"Furniture","category_fr":"Mobilier","title_it":"Carrello da servizio in palissandro e ottone di Ico Parisi – Italia, anni 1950","title_en":"Vintage two-tier serving trolley","title_fr":"Desserte vintage à deux plateaux","dimensions":"H 70 × L 67 × P 46 cm","description_it":"Carrello da servizio italiano disegnato da Ico Parisi negli anni Cinquanta, realizzato in palissandro, ottone e vetro.\n\nLa struttura sagomata in palissandro presenta due ripiani rettangolari in vetro con bordature in ottone, un’impugnatura superiore e quattro ruote. Il disegno leggero e geometrico è rappresentativo del design italiano del secondo dopoguerra.\n\nUtilizzabile come carrello portavivande, mobile bar o complemento d’arredo.\n\nDesigner: Ico Parisi","description_en":"Carrello da servizio pieghevole con struttura in legno, dettagli in ottone, due ripiani in vetro e ruote.","description_fr":"Carrello da servizio pieghevole con struttura in legno, dettagli in ottone, due ripiani in vetro e ruote.","images":["assets/images/A070/A070-01.webp","assets/images/A070/A070-02.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"metà XX secolo, circa anni 1950–1960"},{"label":"Stile","value":"Mid-Century / modernariato"},{"label":"Materiali","value":"legno, vetro, metallo color ottone"}],"epoch_it":"metà XX secolo, circa anni 1950–1960","style_it":"Mid-Century / modernariato","material_it":"legno, vetro, metallo color ottone"},"A071":{"category_key":"rugs_textiles","category_it":"Tappeti e tessili","category_en":"Rugs","category_fr":"Tapis","title_it":"Tappeto caucasico annodato a mano a motivi geometrici","title_en":"Hand-knotted Caucasian rug","title_fr":"Tapis caucasien noué main","dimensions":"270 × 165 cm","description_it":"Tappeto caucasico annodato a mano, caratterizzato da una vivace composizione geometrica sviluppata su un intenso fondo rosso.\n\nIl campo centrale presenta una successione regolare di grandi motivi geometrici e medaglioni stilizzati disposti lungo l’asse longitudinale, accompagnati da elementi ornamentali minori. La composizione è racchiusa da molteplici bordure decorate con motivi geometrici e floreali, nei toni del rosso, blu scuro, avorio, arancio e azzurro.\n\nLa lavorazione artigianale e il rovescio permettono di apprezzare l’annodatura manuale e la buona densità dei nodi. La lana e la ricca combinazione cromatica conferiscono al tappeto un aspetto caldo e decorativo, tipico della tradizione tessile caucasica.\n\nLe leggere irregolarità della tessitura e del disegno costituiscono caratteristiche proprie della lavorazione manuale. Un esemplare di piacevole presenza decorativa, facilmente inseribile sia in ambienti classici sia contemporanei.","description_en":"Tappeto annodato a mano con campo blu scuro, grandi medaglioni geometrici color rosa antico e ricca bordura policroma.","description_fr":"Tappeto annodato a mano con campo blu scuro, grandi medaglioni geometrici color rosa antico e ricca bordura policroma.","images":["assets/images/A071/A071-01.webp","assets/images/A071/A071-02.webp","assets/images/A071/A071-03.webp","assets/images/A071/A071-04.webp","assets/images/A071/A071-05.webp","assets/images/A071/A071-Collage.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XX secolo"},{"label":"Provenienza","value":"area caucasica"},{"label":"Stile","value":"Caucasico, motivi geometrici"},{"label":"Lavorazione","value":"Annodato a mano"},{"label":"Materiale","value":"Lana"}],"epoch_it":"XX secolo","style_it":"Caucasico, motivi geometrici","material_it":"Lana"},"A072":{"category_key":"rugs_textiles","category_it":"Tappeti e tessili","category_en":"Rugs","category_fr":"Tapis","title_it":"Tappeto caucasico a motivi geometrici, annodato a mano","title_en":"Large hand-knotted Caucasian rug","title_fr":"Grand tapis caucasien noué main","dimensions":"127 × 180 cm circa","description_it":"Tappeto caucasico annodato a mano, caratterizzato da una vivace composizione geometrica su fondo blu scuro. Il campo centrale presenta tre grandi medaglioni poligonali nei toni del rosso, decorati internamente da motivi geometrici stilizzati e circondati da piccoli elementi floreali e simbolici policromi.\n\nAmpia bordura su fondo rosso con successione regolare di grandi rosette geometriche multicolori e piccoli motivi ornamentali. La palette comprende rosso mattone, blu scuro, azzurro, avorio, verde e arancio, con piacevoli variazioni cromatiche dovute all'età e all'uso.\n\nLa tessitura e i dettagli visibili sul retro confermano una lavorazione artigianale. Il tappeto presenta usura diffusa e riduzione del vello compatibili con l'età, particolarmente visibili in alcune zone del campo centrale e lungo i bordi. Queste caratteristiche contribuiscono alla patina complessiva del pezzo.","description_en":"Grande tappeto annodato a mano con fondo rosso, motivi geometrici stilizzati e bordure multiple nei toni del blu, avorio e arancio.","description_fr":"Grande tappeto annodato a mano con fondo rosso, motivi geometrici stilizzati e bordure multiple nei toni del blu, avorio e arancio.","images":["assets/images/A072/A072-01.webp","assets/images/A072/A072-02.webp","assets/images/A072/A072-03.webp","assets/images/A072/A072-04.webp","assets/images/A072/A072-05.webp","assets/images/A072/A072-06.webp"],"status":"available","specs_it":[{"label":"Epoca indicativa","value":"prima metà del XX secolo."},{"label":"Area","value":"Caucaso / area caucasica."}]},"A073":{"category_key":"seating","category_it":"Sedute e salotti","category_en":"Seating","category_fr":"Sièges","title_it":"Divanetto / panca imbottita in legno intagliato, stile Luigi XV rivestito a righe","title_en":"Louis XV style upholstered settee","title_fr":"Canapé de style Louis XV","dimensions":"L 170 × H 63 × P 58 cm","description_it":"Elegante divanetto a tre posti con struttura in legno sagomato e intagliato, caratterizzato da una linea sinuosa di gusto Luigi XV.\n\nLa fascia inferiore presenta profili mossi e motivi decorativi intagliati a conchiglia, ripetuti lungo il fronte. La struttura poggia su cinque gambe anteriori arcuate e rastremate, che conferiscono leggerezza all'insieme.\n\nSeduta e braccioli sono completamente imbottiti e rivestiti in tessuto a righe verticali nei toni beige e marrone, impreziosito da piccoli motivi decorativi e rifinito da passamaneria coordinata. Il contrasto tra il legno caldo e il rivestimento crea un effetto elegante e particolarmente decorativo.\n\nDimensioni\nL 170 × H 63 × P 58 cm","description_en":"Divanetto a tre posti con struttura lignea sagomata e intagliata, gambe mosse e rivestimento a righe nei toni beige e marrone.","description_fr":"Divanetto a tre posti con struttura lignea sagomata e intagliata, gambe mosse e rivestimento a righe nei toni beige e marrone.","images":["assets/images/A073/A073-01.webp","assets/images/A073/A073-02.webp","assets/images/A073/A073-03.webp","assets/images/A073/A073-04.webp","assets/images/A073/A073-05.webp","assets/images/A073/A073-06.webp","assets/images/A073/A073-07.webp","assets/images/A073/A073-08.webp","assets/images/A073/A073-09.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XX secolo"},{"label":"Stile","value":"Luigi XV / revival francese"},{"label":"Materiale","value":"legno intagliato, imbottitura e tessuto"}],"epoch_it":"XX secolo","style_it":"Luigi XV / revival francese","material_it":"legno intagliato, imbottitura e tessuto"},"A074":{"category_key":"paintings","category_it":"Dipinti","category_en":"Paintings","category_fr":"Peintures","title_it":"Veduta del Colosseo con figure e paesaggio romano – XIX secolo","title_en":"View of the Colosseum with figures","title_fr":"Vue du Colisée avec personnages","dimensions":"H 90 × L 107 cm circa, cornice inclusa","description_it":"Grande dipinto raffigurante una veduta del Colosseo inserita in un ampio paesaggio romano, animato da piccoli gruppi di figure lungo un sentiero in primo piano.\n\nLa composizione presenta il monumento sul lato destro, parzialmente immerso nella vegetazione e nelle ombre, mentre sulla sinistra si sviluppano alberi e quinte paesaggistiche che conducono lo sguardo verso lo sfondo. Le figure, distribuite lungo il percorso, conferiscono movimento e carattere narrativo alla scena.\n\nLa tavolozza è dominata da tonalità calde e terrose, con un cielo luminoso e sfumato che crea un forte contrasto con le zone più scure del paesaggio. L'opera richiama la tradizione delle vedute romane e dei paesaggi con rovine, molto apprezzata tra XVIII e XIX secolo.\n\nIl dipinto è inserito in una bella cornice dorata con modanature decorative, coerente con il gusto classico dell'opera.","description_en":"Dipinto di gusto vedutista raffigurante il Colosseo e le rovine circostanti, animato da numerose figure, entro cornice dorata. Autore, tecnica ed epoca da verificare.","description_fr":"Dipinto di gusto vedutista raffigurante il Colosseo e le rovine circostanti, animato da numerose figure, entro cornice dorata. Autore, tecnica ed epoca da verificare.","images":["assets/images/A074/A074-01.webp","assets/images/A074/A074-02.webp","assets/images/A074/A074-03.webp","assets/images/A074/A074-04.webp","assets/images/A074/A074-05.webp","assets/images/A074/A074-06.webp","assets/images/A074/A074-07.webp"],"status":"available","specs_it":[{"label":"Tecnica","value":"dipinto su tela"},{"label":"Soggetto","value":"veduta del Colosseo con figure"},{"label":"Epoca","value":"probabilmente XIX secolo"},{"label":"Stile","value":"vedutismo / paesaggio romantico"},{"label":"Paese d'origine","value":"Italia"},{"label":"Cornice","value":"dorata, decorata"}],"epoch_it":"probabilmente XIX secolo","style_it":"vedutismo / paesaggio romantico"},"A075":{"category_key":"lighting","category_it":"Illuminazione","category_en":"Lighting","category_fr":"Luminaires","title_it":"Coppia di applique a due luci con pendenti in cristallo","title_en":"Pair of crystal wall lights","title_fr":"Paire d’appliques en cristal","dimensions":"H 45 × L 30 × P 18 cm circa ciascuna","description_it":"Coppia di eleganti applique decorative a due luci, caratterizzate da una struttura in metallo patinato con bracci sinuosi e ricca decorazione di pendenti in cristallo trasparente e leggermente ametista.\n\nLa composizione è arricchita da elementi floreali in cristallo, grandi gocce sfaccettate e pendenti di diverse forme e dimensioni, che conferiscono alle applique un aspetto particolarmente luminoso e scenografico. Le due luci sono completate da piccoli paralumi plissettati in tessuto beige con bordure in pizzo.\n\nLa patina della struttura metallica e la varietà dei cristalli conferiscono alla coppia un piacevole carattere d'epoca, adatto sia ad ambienti classici sia come elemento decorativo in interni contemporanei.\n\nCaratteristiche:","description_en":"Coppia di appliques a due luci con struttura metallica, fiori e pendenti in cristallo trasparente e ametista, complete di piccoli paralumi plissettati.","description_fr":"Coppia di appliques a due luci con struttura metallica, fiori e pendenti in cristallo trasparente e ametista, complete di piccoli paralumi plissettati.","images":["assets/images/A075/A075-01.webp","assets/images/A075/A075-02.webp","assets/images/A075/A075-03.webp","assets/images/A075/A075-04.webp","assets/images/A075/A075-05.webp","assets/images/A075/A075-06.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XX secolo"},{"label":"Stile","value":"Luigi XV / Rocaille"},{"label":"Materiale","value":"metallo patinato, cristallo e tessuto"},{"label":"Luci","value":"2 per applique"},{"label":"Quantità","value":"coppia (2 applique)"}],"epoch_it":"XX secolo","style_it":"Luigi XV / Rocaille","material_it":"metallo patinato, cristallo e tessuto"},"A076":{"category_key":"decorative_objects","category_it":"Oggetti decorativi","category_en":"Decorative Objects","category_fr":"Objets décoratifs","title_it":"Coppia di urne decorative dorate con basi in marmo nero – XX secolo","title_en":"Pair of gilt bronze urns on marble bases","title_fr":"Paire d’urnes en bronze doré sur socles en marbre","dimensions":"Dimensioni ciascuna: H 33 × L 14 × P 11 cm circa","description_it":"Elegante coppia di urne decorative in metallo dorato, riccamente lavorate a rilievo con scene figurate, putti, motivi vegetali, foglie d’acanto e mascheroni.\n\nLa parte superiore presenta corpo a vaso con ampia bocca e anse laterali sagomate. La decorazione è particolarmente ricca, con figure in rilievo inserite entro motivi di gusto classico e neorinascimentale.\n\nOgni urna poggia su un alto basamento cilindrico in marmo nero venato di bianco, completato da base quadrata e modanature nere.\n\nL’insieme ha forte presenza decorativa ed è particolarmente adatto a una consolle, camino, ingresso o ambiente classico-contemporaneo.","description_en":"Coppia di urne decorative dorate, riccamente lavorate a rilievo con figure, mascheroni e motivi vegetali, su basi cilindriche in marmo scuro.","description_fr":"Coppia di urne decorative dorate, riccamente lavorate a rilievo con figure, mascheroni e motivi vegetali, su basi cilindriche in marmo scuro.","images":["assets/images/A076/A076-01.webp","assets/images/A076/A076-02.webp","assets/images/A076/A076-03.webp","assets/images/A076/A076-04.webp","assets/images/A076/A076-05.webp","assets/images/A076/A076-06.webp","assets/images/A076/A076-07.webp","assets/images/A076/A076-08.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XX secolo"},{"label":"Stile","value":"neoclassico / neorinascimentale"},{"label":"Materiali","value":"metallo dorato e marmo nero"},{"label":"Dimensioni ciascuna","value":"H 33 × L 14 × P 11 cm circa"}],"epoch_it":"XX secolo","style_it":"neoclassico / neorinascimentale","material_it":"metallo dorato e marmo nero"},"A077":{"category_key":"decorative_objects","category_it":"Oggetti decorativi","category_en":"Decorative Objects","category_fr":"Objets décoratifs","title_it":"Coppia di angioletti dorati su volute rocaille","title_en":"Pair of gilt cherub ornaments","title_fr":"Paire de décors dorés aux putti","dimensions":"H 30 × L 33 × P 13 cm circa, ciascuno","description_it":"Elegante coppia di elementi decorativi dorati raffiguranti angioletti, disposti in posizione speculare e inseriti entro un ricco intreccio di volute rocaille, foglie d’acanto e motivi vegetali.\n\nLe figure, finemente modellate, sono rappresentate inginocchiate e accompagnate da elementi floreali. Particolarmente elaborata la base, caratterizzata da ampie volute traforate e sinuose che conferiscono alla coppia un forte effetto plastico e scenografico.\n\nLa finitura dorata presenta una piacevole patina e naturali variazioni di tonalità. Sono presenti segni del tempo, usure della doratura e piccole mancanze negli elementi decorativi, visibili nelle fotografie.\n\nUna coppia di grande effetto decorativo, ideale per essere collocata simmetricamente su un camino, una console o un mobile, ma adatta anche a un ambiente contemporaneo come elemento di contrasto.\n\nDimensioni di ciascun elemento: H 30 × L 33 × P 13 cm circa.","description_en":"Coppia di elementi decorativi dorati raffiguranti putti con uccelli, adagiati su elaborate volute rocaille.","description_fr":"Coppia di elementi decorativi dorati raffiguranti putti con uccelli, adagiati su elaborate volute rocaille.","images":["assets/images/A077/A077-01.webp","assets/images/A077/A077-02.webp","assets/images/A077/A077-03.webp","assets/images/A077/A077-04.webp","assets/images/A077/A077-05.webp","assets/images/A077/A077-06.webp"],"status":"available","specs_it":[{"label":"Dimensioni di ciascun elemento","value":"H 30 × L 33 × P 13 cm circa."}]},"A078":{"category_key":"prints_works_on_paper","title_it":"“Maternità” — Grafica d’autore firmata e numerata 66/70, 1974","category_it":"Stampe e opere su carta","dimensions":"H 66 × L 48 cm","description_it":"Raffinata opera grafica su carta raffigurante una maternità, realizzata nel 1974 e appartenente a una tiratura limitata di 70 esemplari, di cui questo foglio reca la numerazione 66/70.\n\nLa composizione rappresenta una figura materna che accoglie tra le braccia un bambino addormentato. Le due figure sono costruite attraverso un tratto rapido, essenziale ed espressivo, con linee nere decise e leggere sovrapposizioni tonali. Il volto allungato della madre, appena delineato, domina la composizione mentre il bambino è raccolto nella parte inferiore, creando un'immagine intima e delicata incentrata sul legame materno.\n\nL'impostazione stilizzata, l'economia del segno e la deformazione volutamente elegante delle figure sono caratteristiche della ricerca figurativa della seconda metà del Novecento. L'ampio spazio chiaro lasciato attorno ai soggetti accentua ulteriormente la forza del disegno e conferisce all'opera un carattere moderno ed essenziale.\n\nSul margine inferiore sono presenti a matita il titolo “Maternità”, la numerazione 66/70 e la firma dell'artista. All'interno della composizione compare inoltre una firma accompagnata dalla data ’74. In alto a destra è presente una dedica manoscritta personale riferita alla nascita di Chiara, elemento che documenta la storia privata dell'esemplare.\n\nL'opera è conservata sotto vetro, incorniciata con ampio passe-partout chiaro e cornice in legno dorato, impreziosita da un sottile profilo interno color bordeaux. La cornice presenta lievi segni del tempo coerenti con l'età dell'insieme.\n\nPer la sua delicatezza e per l'immediatezza del soggetto, l'opera si presta particolarmente a camere, salotti e ambienti raccolti, ma può essere inserita anche in interni contemporanei grazie alla semplicità della composizione grafica.\n\nEPOCA\n1974\n\nSTILE\nFigurativo moderno, seconda metà del XX secolo\n\nLAVORAZIONE\nOpera grafica su carta in tiratura limitata, esemplare 66/70, firmata e datata. Tecnica di stampa da verificare dal vivo.\n\nMATERIALE\nCarta, vetro, passe-partout e cornice in legno dorato\n\nDIMENSIONI","images":["assets/images/A078/A078-01.webp","assets/images/A078/A078-02.webp","assets/images/A078/A078-03.webp","assets/images/A078/A078-04.webp","assets/images/A078/A078-05.webp"],"status":"available","specs_it":[],"description_en":"","description_fr":""},"A079":{"category_key":"paintings","title_it":"Opera figurativa di B. Aloisi","category_it":"Dipinti","dimensions":"H 68 × L 90 cm","description_it":"Suggestiva opera figurativa firmata B. Aloisi, artista milanese, caratterizzata da una composizione intensa ed espressiva. La scena, dominata da tonalità scure di grigio, nero e verde profondo, presenta una figura umana emergente da grandi forme animate, illuminate da accenti di rosso e rosa che conferiscono profondità e tensione alla composizione.\n\nLa pittura si distingue per il tratto deciso, le sovrapposizioni cromatiche e l’atmosfera enigmatica e visionaria. L’opera è valorizzata da un’ampia cornice argentata con passe-partout beige e profilo interno coordinato.\n\nEPOCA\nSeconda metà XX secolo\n\nSTILE\nFigurativo moderno, espressionista\n\nAUTORE\nB. Aloisi, artista milanese\n\nTECNICA\nTecnica pittorica su supporto\n\nMATERIALE\nSupporto pittorico, passe-partout e cornice argentata\n\nDIMENSIONI","images":["assets/images/A079/A079-01.webp","assets/images/A079/A079-02.webp","assets/images/A079/A079-03.webp","assets/images/A079/A079-04.webp","assets/images/A079/A079-05.webp"],"status":"available","specs_it":[],"description_en":"","description_fr":""},"A080":{"category_key":"prints_works_on_paper","title_it":"Acquaforte “La ballerina” di Auguste Brouet","category_it":"Stampe e opere su carta","dimensions":"H 43 × L 34 cm","description_it":"Acquaforte originale dell’artista francese Auguste Brouet (Parigi, 1872–1941), raffigurante una giovane ballerina in abito di scena, colta di profilo accanto a un fondale teatrale.\n\nL’opera è caratterizzata dal segno sottile e incisivo tipico della produzione grafica di Brouet, con particolare attenzione alla figura e all’atmosfera del mondo teatrale parigino.\n\nEsemplare numerato 59/75 e firmato a matita dall’artista in basso a destra. Una nota conservata sul retro identifica l’opera come “La ballerina” e indica una tiratura di 75 esemplari numerati e firmati, oltre a 10 prove d’artista.\n\nL’opera è presentata con passe-partout e cornice dorata.\n\nEPOCA\nPrima metà XX secolo\n\nARTISTA\nAuguste Brouet (Parigi, 1872–1941)\n\nTECNICA\nAcquaforte originale su carta\n\nTIRATURA\n59/75, firmata a matita dall’artista\n\nDIMENSIONI\nCornice H43 × L34 cm","images":["assets/images/A080/A080-01.webp","assets/images/A080/A080-02.webp","assets/images/A080/A080-03.webp","assets/images/A080/A080-04.webp","assets/images/A080/A080-05.webp"],"status":"available","specs_it":[],"description_en":"","description_fr":""},"A081":{"category_key":"prints_works_on_paper","title_it":"Opera grafica firmata Paolo Paradiso","category_it":"Stampe e opere su carta","dimensions":"H 59 × L 43 cm","description_it":"Opera originale di Paolo Paradiso (Milano, 1957), artista italiano attivo tra Milano e gli Stati Uniti, realizzata personalmente dall’artista per la famiglia.\n\nLa composizione, dal carattere ironico e delicato, raffigura due piccoli personaggi sotto una grande ragnatela a forma di cuore. Il disegno essenziale in bianco e nero è ravvivato dall’accento rosso dell’ombrello, unico elemento cromatico della scena.\n\nL’opera è firmata dall’artista e presentata con ampio passe-partout chiaro e cornice decorativa.\n\nEPOCA\nXX secolo\n\nSTILE\nFigurativo contemporaneo\n\nAUTORE\nPaolo Paradiso (Milano, 1957)\n\nMATERIALE\nTecnica grafica su carta\n\nDIMENSIONI","images":["assets/images/A081/A081-01.webp","assets/images/A081/A081-02.webp","assets/images/A081/A081-03.webp"],"status":"available","specs_it":[],"description_en":"","description_fr":""},"A082":{"category_key":"prints_works_on_paper","title_it":"“L’Orazione di Gesù all’Orto” – Incisione religiosa","category_it":"Stampe e opere su carta","dimensions":"H 62 × L 78 cm","description_it":"Incisione religiosa raffigurante l’Orazione di Gesù nell’Orto degli Ulivi. La scena mostra Cristo in preghiera davanti all’angelo, mentre gli apostoli riposano in primo piano, immersi in un paesaggio alberato finemente inciso.\n\nOpera caratterizzata da un ricco tratteggio e da una composizione di gusto classico, conservata nella sua cornice lignea con ampio passe-partout.","images":["assets/images/A082/A082-01.webp","assets/images/A082/A082-02.webp","assets/images/A082/A082-03.webp","assets/images/A082/A082-04.webp","assets/images/A082/A082-05.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XIX secolo"},{"label":"Stile","value":"Religioso / classico"},{"label":"Tecnica","value":"Incisione su carta"},{"label":"Materiale","value":"Carta, vetro e cornice in legno"}],"epoch_it":"XIX secolo","style_it":"Religioso / classico","material_it":"Carta, vetro e cornice in legno","description_en":"","description_fr":""},"A083":{"category_key":"prints_works_on_paper","title_it":"Incisione antica “La conclusion de la Paix”","category_it":"Stampe e opere su carta","dimensions":"H 65 × L 51 cm","description_it":"Antica incisione in bianco e nero raffigurante “La conclusion de la Paix”, complessa scena allegorica dedicata alla conclusione della pace.\n\nLa composizione presenta diverse figure allegoriche inserite in una scenografia monumentale di gusto classico, con colonne, architetture, armature e simboli militari. Nella parte inferiore della stampa sono presenti il titolo originale in francese e una lunga iscrizione descrittiva.\n\nL’opera conserva il fascino della carta antica, con diffuse tracce del tempo, ingiallimenti e fioriture visibili soprattutto lungo i margini. Presentata entro cornice lignea semplice.","images":["assets/images/A083/A083-01.webp","assets/images/A083/A083-02.webp","assets/images/A083/A083-03.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"antica, datazione da approfondire"},{"label":"Stile","value":"allegorico / storico"},{"label":"Tecnica","value":"incisione su carta"},{"label":"Soggetto","value":"“La conclusion de la Paix”"},{"label":"Materiale","value":"carta, vetro e cornice in legno"}],"epoch_it":"antica, datazione da approfondire","style_it":"allegorico / storico","material_it":"carta, vetro e cornice in legno","description_en":"","description_fr":""},"A084":{"category_key":"decorative_objects","title_it":"Coppia di piccoli vasi a cratere","category_it":"Oggetti decorativi","dimensions":"H 16 × L 8 × P 8 cm ciascuno","description_it":"Elegante coppia di piccoli vasi ornamentali realizzati presumibilmente in alabastro dalle calde tonalità avorio e miele, caratterizzato da naturali venature rosate e brune.\n\nI due elementi presentano una forma classica a cratere, con ampio bordo modanato, corpo tornito e panciuto, piede sagomato e base quadrata. La lavorazione valorizza le trasparenze e le variazioni cromatiche naturali della pietra, rendendo ciascun esemplare leggermente diverso dall’altro.\n\nLa coppia conserva una piacevole patina del tempo e presenta diffuse tracce d'uso, piccole sbeccature e irregolarità lungo i bordi e le basi, visibili nelle fotografie e coerenti con l'età e la delicatezza del materiale.","images":["assets/images/A084/A084-01.webp","assets/images/A084/A084-02.webp","assets/images/A084/A084-03.webp","assets/images/A084/A084-04.webp","assets/images/A084/A084-05.webp","assets/images/A084/A084-06.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"presumibilmente prima metà del XX secolo"},{"label":"Stile","value":"classico / neoclassico"},{"label":"Lavorazione","value":"alabastro tornito e sagomato Materiale presumibilmente alabastro"}],"epoch_it":"presumibilmente prima metà del XX secolo","style_it":"classico / neoclassico","description_en":"","description_fr":""},"A085":{"category_key":"decorative_objects","title_it":"Coppia di obelischi decorativi in onice rosa","category_it":"Oggetti decorativi","dimensions":"H 37 × L 11 × P 10 cm ciascuno","description_it":"Elegante coppia di obelischi decorativi realizzati in pietra naturale, verosimilmente onice rosa, caratterizzata da suggestive venature verticali nei toni del rosa, salmone, crema e bianco.\n\nLa forma slanciata e geometrica riprende il classico obelisco, con superfici levigate e lucidate che mettono particolarmente in risalto la naturale traslucenza e la ricca stratificazione cromatica della pietra. Le venature sono differenti nei due esemplari, confermando l'unicità naturale del materiale e creando una coppia coordinata ma non perfettamente identica.\n\nOggetti decorativi di forte presenza, adatti sia ad ambienti classici sia a interni contemporanei, particolarmente scenografici se illuminati dalla luce naturale.","images":["assets/images/A085/A085-01.webp","assets/images/A085/A085-02.webp","assets/images/A085/A085-03.webp","assets/images/A085/A085-04.webp","assets/images/A085/A085-05.webp","assets/images/A085/A085-06.webp","assets/images/A085/A085-07.webp","assets/images/A085/A085-08.webp","assets/images/A085/A085-09.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"seconda metà del XX secolo"},{"label":"Stile","value":"classico / decorativo"},{"label":"Lavorazione","value":"pietra tagliata, sagomata e lucidata"},{"label":"Materiale","value":"onice rosa, attribuzione da confermare"}],"epoch_it":"seconda metà del XX secolo","style_it":"classico / decorativo","material_it":"onice rosa, attribuzione da confermare","description_en":"","description_fr":""},"A086":{"category_key":"decorative_objects","title_it":"Coppia di sfere decorative rivestite in osso su basi in legno","category_it":"Oggetti decorativi","dimensions":"Dimensioni grande: H 18 × L 15 × P 15 cm\nDimensioni piccola: H 14 × L 8 × P 8 cm","description_it":"Coppia di sfere decorative di differenti dimensioni, rivestite da elementi sagomati e lucidati in materiale di origine animale, verosimilmente osso, disposti a fasce concentriche e montate su eleganti basi tornite in legno.\n\nLa superficie presenta le naturali variazioni cromatiche del materiale, nelle tonalità dell'avorio, crema e miele, che conferiscono agli oggetti un piacevole carattere artigianale. Le basi in legno tornito, anch'esse di dimensioni differenti, completano la composizione creando un insieme decorativo particolarmente scenografico.\n\nLa sfera più piccola è removibile dalla propria base. L'esemplare maggiore presenta rotture, distacchi e mancanze nel rivestimento, chiaramente documentati nelle fotografie, mentre il più piccolo appare complessivamente meglio conservato.","images":["assets/images/A086/A086-01.webp","assets/images/A086/A086-02.webp","assets/images/A086/A086-03.webp","assets/images/A086/A086-04.webp","assets/images/A086/A086-05.webp","assets/images/A086/A086-06.webp","assets/images/A086/A086-07.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"seconda metà del XX secolo"},{"label":"Stile","value":"decorativo / etnico-coloniale"},{"label":"Lavorazione","value":"elementi sagomati e assemblati su struttura sferica; basi in legno tornito"},{"label":"Materiale","value":"presumibilmente osso e legno"},{"label":"Dimensioni grande","value":"H 18 × L 15 × P 15 cm"},{"label":"Dimensioni piccola","value":"H 14 × L 8 × P 8 cm"}],"epoch_it":"seconda metà del XX secolo","style_it":"decorativo / etnico-coloniale","material_it":"presumibilmente osso e legno","description_en":"","description_fr":""},"A087":{"category_key":"ceramics","title_it":"Teiera scultorea in ceramica smaltata verde e blu con due piattini in vetro","category_it":"Ceramiche e porcellane","dimensions":"Dimensioni teiera: H 20 × L 27 cm\nDimensioni piattini: 30 × 12 cm","description_it":"Originale teiera scultorea in ceramica smaltata, caratterizzata da un corpo cilindrico verde smeraldo e da un lungo beccuccio e manico ricurvi in blu cobalto.\n\nLa superficie presenta una lavorazione volutamente materica e irregolare, con colature, piccole bolle e variazioni dello smalto che sottolineano il carattere artigianale del pezzo. La forma fortemente stilizzata e il contrasto tra verde e blu conferiscono alla teiera un aspetto moderno e scultoreo, rendendola particolarmente interessante anche come oggetto decorativo.\n\nLa teiera è accompagnata da due piattini/vassoi ovali in vetro spesso, uno blu e uno verde, con incavo ovale centrale.","images":["assets/images/A087/A087-01.webp","assets/images/A087/A087-02.webp","assets/images/A087/A087-03.webp","assets/images/A087/A087-04.webp","assets/images/A087/A087-05.webp","assets/images/A087/A087-06.webp","assets/images/A087/A087-07.webp","assets/images/A087/A087-08.webp","assets/images/A087/A087-09.webp","assets/images/A087/A087-10.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XX secolo"},{"label":"Stile","value":"Moderno / design scultoreo"},{"label":"Lavorazione","value":"Artigianale, ceramica modellata e smaltata"},{"label":"Materiale","value":"Ceramica smaltata; piattini in vetro"},{"label":"Dimensioni teiera","value":"H 20 × L 27 cm"},{"label":"Dimensioni piattini","value":"30 × 12 cm"}],"epoch_it":"XX secolo","style_it":"Moderno / design scultoreo","material_it":"Ceramica smaltata; piattini in vetro","description_en":"","description_fr":""},"A088":{"category_key":"lighting","title_it":"Lampadario in bronzo dorato con pendenti in cristallo","category_it":"Illuminazione","dimensions":"Da misurare","description_it":"Elegante lampadario a sospensione di gusto classico, caratterizzato da una ricca struttura in metallo lavorato con finitura dorata e da numerosi pendenti in cristallo trasparente sfaccettato.\n\nLa composizione presenta bracci sinuosi decorati da motivi vegetali e volute, arricchiti da grandi gocce e pendenti di diverse forme e dimensioni che riflettono la luce creando un raffinato effetto luminoso. Il corpo centrale, particolarmente elaborato, è completato nella parte superiore da elementi ornamentali traforati e ulteriori cristalli.\n\nIl lampadario conserva il sistema di sospensione a catena e il rosone decorativo coordinato. Un elemento d'arredo scenografico, adatto sia ad ambienti classici sia a interni contemporanei dove possa essere utilizzato come pezzo decorativo di forte presenza.","images":["assets/images/A088/A088-01.webp","assets/images/A088/A088-02.webp","assets/images/A088/A088-03.webp","assets/images/A088/A088-04.webp","assets/images/A088/A088-05.webp","assets/images/A088/A088-06.webp","assets/images/A088/A088-Scheda.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XX secolo"},{"label":"Stile","value":"Classico / revival"},{"label":"Lavorazione","value":"Metallo lavorato e cristalli sfaccettati"},{"label":"Materiale","value":"Metallo dorato e cristallo"}],"epoch_it":"XX secolo","style_it":"Classico / revival","material_it":"Metallo dorato e cristallo","description_en":"","description_fr":""},"A089":{"category_key":"furniture","title_it":"Comò a tre cassetti con fronte bombato e intarsi","category_it":"Mobili","dimensions":"H 89 × L 103 × P 55 cm","description_it":"Elegante comò a tre cassetti caratterizzato dal fronte bombato e da una ricca impiallacciatura con giochi geometrici delle venature del legno. Il mobile poggia su quattro piedi torniti e presenta sottili filettature decorative che ne sottolineano il profilo.\n\nI tre ampi cassetti conservano ferramenta decorativa in metallo, con maniglie ad anello su placche ovali ornate e bocchette centrali per le serrature. La lavorazione, le proporzioni e l'impostazione formale richiamano il gusto neoclassico tra la fine del XVIII e l'inizio del XIX secolo.\n\nIl mobile conserva una bella presenza decorativa e una patina coerente con l'età. Sono visibili segni del tempo, usure della superficie, piccole fessurazioni e sollevamenti/mancanze dell'impiallacciatura, in particolare lungo i bordi e nelle zone inferiori; condizioni che suggeriscono un intervento conservativo di restauro.","images":["assets/images/A089/A089-01.webp","assets/images/A089/A089-02.webp","assets/images/A089/A089-03.webp","assets/images/A089/A089-04.webp","assets/images/A089/A089-05.webp","assets/images/A089/A089-06.webp","assets/images/A089/A089-07.webp","assets/images/A089/A089-08.webp","assets/images/A089/A089-09.webp","assets/images/A089/A089-Scheda.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"fine XVIII – inizi XIX secolo"},{"label":"Stile","value":"Neoclassico"},{"label":"Materiale","value":"legno impiallacciato e intarsiato, ferramenta in metallo"}],"epoch_it":"fine XVIII – inizi XIX secolo","style_it":"Neoclassico","material_it":"legno impiallacciato e intarsiato, ferramenta in metallo","description_en":"","description_fr":""},"A090":{"category_key":"musical","title_it":"Basso elettrico SX 4 corde tipo Precision Bass, finitura sunburst","category_it":"Strumenti musicali","dimensions":"H 117 × L 34 × P 4 cm","description_it":"Basso elettrico a 4 corde SX, caratterizzato dalla classica configurazione ispirata al Precision Bass. Il corpo presenta una finitura sunburst a tre tonalità con battipenna bianco, mentre il manico è completato da tastiera scura con segnatasti circolari e paletta in legno naturale con logo SX.\n\nÈ equipaggiato con pickup split-coil, controlli volume e tono, ponte cromato a quattro sellette e meccaniche aperte. Completo di tracolla Fender visibile in fotografia.\n\nEsemplare usato, con normali segni e tracce d’uso visibili sulla finitura e sui componenti. Lo stato di funzionamento dell’elettronica non è verificabile dalle sole fotografie.","images":["assets/images/A090/A090-01.webp","assets/images/A090/A090-02.webp","assets/images/A090/A090-03.webp","assets/images/A090/A090-04.webp","assets/images/A090/A090-05.webp","assets/images/A090/A090-06.webp","assets/images/A090/A090-07.webp","assets/images/A090/A090-08.webp","assets/images/A090/A090-09.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"Contemporaneo"},{"label":"Stile","value":"Precision Bass"},{"label":"Marca","value":"SX"},{"label":"Materiale","value":"Legno, metallo e materiale plastico"},{"label":"Finitura","value":"Sunburst"}],"epoch_it":"Contemporaneo","style_it":"Precision Bass","material_it":"Legno, metallo e materiale plastico","description_en":"","description_fr":""},"A091":{"category_key":"musical","title_it":"Chitarra acustica Washburn D10SB nera","category_it":"Strumenti musicali","dimensions":"H 105 × L 40 × P 11 cm","description_it":"Chitarra acustica a 6 corde Washburn, modello D10SB, dalla classica forma dreadnought e caratterizzata da un'elegante finitura nera lucida.\n\nLa chitarra presenta tastiera scura con segnatasti circolari, rosetta decorativa intorno alla buca, binding chiaro lungo il profilo della cassa e meccaniche cromate. La paletta nera reca il caratteristico logo Washburn dorato.\n\nL'etichetta interna originale identifica il modello D10SB e riporta il numero di serie G05030480 e la produzione Made in China. Esemplare usato, conservato con segni compatibili con l'utilizzo. Lo stato funzionale e la regolazione dello strumento non sono stati verificati.","images":["assets/images/A091/A091-01.webp","assets/images/A091/A091-02.webp","assets/images/A091/A091-03.webp","assets/images/A091/A091-04.webp","assets/images/A091/A091-05.webp","assets/images/A091/A091-06.webp","assets/images/A091/A091-07.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"Contemporanea"},{"label":"Marca","value":"Washburn"},{"label":"Modello","value":"D10SB"},{"label":"Numero di serie","value":"G05030480"},{"label":"Tipologia","value":"Chitarra acustica dreadnought a 6 corde"},{"label":"Materiale","value":"Legno e metallo"},{"label":"Finitura","value":"Nera lucida"}],"epoch_it":"Contemporanea","material_it":"Legno e metallo","description_en":"","description_fr":""},"A092":{"category_key":"prints_works_on_paper","title_it":"Serie di quattro incisioni con ritratti storici inglesi","category_it":"Stampe e opere su carta","dimensions":"H 45 × L 29 cm ciascuna","description_it":"Serie decorativa composta da quattro incisioni raffiguranti illustri personaggi della storia inglese, rappresentati a mezzo busto entro elaborate cornici ovali e accompagnati da elementi allegorici, araldici e simbolici.\n\nLe composizioni, di gusto settecentesco, presentano una raffinata impostazione grafica con ricca lavorazione a tratteggio e un interessante apparato ornamentale. Le stampe mostrano una naturale patina e tonalità brunite dovute al tempo, che ne accentuano il carattere antico.\n\nTutte e quattro sono presentate entro cornici nere modanate coordinate, formando un insieme omogeneo e di notevole effetto decorativo, particolarmente adatto a una biblioteca, uno studio o un ambiente classico.","images":["assets/images/A092/A092-01.webp","assets/images/A092/A092-02.webp","assets/images/A092/A092-03.webp","assets/images/A092/A092-04.webp","assets/images/A092/A092-05.webp","assets/images/A092/A092-06.webp","assets/images/A092/A092-07.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XVIII secolo / da verificare su esame diretto"},{"label":"Stile","value":"Inglese settecentesco"},{"label":"Tecnica","value":"Incisione su carta"},{"label":"Materiale","value":"Carta, vetro e cornice in legno"},{"label":"Quantità","value":"4 incisioni"}],"epoch_it":"XVIII secolo / da verificare su esame diretto","style_it":"Inglese settecentesco","material_it":"Carta, vetro e cornice in legno","description_en":"","description_fr":""},"A093":{"category_key":"vintage_collectibles","title_it":"Lotto di marionette teatrali originali Cinilli con scatole originali","category_it":"Vintage e collezionismo","dimensions":"Dimensioni marionette: circa H 19 × L 6 cm ciascuna\nDimensioni scatole: circa L 22 × P 8 × H 5 cm ciascuna","description_it":"Raro e affascinante lotto di marionette teatrali originali Cinilli, conservate con le rispettive scatole d’epoca in cartone, numerose ancora corredate dall’etichetta originale con il nome del personaggio.\n\nLa collezione comprende diversi personaggi della tradizione teatrale e della Commedia dell’Arte, tra cui Arlecchino, Pantalone, Brighella, Capitano, Rosaura, Principe, Oste e Donna Grassa.\n\nOgni figura è caratterizzata da una propria fisionomia e da un costume specifico, con teste modellate e dipinte, abiti in tessuto e sistema di movimentazione mediante fili e piccoli comandi in legno. Particolarmente suggestiva la varietà dei costumi, dei tessuti e delle espressioni dipinte, che conferisce a ciascun personaggio una forte individualità.\n\nDi particolare importanza collezionistica è la conservazione delle scatole originali Cinilli, alcune con il nome del personaggio applicato frontalmente e altre recanti la caratteristica firma “Cinilli” sul coperchio. La presenza delle confezioni originali permette di conservare l'insieme come collezione storica coerente e ne aumenta l'interesse rispetto ai singoli esemplari sciolti.","images":["assets/images/A093/A093-01.webp","assets/images/A093/A093-02.webp","assets/images/A093/A093-03.webp","assets/images/A093/A093-04.webp","assets/images/A093/A093-05.webp","assets/images/A093/A093-06.webp","assets/images/A093/A093-07.webp","assets/images/A093/A093-08.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"metà XX secolo circa"},{"label":"Produzione","value":"Cinilli, Italia"},{"label":"Stile","value":"Teatro di figura italiano / Commedia dell’Arte"},{"label":"Lavorazione","value":"Artigianale, dipinta e assemblata a mano"},{"label":"Materiale","value":"Tessuto, legno, materiali modellati, fili"},{"label":"Dimensioni marionette","value":"circa H 19 × L 6 cm ciascuna"},{"label":"Dimensioni scatole","value":"circa L 22 × P 8 × H 5 cm ciascuna"}],"epoch_it":"metà XX secolo circa","style_it":"Teatro di figura italiano / Commedia dell’Arte","material_it":"Tessuto, legno, materiali modellati, fili","description_en":"","description_fr":""},"A094":{"category_key":"desk_objects","title_it":"Portacorrispondenza da scrivania in legno con applicazione in metallo argentato","category_it":"Oggetti da scrivania","dimensions":"H 11 × L 26 × P 12 cm","description_it":"Elegante portacorrispondenza da scrivania realizzato in legno, caratterizzato da una struttura sagomata con tre scomparti separati, pensati per organizzare lettere, documenti e carte.\n\nIl fronte è impreziosito da un’applicazione ovale in metallo argentato, decorata lungo il bordo con un raffinato motivo floreale a rilievo. Le linee curve degli scomparti e dello schienale conferiscono all’oggetto un aspetto classico ed elegante, tipico degli accessori da scrittoio della prima metà del Novecento.\n\nOggetto decorativo e funzionale, adatto a uno studio, una biblioteca o una scrivania classica.","images":["assets/images/A094/A094-01.webp","assets/images/A094/A094-02.webp","assets/images/A094/A094-03.webp","assets/images/A094/A094-04.webp","assets/images/A094/A094-05.webp","assets/images/A094/A094-06.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"prima metà del XX secolo"},{"label":"Stile","value":"classico"},{"label":"Materiale","value":"legno e metallo argentato"}],"epoch_it":"prima metà del XX secolo","style_it":"classico","material_it":"legno e metallo argentato","description_en":"","description_fr":""},"A095":{"category_key":"sculptures","title_it":"Coppia di sculture figurative con scene di vita Inuit","category_it":"Sculture","dimensions":"Da misurare","description_it":"Coppia di sculture decorative raffiguranti personaggi Inuit in scene di vita quotidiana, caratterizzate da una lavorazione ricca di dettagli e da una superficie scura con naturali tracce del tempo.\n\nLa prima composizione raffigura una figura con ampio abbigliamento tradizionale accanto a un grande pesce, elemento legato alla pesca e alla vita delle popolazioni artiche. La seconda presenta una figura seduta con un bambino, resa con particolare attenzione alle pieghe degli abiti, ai volti e ai dettagli delle figure.\n\nLe due sculture presentano soggetti differenti ma stilisticamente coerenti e risultano particolarmente decorative se esposte insieme.","images":["assets/images/A095/A095-01.webp","assets/images/A095/A095-02.webp","assets/images/A095/A095-03.webp","assets/images/A095/A095-04.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XX secolo"},{"label":"Stile","value":"Arte figurativa di ispirazione Inuit / artica"},{"label":"Materiale","value":"probabile pietra ollare (steatite) scolpita"},{"label":"Lavorazione","value":"scultura a rilievo e incisione"}],"epoch_it":"XX secolo","style_it":"Arte figurativa di ispirazione Inuit / artica","material_it":"probabile pietra ollare (steatite) scolpita","description_en":"","description_fr":""},"A096":{"category_key":"vintage_collectibles","title_it":"Orsetto meccanico vintage su sedia a dondolo con libro “Nursery Tales”","category_it":"Vintage e collezionismo","dimensions":"H 23 × L 18 × P 11 cm","description_it":"Giocattolo meccanico vintage raffigurante un orsetto seduto su una piccola sedia a dondolo, intento a leggere un libro illustrato “Nursery Tales”. La figura è realizzata in peluche con dettagli in materiale plastico e occhiali applicati; la sedia e la base sono in latta litografata, riccamente decorate con motivi policromi tipici dei giocattoli del secondo dopoguerra.\n\nSul basamento è presente l’interruttore ON/OFF, elemento che indica un funzionamento elettrico/meccanico. Il soggetto appartiene alla produzione di giocattoli animati da collezione diffusa soprattutto tra anni ’50 e ’60. Esemplari giapponesi analoghi di orsetti meccanici su sedia a dondolo sono oggi ricercati nel mercato del giocattolo vintage.\n\nPresenta normali segni del tempo e dell’utilizzo, visibili soprattutto sulla base litografata e sul piccolo libro. Da verificare il corretto funzionamento del meccanismo.","images":["assets/images/A096/A096-01.webp","assets/images/A096/A096-02.webp","assets/images/A096/A096-03.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"circa anni 1950–1960"},{"label":"Tipologia","value":"giocattolo meccanico/elettrico da collezione"},{"label":"Materiale","value":"latta litografata, peluche, plastica e tessuto"}],"epoch_it":"circa anni 1950–1960","material_it":"latta litografata, peluche, plastica e tessuto","description_en":"","description_fr":""},"A097":{"category_key":"desk_objects","title_it":"Tampone asciugainchiostro da scrivania vintage in legno","category_it":"Oggetti da scrivania","dimensions":"H 9 × L 16 × P 7 cm","description_it":"Elegante tampone asciugainchiostro da scrivania, accessorio tradizionalmente utilizzato per assorbire l’inchiostro in eccesso dopo la scrittura con penna stilografica o pennino.\n\nL’esemplare presenta una struttura superiore rettangolare in legno con finitura bruno-rossastra e impugnatura centrale tornita in legno ebanizzato nero. La parte inferiore, dalla caratteristica forma curva basculante, conserva il rivestimento assorbente con fascia tessile chiara lungo il bordo.\n\nUn piccolo oggetto da scrittoio dal fascino d’epoca, interessante sia come complemento decorativo sia per una collezione di accessori da scrittura.","images":["assets/images/A097/A097-01.webp","assets/images/A097/A097-02.webp","assets/images/A097/A097-03.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"prima metà del XX secolo"},{"label":"Stile","value":"classico / accessorio da scrittoio"},{"label":"Materiale","value":"legno, legno ebanizzato e materiale tessile assorbente"}],"epoch_it":"prima metà del XX secolo","style_it":"classico / accessorio da scrittoio","material_it":"legno, legno ebanizzato e materiale tessile assorbente","description_en":"","description_fr":""},"A098":{"category_key":"ceramics","title_it":"Gruppo di tre figure orientali in porcellana policroma","category_it":"Ceramiche e porcellane","dimensions":"figura grande H 22 × L 16 cm; figure piccole H 13 × L 9 cm ciascuna","description_it":"Gruppo decorativo composto da tre figure maschili orientali sedute, realizzate in porcellana policroma. La composizione comprende una figura centrale di dimensioni maggiori e due figure laterali più piccole coordinate.\n\nI personaggi indossano ricche vesti decorate con motivi floreali policromi nei toni del rosa, giallo, blu e verde, con dettagli dorati. Le tre figure poggiano su basi sagomate decorate e costituiscono un insieme particolarmente scenografico.\n\nSulla base di alcuni esemplari sono presenti marchi impressi, documentati fotograficamente.","images":["assets/images/A098/A098-01.webp","assets/images/A098/A098-02.webp","assets/images/A098/A098-03.webp","assets/images/A098/A098-04.webp","assets/images/A098/A098-05.webp","assets/images/A098/A098-06.webp","assets/images/A098/A098-07.webp","assets/images/A098/A098-08.webp","assets/images/A098/A098-09.webp","assets/images/A098/A098-10.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XX secolo"},{"label":"Stile","value":"gusto orientale / cineserie"},{"label":"Lavorazione","value":"porcellana modellata e decorata in policromia"},{"label":"Materiale","value":"porcellana"},{"label":"Composizione","value":"3 pezzi"}],"epoch_it":"XX secolo","style_it":"gusto orientale / cineserie","material_it":"porcellana","description_en":"","description_fr":""},"A099":{"category_key":"ceramics","title_it":"Coppia di grandi Budai con bambini in porcellana policroma","category_it":"Ceramiche e porcellane","dimensions":"H 26 × L 25 cm circa ciascuno","description_it":"Coppia di grandi figure orientali raffiguranti Budai, tradizionalmente associato a prosperità, abbondanza e felicità, rappresentato sorridente e circondato da numerosi bambini.\n\nLe due sculture, concepite come pendant decorativo, presentano ricche decorazioni policrome differenti ma coordinate, con vesti e basi ornate da motivi floreali e geometrici nei toni del rosa, giallo, azzurro, verde e rosso. Particolarmente vivace la modellazione dei numerosi bambini disposti intorno alle figure principali.\n\nInsieme di notevole presenza decorativa, valorizzato dalle dimensioni importanti e dalla ricchezza della composizione.","images":["assets/images/A099/A099-01.webp","assets/images/A099/A099-02.webp","assets/images/A099/A099-03.webp","assets/images/A099/A099-04.webp","assets/images/A099/A099-05.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XX secolo"},{"label":"Stile","value":"gusto orientale / cineserie"},{"label":"Lavorazione","value":"porcellana modellata e decorata in policromia"},{"label":"Materiale","value":"porcellana"},{"label":"Composizione","value":"2 pezzi"}],"epoch_it":"XX secolo","style_it":"gusto orientale / cineserie","material_it":"porcellana","description_en":"","description_fr":""},"A100":{"category_key":"ceramics","title_it":"Coppia di Buddha sorridenti in porcellana policroma cinese","category_it":"Ceramiche e porcellane","dimensions":"H 19 × L 17 cm.circa\nH 11 × L 10 cm.circa","description_it":"Coppia di figure decorative raffiguranti il Buddha sorridente, realizzate in porcellana smaltata e dipinta in vivace policromia.\n\nLe due figure, di dimensioni pressoché equivalenti, sono rappresentate sedute, con ventre scoperto e ampie vesti decorate nei toni del giallo, rosa, verde, blu e rosso. La ricca decorazione degli abiti, i dettagli del volto dipinti a mano e le differenti pose conferiscono a ciascuna figura un carattere individuale pur mantenendo una forte coerenza d'insieme.\n\nSul fondo è presente un marchio impresso con caratteri cinesi. Dalle fotografie il marchio è visibile.\n\nInteressante coppia decorativa, particolarmente adatta a essere conservata e esposta insieme.","images":["assets/images/A100/A100-01.webp","assets/images/A100/A100-02.webp","assets/images/A100/A100-03.webp","assets/images/A100/A100-04.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XX secolo"},{"label":"Stile","value":"Cinese, gusto orientale"},{"label":"Lavorazione","value":"Porcellana modellata, smaltata e dipinta in policromia"},{"label":"Materiale","value":"Porcellana"},{"label":"Marchio","value":"marchio impresso con caratteri cinesi sul fondo"}],"epoch_it":"XX secolo","style_it":"Cinese, gusto orientale","material_it":"Porcellana","description_en":"","description_fr":""},"A101":{"category_key":"ceramics","title_it":"Coppia di Buddha sorridenti in porcellana policroma","category_it":"Ceramiche e porcellane","dimensions":"H 16 × L 14 cm circa ciascuno","description_it":"Coppia di figure orientali raffiguranti Buddha sorridente, realizzate in porcellana smaltata e riccamente decorate in policromia.\n\nLe due figure presentano il caratteristico ventre scoperto e un’espressione sorridente, con vesti ornate da vivaci motivi floreali e geometrici. La decorazione, differente ma coordinata nei due esemplari, combina tonalità turchesi, verdi, gialle, rosa e rosse con dettagli finemente delineati.\n\nInteressante coppia decorativa, particolarmente gradevole esposta insieme e rappresentativa della produzione cinese destinata all’arredo e al collezionismo occidentale.","images":["assets/images/A101/A101-01.webp","assets/images/A101/A101-02.webp","assets/images/A101/A101-03.webp","assets/images/A101/A101-04.webp","assets/images/A101/A101-05.webp","assets/images/A101/A101-07.webp","assets/images/A101/A101-08.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XX secolo"},{"label":"Stile","value":"Cinese tradizionale"},{"label":"Lavorazione","value":"Porcellana modellata, smaltata e dipinta in policromia"},{"label":"Materiale","value":"Porcellana"}],"epoch_it":"XX secolo","style_it":"Cinese tradizionale","material_it":"Porcellana","description_en":"","description_fr":""},"A102":{"category_key":"ceramics","title_it":"Buddha seduto in ceramica smaltata rosa","category_it":"Ceramiche e porcellane","dimensions":"H 20 × L 10 cm circa","description_it":"Figura orientale raffigurante un Buddha seduto, modellato in ceramica e rivestito da una caratteristica invetriatura monocroma rosa intenso. La figura presenta un volto sorridente, ventre prominente e veste morbidamente drappeggiata, con una mano appoggiata sul ventre e l’altra sul ginocchio.\n\nLa superficie mostra una diffusa craquelure della vetrina e naturali segni del tempo, che contribuiscono al carattere decorativo dell’oggetto.","images":["assets/images/A102/A102-01.webp","assets/images/A102/A102-02.webp","assets/images/A102/A102-03.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XX secolo"},{"label":"Stile","value":"Orientale / cinese"},{"label":"Lavorazione","value":"Ceramica modellata e smaltata"},{"label":"Materiale","value":"Ceramica invetriata"}],"epoch_it":"XX secolo","style_it":"Orientale / cinese","material_it":"Ceramica invetriata","description_en":"","description_fr":""},"A103":{"category_key":"ceramics","title_it":"Coppia di figure orientali in porcellana policroma","category_it":"Ceramiche e porcellane","dimensions":"figura più grande: H 24 × L 10 cm circa\nfigura più piccola: H 19 × L 11 cm circa","description_it":"Coppia di figure decorative orientali in porcellana smaltata e dipinta in vivaci colori policromi. Le due figure, differenti per forma e altezza ma accomunate dallo stesso gusto decorativo, indossano abiti riccamente ornati con motivi floreali nei toni del rosa, giallo, verde, azzurro e lilla.\n\nLa figura più alta è raffigurata in piedi con oggetti tra le mani, mentre la seconda, più bassa e dalla sagoma più ampia, è rappresentata seduta e presenta una decorazione particolarmente ricca a motivi floreali. Entrambe presentano un'apertura sulla sommità del capo, elemento probabilmente legato alla loro originaria funzione decorativa.\n\nInsieme molto piacevole e scenografico, particolarmente adatto a essere presentato come coppia per l'affinità cromatica e stilistica.","images":["assets/images/A103/A103-01.webp","assets/images/A103/A103-02.webp","assets/images/A103/A103-03.webp","assets/images/A103/A103-04.webp","assets/images/A103/A103-05.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XX secolo"},{"label":"Stile","value":"orientale / cinese"},{"label":"Lavorazione","value":"porcellana modellata, smaltata e dipinta in policromia"},{"label":"Materiale","value":"porcellana"}],"epoch_it":"XX secolo","style_it":"orientale / cinese","material_it":"porcellana","description_en":"","description_fr":""},"A104":{"category_key":"decorative_objects","title_it":"Ciotola decorativa in onice con montatura in metallo e cabochon viola","category_it":"Oggetti decorativi","dimensions":"H 6 × Ø 30 cm circa.","description_it":"Elegante ciotola centrotavola di forma circolare realizzata in pietra naturale fortemente venata, verosimilmente onice, caratterizzata da suggestive sfumature nei toni del crema, miele, beige e bruno.\n\nL'ampio bordo è impreziosito da una montatura in metallo scuro lavorato, scandita da inserti in pietra e motivi ornamentali traforati e incisi. Piccoli cabochon di colore viola, dall'aspetto simile all'ametista, sono distribuiti lungo la circonferenza e creano un raffinato contrasto cromatico con le tonalità calde della pietra.\n\nLa naturale varietà delle venature rende il pezzo particolarmente decorativo e scenografico, adatto come centrotavola, svuotatasche o elemento da collezione.","images":["assets/images/A104/A104-01.webp","assets/images/A104/A104-02.webp","assets/images/A104/A104-03.webp","assets/images/A104/A104-04.webp","assets/images/A104/A104-05.webp","assets/images/A104/A104-06.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XX secolo"},{"label":"Stile","value":"decorativo / eclettico"},{"label":"Lavorazione","value":"pietra sagomata e lucidata con montatura metallica applicata"},{"label":"Materiale","value":"pietra naturale, verosimilmente onice; metallo; cabochon viola"}],"epoch_it":"XX secolo","style_it":"decorativo / eclettico","material_it":"pietra naturale, verosimilmente onice; metallo; cabochon viola","description_en":"","description_fr":""},"A105":{"category_key":"decorative_objects","title_it":"Riproduzione di vaso rituale cinese Houmuwu Ding","category_it":"Oggetti decorativi","dimensions":"H 15 × L 10 cm.","description_it":"Riproduzione decorativa cinese ispirata al celebre Houmuwu Ding, grande vaso rituale tripode della tradizione dell’antica Cina. Il recipiente presenta corpo bombato sostenuto da tre piedi, due alte anse verticali e una ricca decorazione a rilievo.\n\nLa superficie è ornata da motivi di gusto arcaizzante, architetture orientali, figure e mascheroni zoomorfi, con finitura nei toni del bronzo brunito e dettagli dorati. Completo di base espositiva con targhetta recante caratteri cinesi “后母戊鼎”.","images":["assets/images/A105/A105-01.webp","assets/images/A105/A105-02.webp","assets/images/A105/A105-03.webp","assets/images/A105/A105-04.webp","assets/images/A105/A105-05.webp","assets/images/A105/A105-06.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XX secolo"},{"label":"Stile","value":"Cinese, ispirazione arcaica Shang"},{"label":"Lavorazione","value":"Fusione con decorazioni a rilievo"},{"label":"Materiale","value":"Metallo patinato, base espositiva"}],"epoch_it":"XX secolo","style_it":"Cinese, ispirazione arcaica Shang","material_it":"Metallo patinato, base espositiva","description_en":"","description_fr":""},"A106":{"category_key":"ceramics","title_it":"Coppia di vasi cinesi con coperchio decorati con draghi","category_it":"Ceramiche e porcellane","dimensions":"ciascuna potiche circa H 17 × Ø 15 cm","description_it":"Coppia di vasi orientali in porcellana invetriata, caratterizzati da una tonalità verde celadon e decorazione in blu sotto vetrina. Il corpo globulare è ornato da grandi draghi sinuosi tra motivi floreali e vegetali stilizzati, secondo il repertorio decorativo tradizionale cinese.\n\nI coperchi presentano bordo sagomato e presa ad anello, con fasce ornamentali geometriche che si ripetono sul collo e alla base. La lavorazione mostra irregolarità e variazioni nella decorazione e nella superficie, caratteristiche di una produzione artigianale.\n\nLa coppia è particolarmente decorativa e interessante per l'abbinamento dei due esemplari. Dalle sole fotografie non è possibile stabilire con sicurezza l'epoca di produzione; eviterei quindi di attribuirli a una dinastia o a un periodo antico preciso senza esame diretto.","images":["assets/images/A106/A106-01.webp","assets/images/A106/A106-02.webp","assets/images/A106/A106-03.webp","assets/images/A106/A106-04.webp","assets/images/A106/A106-05.webp","assets/images/A106/A106-06.webp","assets/images/A106/A106-07.webp","assets/images/A106/A106-08.webp","assets/images/A106/A106-09.webp","assets/images/A106/A106-10.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XX secolo, attribuzione prudenziale"},{"label":"Stile","value":"Cinese tradizionale"},{"label":"Lavorazione","value":"Decorazione in blu sotto vetrina"},{"label":"Materiale","value":"Porcellana invetriata"}],"epoch_it":"XX secolo, attribuzione prudenziale","style_it":"Cinese tradizionale","material_it":"Porcellana invetriata","description_en":"","description_fr":""},"A107":{"category_key":"ceramics","title_it":"Vaso cinese con coperchio in porcellana bianco-blu con simbolo della Doppia Felicità","category_it":"Ceramiche e porcellane","dimensions":"H 24 × L 15 cm circa","description_it":"Vaso cinese di forma globulare con coperchio, realizzato in porcellana decorata nei toni del blu su fondo bianco. La superficie è fittamente ornata da motivi floreali e vegetali stilizzati, organizzati attorno al grande carattere cinese 囍 (Shuangxi), simbolo della “Doppia Felicità”, tradizionalmente associato al matrimonio, all’unione e agli auguri di prosperità.\n\nIl collo e il bordo sono impreziositi da una fascia geometrica, mentre il coperchio riprende il carattere della Doppia Felicità, creando una composizione decorativa particolarmente ricca e armoniosa.\n\nL'esemplare presenta segni del tempo e una evidente filatura verticale visibile sul corpo, oltre a piccole irregolarità e tracce d'uso. Dalle fotografie del fondo non risultano visibili marchi o sigilli identificativi.","images":["assets/images/A107/A107-01.webp","assets/images/A107/A107-02.webp","assets/images/A107/A107-03.webp","assets/images/A107/A107-04.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"probabilmente XX secolo"},{"label":"Stile","value":"Cinese tradizionale, decorazione “Double Happiness”"},{"label":"Lavorazione","value":"Decorazione blu sotto/invetriatura"},{"label":"Materiale","value":"Porcellana / ceramica invetriata"}],"epoch_it":"probabilmente XX secolo","style_it":"Cinese tradizionale, decorazione “Double Happiness”","material_it":"Porcellana / ceramica invetriata","description_en":"","description_fr":""},"A108":{"category_key":"furniture","title_it":"Coppia di comodini impiallacciati con piano sagomato","category_it":"Mobili","dimensions":"H 79 × L 53 × P 36 cm ciascuno","description_it":"Elegante coppia di comodini d’epoca caratterizzati da una linea leggermente bombata e da una ricca impiallacciatura lignea, con belle venature naturali che decorano il fronte e i fianchi.\n\nOgni comodino presenta un cassetto superiore con maniglia decorativa in metallo dorato e un vano inferiore chiuso da anta. Il piano sagomato riprende il profilo mosso del mobile, mentre le gambe alte e rastremate alleggeriscono l’insieme. Piccoli elementi ornamentali intagliati completano la struttura.\n\nLa coppia conserva un piacevole carattere autentico e mostra evidenti segni del tempo e dell’uso, con sollevamenti e mancanze dell’impiallacciatura, in particolare sui piani e lungo alcuni bordi. Necessita di interventi di restauro conservativo.","images":["assets/images/A108/A108-01.webp","assets/images/A108/A108-02.webp","assets/images/A108/A108-03.webp","assets/images/A108/A108-04.webp","assets/images/A108/A108-05.webp","assets/images/A108/A108-06.webp","assets/images/A108/A108-07.webp","assets/images/A108/A108-08.webp","assets/images/A108/A108-09.webp","assets/images/A108/A108-10.webp","assets/images/A108/A108-11.webp","assets/images/A108/A108-12.webp","assets/images/A108/A108-13.webp","assets/images/A108/A108-14.webp","assets/images/A108/A108-15.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XIX secolo"},{"label":"Stile","value":"Luigi XVI / gusto neoclassico"},{"label":"Materiale","value":"Legno impiallacciato, metallo dorato"}],"epoch_it":"XIX secolo","style_it":"Luigi XVI / gusto neoclassico","material_it":"Legno impiallacciato, metallo dorato","description_en":"","description_fr":""},"A109":{"category_key":"mirrors","title_it":"Specchio decorativo in legno ebanizzato e dorato con medaglioni","category_it":"Specchi","dimensions":"H 114 × L 82 cm","description_it":"Specchio rettangolare di gusto neoclassico, caratterizzato da un’importante cornice in legno con finitura ebanizzata nera e profili dorati.\n\nLa cornice è impreziosita sui quattro lati da grandi medaglioni circolari applicati e dorati, decorati con motivi geometrici stilizzati. La superficie scura presenta una lavorazione volutamente materica e irregolare, che crea un elegante contrasto con le parti dorate e conferisce allo specchio un forte carattere decorativo.\n\nIl bordo interno dorato incornicia lo specchio con linea semplice e regolare. Un complemento d’arredo scenografico, adatto sia ad ambienti classici sia a interni contemporanei.","images":["assets/images/A109/A109-01.webp","assets/images/A109/A109-02.webp","assets/images/A109/A109-03.webp","assets/images/A109/A109-04.webp","assets/images/A109/A109-05.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"seconda metà del XX secolo, da confermare"},{"label":"Stile","value":"neoclassico / decorativo"},{"label":"Lavorazione","value":"cornice lavorata e decorata con elementi applicati e doratura"},{"label":"Materiale","value":"legno, finitura ebanizzata e dorata, specchio"}],"epoch_it":"seconda metà del XX secolo, da confermare","style_it":"neoclassico / decorativo","material_it":"legno, finitura ebanizzata e dorata, specchio","description_en":"","description_fr":""},"A110":{"category_key":"lighting","title_it":"Applique a due luci in bronzo dorato con motivi fogliati","category_it":"Illuminazione","dimensions":"Da misurare","description_it":"Elegante applique da parete a due luci, caratterizzata da una struttura riccamente modellata con andamento sinuoso e decorazione vegetale a foglie d’acanto.\n\nI due bracci curvilinei si sviluppano simmetricamente dal corpo centrale e terminano in piattelli sagomati e portacandele. La lavorazione a rilievo e la finitura dorata, con naturale patina e tonalità più scure nelle parti incavate, valorizzano il movimento della decorazione.\n\nCompleta l’applique la coppia di piccoli paralumi sagomati in tessuto color bordeaux, rifiniti da passamaneria scura.\n\nUn elemento d’illuminazione decorativo e scenografico, di gusto classico, particolarmente adatto ad ambienti eleganti e tradizionali.","images":["assets/images/A110/A110-01.webp","assets/images/A110/A110-02.webp","assets/images/A110/A110-03.webp","assets/images/A110/A110-04.webp","assets/images/A110/A110-05.webp","assets/images/A110/A110-06.webp","assets/images/A110/A110-07.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XX secolo"},{"label":"Stile","value":"Luigi XV / rococò"},{"label":"Lavorazione","value":"fusione e lavorazione a rilievo"},{"label":"Materiale","value":"metallo dorato, tessuto"}],"epoch_it":"XX secolo","style_it":"Luigi XV / rococò","material_it":"metallo dorato, tessuto","description_en":"","description_fr":""},"A111":{"category_key":"paintings","title_it":"Nudo femminile seduto, Paolo Paradiso","category_it":"Dipinti","dimensions":"Dimensioni complessive: H 45 × L 35 cm\nDimensioni opera: H 16 × L 11 cm","description_it":"Piccolo studio di figura femminile nuda, raffigurata seduta di profilo con il capo reclinato e lo sguardo rivolto verso il basso.\n\nLa composizione, intima e raccolta, è costruita attraverso tonalità calde e morbide, con il corpo illuminato che emerge da un fondo scuro. La figura è resa con una pittura sfumata e materica, incentrata sul rapporto tra luce, volume e incarnato.\n\nL’opera è firmata in basso a sinistra “Paolo Paradiso” ed è presentata entro un’ampia passe-partout chiara e cornice in legno marezzato.\n\nPaolo Paradiso è un pittore milanese, attivo anche negli Stati Uniti e successivamente rappresentato dalla Galleria Ponte Rosso di Milano; la sua produzione più conosciuta è legata a soggetti figurativi e alle atmosfere dell’America degli anni Cinquanta e Sessanta.","images":["assets/images/A111/A111-01.webp","assets/images/A111/A111-02.webp","assets/images/A111/A111-03.webp","assets/images/A111/A111-04.webp","assets/images/A111/A111-05.webp","assets/images/A111/A111-06.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"seconda metà del XX secolo / contemporaneo"},{"label":"Stile","value":"figurativo"},{"label":"Soggetto","value":"nudo femminile"},{"label":"Artista","value":"Paolo Paradiso"},{"label":"Materiale/Tecnica","value":"da confermare"},{"label":"Dimensioni complessive","value":"H 45 × L 35 cm"},{"label":"Dimensioni opera","value":"H 16 × L 11 cm"}],"epoch_it":"seconda metà del XX secolo / contemporaneo","style_it":"figurativo","material_it":"da confermare","description_en":"","description_fr":""},"A112":{"category_key":"decorative_panels","title_it":"Pannello decorativo con albero di agrumi e vaso classico","category_it":"Pannelli decorativi","dimensions":"H 163 × L 103 cm","description_it":"Grande pannello decorativo raffigurante un rigoglioso albero di agrumi che si sviluppa simmetricamente da un monumentale vaso di gusto classico, ornato da volute e da un volto centrale.\n\nLa composizione, nei toni dell’ocra e dell’oro su fondo scuro, presenta una ricca trama di rami, foglie e frutti. La superficie è caratterizzata da una diffusa craquelure e da una patina decorativa che conferiscono all’opera un marcato effetto anticato.\n\nLe importanti dimensioni e la composizione scenografica ne fanno un elemento decorativo di forte presenza, adatto anche come pannello centrale in un grande ambiente.","images":["assets/images/A112/A112-01.webp","assets/images/A112/A112-02.webp","assets/images/A112/A112-03.webp","assets/images/A112/A112-04.webp","assets/images/A112/A112-05.webp","assets/images/A112/A112-06.webp","assets/images/A112/A112-07.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XX secolo"},{"label":"Stile","value":"Neoclassico / decorativo"},{"label":"Lavorazione","value":"Pittura decorativa con finitura anticata e craquelure"},{"label":"Materiale","value":"Supporto ligneo o pannello dipinto"}],"epoch_it":"XX secolo","style_it":"Neoclassico / decorativo","material_it":"Supporto ligneo o pannello dipinto","description_en":"","description_fr":""},"A113":{"category_key":"desk_objects","title_it":"Scrittoio da tavolo richiudibile in legno con scomparti interni","category_it":"Oggetti da scrivania","dimensions":"Dimensioni chiuso: H 25 × L 31 × P 10 cm\nDimensioni aperto: H 31 × L 57 × P 34 cm","description_it":"Elegante scrittoio da tavolo richiudibile in legno, caratterizzato da una struttura compatta che, una volta aperta, rivela un articolato interno organizzato in numerosi vani e scomparti.\n\nIl corpo centrale presenta diversi divisori destinati alla sistemazione di documenti e accessori da scrittura, affiancati da due elementi laterali apribili, anch’essi provvisti di tasche e scomparti. Il pannello frontale ribaltabile forma un pratico piano di scrittura.\n\nParticolarmente raffinati gli inserti neri presenti sul piano e all'interno del coperchio superiore, impreziositi da una sottile decorazione dorata a motivo vegetale. Cerniere, chiusure e altri elementi metallici completano la struttura.\n\nIl legno, dalle calde tonalità bruno-rossastre, conserva una piacevole patina e naturali tracce del tempo che contribuiscono al carattere dell'oggetto.","images":["assets/images/A113/A113-01.webp","assets/images/A113/A113-02.webp","assets/images/A113/A113-03.webp","assets/images/A113/A113-04.webp","assets/images/A113/A113-05.webp","assets/images/A113/A113-06.webp","assets/images/A113/A113-07.webp","assets/images/A113/A113-08.webp","assets/images/A113/A113-09.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XIX secolo / inizi XX secolo, da confermare"},{"label":"Stile","value":"classico"},{"label":"Lavorazione","value":"ebanisteria con struttura richiudibile e interno suddiviso in scomparti"},{"label":"Materiale","value":"legno, metallo, inserti neri con decorazione dorata"},{"label":"Dimensioni chiuso","value":"H 25 × L 31 × P 10 cm"},{"label":"Dimensioni aperto","value":"H 31 × L 57 × P 34 cm"}],"epoch_it":"XIX secolo / inizi XX secolo, da confermare","style_it":"classico","material_it":"legno, metallo, inserti neri con decorazione dorata","description_en":"","description_fr":""},"A114":{"category_key":"prints_works_on_paper","title_it":"Gruppo di sei stampe con busti dell’antichità classica","category_it":"Stampe e opere su carta","dimensions":"Piccoli: H 50 × L 40 cm\nMedi: H 58 × L 48 cm\nGrande: H 58 × L 70 cm","description_it":"Gruppo coordinato di sei stampe raffiguranti busti e figure dell’antichità classica, presentate entro cornici in legno e passe-partout chiari decorati da sottili filettature geometriche.\n\nLe diverse tavole riproducono sculture e ritratti di personaggi del mondo greco e romano, accompagnati da iscrizioni e indicazioni tipografiche. Le stampe presentano tonalità differenti, dal nero al seppia, e conservano le naturali variazioni cromatiche e tracce del tempo della carta.\n\nL’insieme è particolarmente decorativo grazie all’uniformità delle cornici e alla varietà dei soggetti. Le differenti dimensioni permettono inoltre di creare una composizione a parete articolata e scenografica.","images":["assets/images/A114/A114-01.webp","assets/images/A114/A114-02.webp","assets/images/A114/A114-03.webp","assets/images/A114/A114-04.webp","assets/images/A114/A114-05.webp","assets/images/A114/A114-06.webp","assets/images/A114/A114-07.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"stampe antiche, epoca esatta da determinare"},{"label":"Stile","value":"classico / archeologico"},{"label":"Soggetto","value":"busti e figure dell’antichità classica"},{"label":"Tecnica","value":"stampa su carta"},{"label":"Materiale","value":"carta, vetro, legno Dimensioni:"},{"label":"Piccoli","value":"H 50 × L 40 cm"},{"label":"Medi","value":"H 58 × L 48 cm"},{"label":"Grande","value":"H 58 × L 70 cm"},{"label":"Numero di elementi","value":"6"}],"epoch_it":"stampe antiche, epoca esatta da determinare","style_it":"classico / archeologico","material_it":"carta, vetro, legno Dimensioni:","description_en":"","description_fr":""},"A115":{"category_key":"paintings","title_it":"Ritratto di gatto su fondo nero, firmato","category_it":"Dipinti","dimensions":"H 88 × L 65 cm","description_it":"Originale composizione raffigurante un grande volto di gatto, costruito attraverso un fitto tratto grafico nei toni del blu-verde su fondo nero. Gli intensi occhi rosa creano un forte contrasto cromatico e costituiscono il punto focale dell’opera.\n\nIl soggetto, fortemente stilizzato e di grande impatto decorativo, è caratterizzato da un segno libero e materico. Firma dell’artista ben visibile in basso a destra.\n\nL’opera è presentata con passe-partout chiaro e cornice argentata.","images":["assets/images/A115/A115-01.webp","assets/images/A115/A115-02.webp","assets/images/A115/A115-03.webp","assets/images/A115/A115-04.webp","assets/images/A115/A115-05.webp","assets/images/A115/A115-06.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"seconda metà del XX secolo"},{"label":"Stile","value":"moderno / figurativo"},{"label":"Tecnica","value":"tecnica grafica su carta, da verificare"},{"label":"Soggetto","value":"gatto"},{"label":"Firma","value":"presente in basso a destra"},{"label":"Materiale","value":"carta, vetro e cornice"}],"epoch_it":"seconda metà del XX secolo","style_it":"moderno / figurativo","material_it":"carta, vetro e cornice","description_en":"","description_fr":""},"A116":{"category_key":"prints_works_on_paper","title_it":"Incisione religiosa con Compianto sul Cristo morto","category_it":"Stampe e opere su carta","dimensions":"H 54 × L 41 cm","description_it":"Antica incisione in bianco e nero raffigurante il Compianto sul Cristo morto, con il corpo di Cristo sorretto e circondato da figure in atteggiamento di dolore e raccoglimento.\n\nLa composizione è ricca di personaggi e dettagli, con un fitto tratteggio che definisce volti, panneggi e architetture. Sullo sfondo sono visibili il paesaggio e le croci del Calvario, che collocano la scena immediatamente dopo la Crocifissione.\n\nL’opera è presentata entro cornice lignea scura. La carta e il passe-partout mostrano diffuse fioriture, ossidazioni e ingiallimenti, coerenti con l’età dell’opera e ben visibili nelle fotografie.\n\nEPOCA\n\nXIX secolo\n\nSTILE\n\nReligioso / classico\n\nTECNICA\n\nIncisione su carta\n\nMATERIALE\n\nCarta, vetro e cornice in legno\n\nDIMENSIONI","images":["assets/images/A116/A116-01.webp","assets/images/A116/A116-02.webp","assets/images/A116/A116-03.webp"],"status":"available","specs_it":[],"description_en":"","description_fr":""},"A117":{"category_key":"paintings","title_it":"Dipinto raffigurante scorcio architettonico con corte","category_it":"Dipinti","dimensions":"H 92 × L 70 cm","description_it":"Dipinto a olio raffigurante un suggestivo scorcio di architettura antica, con edifici in pietra, archi e una corte interna parzialmente avvolta dalla vegetazione.\n\nLa composizione è caratterizzata da una tavolozza calda e terrosa, con verdi profondi e una pittura materica particolarmente evidente nella vegetazione e nelle superfici murarie. La prospettiva conduce lo sguardo attraverso gli archi verso l’interno della corte, creando profondità e atmosfera.\n\nIl dipinto è presentato entro un’importante cornice nera riccamente lavorata a rilievo, che ne accentua il carattere decorativo.","images":["assets/images/A117/A117-01.webp","assets/images/A117/A117-02.webp","assets/images/A117/A117-03.webp","assets/images/A117/A117-04.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XX secolo"},{"label":"Stile","value":"Figurativo / paesaggio architettonico"},{"label":"Tecnica","value":"Olio su tela"},{"label":"Soggetto","value":"Scorcio architettonico con corte"},{"label":"Materiale","value":"Tela, cornice in legno lavorato"}],"epoch_it":"XX secolo","style_it":"Figurativo / paesaggio architettonico","material_it":"Tela, cornice in legno lavorato","description_en":"","description_fr":""},"A118":{"category_key":"paintings","title_it":"Paesaggio pastorale con figure e animali","category_it":"Dipinti","dimensions":"H 64 × L 86 cm","description_it":"Dipinto raffigurante un ampio paesaggio pastorale, animato in primo piano da piccole figure e da un gregge con diversi animali al pascolo. La scena si sviluppa tra una fitta vegetazione ombrosa sulla sinistra e un paesaggio collinare che si apre in profondità sulla destra, dove si distingue un insediamento fortificato sulla sommità del rilievo.\n\nLa composizione, caratterizzata da forti contrasti chiaroscurali e da tonalità brune, verdi e dorate, richiama la tradizione del paesaggio classico italiano. Particolarmente piacevoli i piccoli dettagli delle figure e degli animali, che conferiscono movimento alla scena.\n\nPresentato entro importante cornice dorata riccamente lavorata e modanata.","images":["assets/images/A118/A118-01.webp","assets/images/A118/A118-02.webp","assets/images/A118/A118-03.webp","assets/images/A118/A118-04.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"da verificare"},{"label":"Stile","value":"Paesaggio classico / pastorale"},{"label":"Tecnica","value":"Olio su tela"},{"label":"Soggetto","value":"Paesaggio con figure e animali"},{"label":"Materiale","value":"Tela, cornice in legno dorato"}],"epoch_it":"da verificare","style_it":"Paesaggio classico / pastorale","material_it":"Tela, cornice in legno dorato","description_en":"","description_fr":""},"A119":{"category_key":"paintings","title_it":"“Charlie” – scena equestre con cavallo, cavaliere e cane","category_it":"Dipinti","dimensions":"H46xL56","description_it":"Dipinto di gusto equestre raffigurante un cavallo baio sellato accompagnato dal suo cavaliere e da un piccolo cane, ambientati all’ingresso di una proprietà di campagna. La composizione, curata nei dettagli dell’animale, della bardatura e dell’abbigliamento, richiama la tradizione della pittura equestre britannica.\n\nSul margine inferiore compaiono le iscrizioni “CHARLIE.” e “STUART DOUGLAS.”. L’opera è presentata entro una cornice in legno scuro con ampia fascia interna dorata.","images":["assets/images/A119/A119-01.webp","assets/images/A119/A119-02.webp","assets/images/A119/A119-03.webp","assets/images/A119/A119-04.webp","assets/images/A119/A119-05.webp","assets/images/A119/A119-06.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XIX secolo / inizi XX secolo circa"},{"label":"Stile","value":"pittura equestre britannica"},{"label":"Soggetto","value":"cavallo “Charlie” con cavaliere e cane"},{"label":"Tecnica","value":"da verificare dal vivo"},{"label":"Materiale","value":"supporto pittorico, cornice in legno con profilo dorato"}],"epoch_it":"XIX secolo / inizi XX secolo circa","style_it":"pittura equestre britannica","material_it":"supporto pittorico, cornice in legno con profilo dorato","description_en":"","description_fr":""},"A120":{"category_key":"paintings","title_it":"Roberto Crippa, Composizione astratta-Spirali","category_it":"Dipinti","dimensions":"H 108 × L 95 cm, cornice compresa","description_it":"Grande serigrafia di Roberto Crippa (Monza, 1921 – Bresso, 1972), riconducibile alla celebre ricerca delle “Spirali”, uno dei motivi più rappresentativi della produzione dell’artista e della sua adesione allo Spazialismo.\n\nLa composizione presenta un intenso fondo rosso attraversato da una fitta trama di linee bianche, sviluppate in vortici, traiettorie e sovrapposizioni che creano un forte senso di movimento e profondità.\n\nSi tratta di una serigrafia retroestesa realizzata in edizione limitata di 99 esemplari. Sul retro è presente la dichiarazione di Rosangela Baggini che attesta che l’opera grafica fu ideata da Roberto Crippa ed eseguita, secondo il desiderio dell'artista, nella tiratura da 1/99 a 99/99. Esemplare apparentemente numerato 43/99.\n\nFirma presente in basso a destra.\n\nL'opera è montata entro una grande cornice laccata bordeaux con superficie trasparente, che lascia visibile lo spazio intorno alla composizione.","images":["assets/images/A120/A120-01.webp","assets/images/A120/A120-02.webp","assets/images/A120/A120-03.webp","assets/images/A120/A120-04.webp","assets/images/A120/A120-05.webp","assets/images/A120/A120-06.webp","assets/images/A120/A120-07.webp","assets/images/A120/A120-08.webp","assets/images/A120/A120-09.webp"],"status":"available","specs_it":[{"label":"Autore","value":"Roberto Crippa (1921–1972)"},{"label":"Titolo","value":"Spirali / Senza titolo"},{"label":"Epoca","value":"seconda metà del XX secolo"},{"label":"Stile","value":"Spazialismo / astrattismo gestuale"},{"label":"Tecnica","value":"serigrafia retroestesa"},{"label":"Tiratura","value":"99 esemplari, apparentemente es. 43/99"},{"label":"Autenticazione","value":"dichiarazione al retro di Rosangela Baggini"},{"label":"Dimensioni complessive","value":"H 108 × L 95 cm"}],"epoch_it":"seconda metà del XX secolo","style_it":"Spazialismo / astrattismo gestuale","description_en":"","description_fr":""},"A121":{"category_key":"furniture","title_it":"Credenza / buffet in radica intarsiata con fianchi curvi","category_it":"Mobili","dimensions":"Da misurare","description_it":"Elegante credenza a tre ante caratterizzata da una ricca impiallacciatura in radica dalle calde tonalità ambrate, impreziosita da raffinati intarsi geometrici in essenze lignee a contrasto.\n\nIl mobile presenta un fronte architettonico e simmetrico, con grande anta centrale affiancata da due ante laterali poste sui caratteristici fianchi arrotondati. Lesene verticali, cornici modanate e fasce intarsiate scandiscono la superficie, mentre piccoli motivi romboidali decorano i pannelli delle ante.\n\nParticolarmente suggestiva la marezzatura naturale della radica, scelta e disposta in modo da valorizzare il disegno del legno. Il piano superiore segue elegantemente il profilo curvilineo del mobile.\n\nEsemplare di notevole presenza decorativa, adatto sia ad ambienti classici sia come pezzo d’accento in interni contemporanei.","images":["assets/images/A121/A121-01.webp","assets/images/A121/A121-02.webp","assets/images/A121/A121-03.webp","assets/images/A121/A121-04.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"presumibilmente fine XIX – inizi XX secolo"},{"label":"Stile","value":"gusto eclettico / revival ottocentesco"},{"label":"Materiale","value":"legno impiallacciato in radica, intarsi in essenze lignee a contrasto"}],"epoch_it":"presumibilmente fine XIX – inizi XX secolo","style_it":"gusto eclettico / revival ottocentesco","material_it":"legno impiallacciato in radica, intarsi in essenze lignee a contrasto","description_en":"","description_fr":""},"A122":{"category_key":"paintings","title_it":"Ralph Wolfe Cowan (1931–2018) – Grande ritratto femminile – 1980","category_it":"Dipinti","dimensions":"Da misurare","description_it":"Ralph Wolfe Cowan (1931–2018) è stato un celebre ritrattista americano, noto per aver dipinto importanti personalità internazionali, tra cui Grace Kelly, Principessa di Monaco. Nel 1956 realizzò il celebre ritratto della Principessa Grace oggi appartenente al Palazzo del Principe di Monaco. Nel corso della sua carriera ritrasse inoltre membri di famiglie reali, capi di Stato e protagonisti del mondo dello spettacolo.\n\nL'opera raffigura una giovane donna elegantemente vestita di bianco, seduta su una poltrona, con gioielli e un piccolo fiore nella mano. La figura emerge su un ampio sfondo atmosferico nei toni dell'azzurro e del grigio, con un'impostazione teatrale tipica della ritrattistica glamour dell'artista.\n\nIn basso a sinistra è presente la firma autografa “Ralph Wolfe Cowan” accompagnata dalla data 1980, chiaramente visibile nelle fotografie di dettaglio.\n\nIl dipinto è inserito in un'importante cornice decorativa nera e dorata, che contribuisce alla forte presenza scenografica dell'insieme.","images":["assets/images/A122/A122-01.webp","assets/images/A122/A122-02.webp","assets/images/A122/A122-03.webp","assets/images/A122/A122-04.webp"],"status":"available","specs_it":[{"label":"Autore","value":"Ralph Wolfe Cowan (1931–2018)"},{"label":"Data","value":"1980"},{"label":"Tecnica","value":"olio su tela, da confermare dal retro"},{"label":"Soggetto","value":"ritratto femminile"},{"label":"Firma","value":"firmato e datato in basso a sinistra"},{"label":"Paese d'origine","value":"Stati Uniti"},{"label":"Epoca","value":"1980"},{"label":"Cornice","value":"presente, nera e dorata"},{"label":"Background dell'Artista","value":"Ralph Wolfe Cowan realizzò nel 1956 un ritratto ufficiale di Grace Kelly, Principessa Grace di Monaco. Il Catalog of American Portraits della Smithsonian National Portrait Gallery registra l'opera come olio su tela, datata 1956, con Cowan come artista e Grace Kelly come soggetto; indica inoltre come proprietario il Palazzo del Principe di Monaco."}],"epoch_it":"1980","description_en":"","description_fr":""},"A123":{"category_key":"furniture","title_it":"Coppia di antichi comodini / mensole da parete dorate con piano in marmo – XVIII/primo XIX secolo","category_it":"Mobili","dimensions":"Da misurare","description_it":"Importante coppia di antiche mensole da parete risalenti tra il XVIII e il primo XIX secolo, caratterizzate da una raffinata struttura intagliata e dorata e da piani sagomati a mezzaluna in vero marmo.\n\nLa fascia frontale presenta una ricca decorazione intagliata a motivi vegetali, mentre la parte inferiore è costruita attraverso eleganti volute contrapposte e riccioli, secondo il repertorio ornamentale tardobarocco e rococò.\n\nI piani in marmo, dalle calde tonalità rosso-ocra con venature naturali, creano un elegante contrasto con la doratura della struttura.\n\nParticolarmente interessante e non comune la conservazione della coppia, concepita per una disposizione simmetrica. Possono essere utilizzate come piccole console sospese, mensole decorative o comodini da parete ai lati di un letto.\n\nLa doratura conserva patina, usure e variazioni cromatiche coerenti con l'età, elementi che testimoniano la lunga storia degli arredi e ne mantengono il fascino autentico.","images":["assets/images/A123/A123-01.webp","assets/images/A123/A123-02.webp"],"status":"available","specs_it":[{"label":"Epoca","value":"XVIII – primo XIX secolo"},{"label":"Stile","value":"tardobarocco / rococò"},{"label":"Materiali","value":"legno intagliato e dorato, vero marmo"},{"label":"Dimensioni indicative ciascuna","value":"H 38 × L 60 × P 27 cm circa – da verificare"}],"epoch_it":"XVIII – primo XIX secolo","style_it":"tardobarocco / rococò","material_it":"legno intagliato e dorato, vero marmo","description_en":"","description_fr":""},"A124":{"category_key":"paintings","title_it":"Coppia di paesaggi marini in burrasca, studio da Antonio Maria Marini, firmati Maria Marini","category_it":"Dipinti","dimensions":"Dimensioni ciascuno: H 81 × L 91 × P 6 cm circa.","description_it":"Coppia di dipinti raffiguranti paesaggi marini in burrasca, caratterizzati da una composizione fortemente scenografica: coste rocciose e fortificate emergono da un mare agitato, solcato da onde spumeggianti, mentre imbarcazioni e rilievi montuosi animano lo sfondo.\n\nLe opere riprendono la tradizione pittorica di Antonio Maria Marini (Venezia, 1668–1725), noto per paesaggi fantastici e marine tempestose. I dipinti sono firmati “Maria Marini” e sono studio/derivazione da Antonio Maria Marini.\n\nEntrambi conservano cornici dorate riccamente modanate e decorate, coerenti con il carattere classico delle composizioni.\n\nDimensioni ciascuno: H 81 × L 91 × P 6 cm circa.","images":["assets/images/A124/A124-01.webp"],"status":"available","specs_it":[{"label":"Dimensioni ciascuno","value":"H 81 × L 91 × P 6 cm circa."}],"description_en":"","description_fr":""},"A126":{"category_key":"sculptures","title_it":"Paolo Troubetzkoy (1866–1938), Cowboy su cavallo che scalcia","category_it":"Sculture","category_en":"Sculptures","category_fr":"Sculptures","dimensions":"H 37 × L 20 × P 27 cm","description_it":"Importante scultura equestre in bronzo patinato di Paolo Troubetzkoy (Intra, 1866 – Pallanza, 1938), raffigurante un cowboy su un cavallo nell’atto di scalciare.\n\nLa composizione, di grande dinamismo, mostra il cavallo con il capo fortemente abbassato e il corpo in tensione, mentre il cavaliere trattiene le redini con una mano e protende energicamente l’altro braccio. Il modellato rapido e vibrante, la superficie movimentata e l’immediatezza della rappresentazione sono caratteristiche della produzione scultorea di Troubetzkoy.\n\nIl soggetto trova preciso riscontro nel modello “Cowboy su cavallo che scalcia” conservato in gesso presso il Museo del Paesaggio di Verbania (inv. T n. 76), opera appartenente alla produzione tarda dell’artista e databile agli anni Trenta.\n\nEsemplare in bronzo a patina scura, firmato sulla base. La base naturalistica è modellata unitamente alla composizione e riproduce il terreno sul quale si svolge la scena.","images":["assets/images/A126/A126-01.webp","assets/images/A126/A126-02.webp","assets/images/A126/A126-03.webp","assets/images/A126/A126-04.webp","assets/images/A126/A126-05.webp","assets/images/A126/A126-06.webp","assets/images/A126/A126-07.webp","assets/images/A126/A126-08.webp"],"status":"available","specs_it":[{"label":"Autore","value":"Paolo Troubetzkoy (1866–1938)"},{"label":"Soggetto","value":"Cowboy su cavallo che scalcia"},{"label":"Epoca","value":"circa 1930–1937"},{"label":"Materiale","value":"bronzo patinato"},{"label":"Firma","value":"firmata sulla base"},{"label":"Dimensioni","value":"H 37 × L 20 × P 27 cm"}],"epoch_it":"circa 1930–1937","material_it":"bronzo patinato","description_en":"","description_fr":""},"A127":{"category_key":"sculptures","title_it":"Paolo Troubetzkoy (1866–1938) - Giovane con asinello, scultura in bronzo","category_it":"Sculture","category_en":"Sculptures","category_fr":"Sculptures","dimensions":"H 32 × L 17 × P 26 cm","description_it":"Gruppo scultoreo in bronzo patinato attribuito a Paolo Troubetzkoy (Intra, 1866 – Pallanza, 1938), raffigurante un giovane viandante o contadino accompagnato da un asinello.\n\nLa figura maschile è rappresentata scalza, con pantaloni corti, fazzoletto annodato al collo e ampio cappello. La posa, con il capo inclinato e appoggiato alla mano, conferisce alla composizione un carattere spontaneo e narrativo. Accanto al giovane, l'asinello è modellato con particolare attenzione alla fisionomia e ai dettagli dei finimenti.\n\nIl gruppo poggia su una base naturalistica irregolare, lavorata a imitazione del terreno. La modellazione vivace delle superfici, l'interesse per la figura colta in un atteggiamento quotidiano e la presenza dell'animale sono coerenti con soggetti ricorrenti nella produzione di Troubetzkoy, che dedicò numerose opere anche al rapporto tra figure umane e animali. È documentata, ad esempio, la presenza di un suo Ragazzo e cane alla Mostra Nazionale di Belle Arti di Milano del 1906. (https://dizionariodartesartori.it/artisti/troubetzkoy-paolo)\n\nCaratteristiche","images":["assets/images/A127/A127-01.webp","assets/images/A127/A127-02.webp","assets/images/A127/A127-03.webp","assets/images/A127/A127-04.webp","assets/images/A127/A127-05.webp","assets/images/A127/A127-06.webp","assets/images/A127/A127-07.webp","assets/images/A127/A127-08.webp","assets/images/A127/A127-09.webp"],"status":"available","specs_it":[{"label":"Autore","value":"Paolo Troubetzkoy (1866–1938)"},{"label":"Soggetto","value":"giovane con asinello"},{"label":"Materiale","value":"bronzo patinato"},{"label":"Epoca","value":"prima metà XX secolo"},{"label":"Dimensioni","value":"H 32 × L 17 × P 26 cm"}],"material_it":"bronzo patinato","epoch_it":"prima metà XX secolo","description_en":"","description_fr":""},"A128":{"category_key":"sculptures","title_it":"Paolo Troubetzkoy (1866–1938), scultura in bronzo “Giovane pastore con capra”","category_it":"Sculture","category_en":"Sculptures","category_fr":"Sculptures","dimensions":"H 40 × L 20 × P 23 cm","description_it":"Scultura figurativa in bronzo patinato raffigurante un giovane pastore scalzo accompagnato da una capra. Il giovane, con ampio cappello e pantaloni arrotolati, è rappresentato in una posa vivace mentre sostiene sottili rami con foglie; al suo fianco la capra è raffigurata con campanaccio al collo.\n\nLa composizione poggia su una base naturalistica irregolare, modellata a simulare il terreno. Particolarmente accurata la resa dei dettagli anatomici, dell’espressione del volto, degli abiti e del manto dell’animale.\n\nLa superficie conserva una patina scura con sfumature brune e naturali variazioni dovute al tempo. Visibili elementi di fissaggio nella parte inferiore della base.","images":["assets/images/A128/A128-01.webp","assets/images/A128/A128-02.webp","assets/images/A128/A128-03.webp","assets/images/A128/A128-04.webp","assets/images/A128/A128-05.webp","assets/images/A128/A128-06.webp","assets/images/A128/A128-07.webp","assets/images/A128/A128-08.webp","assets/images/A128/A128-09.webp"],"status":"available","specs_it":[{"label":"Autore","value":"Paolo Troubetzkoy (1866–1938)"},{"label":"Epoca","value":"fine XIX – inizi XX secolo"},{"label":"Materiale","value":"bronzo patinato"},{"label":"Soggetto","value":"giovane pastore con capra"},{"label":"Dimensioni","value":"H 40 × L 20 × P 23 cm"}],"epoch_it":"fine XIX – inizi XX secolo","material_it":"bronzo patinato","description_en":"","description_fr":""},"A129":{"category_key":"seating","title_it":"Divanetto Luigi XV con ricamo floreale Cannetta Milano","category_it":"Sedute e salotti","category_en":"Seating and salons","category_fr":"Sièges et salons","dimensions":"H 74 × L 113 × P 50 cm","description_it":"Elegante divanetto a due posti in stile Luigi XV, caratterizzato da una struttura in legno sagomato e intagliato, con linea avvolgente dello schienale e dei fianchi, grembiale mosso e gambe arcuate di gusto rocaille.\n\nLa seduta e lo schienale sono rivestiti in tessuto nei toni naturali del beige, impreziosito da importanti ricami floreali policromi raffiguranti composizioni di rose e altri fiori nei toni del rosa, avorio, verde e lilla. Il ricamo è stato realizzato dal noto atelier Cannetta di Milano, elemento particolarmente interessante per la qualità decorativa e la provenienza milanese della lavorazione tessile.\n\nIl rivestimento è rifinito lungo il profilo della struttura con una fila continua di borchie decorative. La struttura lignea presenta intagli floreali e motivi a volute, particolarmente evidenti sul grembiale anteriore e in corrispondenza delle gambe.\n\nL'insieme conserva un aspetto elegante e decorativo, con normale patina e segni del tempo sulla struttura lignea e sul rivestimento, coerenti con l'età e l'uso. I ricami costituiscono l'elemento distintivo del pezzo e sono particolarmente adatti a valorizzare il divanetto in un ambiente classico o in contrasto con un arredamento contemporaneo.\n\nCaratteristiche","images":["assets/images/A129/A129-01.webp","assets/images/A129/A129-02.webp"],"status":"available","specs_it":[{"label":"Tipologia","value":"divanetto / canapé a due posti"},{"label":"Epoca","value":"Luigi XV / Rocaille"},{"label":"Materiale","value":"legno intagliato, tessuto e ricamo policromo"},{"label":"Ricamo","value":"Cannetta, Milano"},{"label":"Decorazione","value":"composizioni floreali con rose e fiori"},{"label":"Dimensioni","value":"H 74 × L 113 × P 50 cm"}],"epoch_it":"Luigi XV / Rocaille","material_it":"legno intagliato, tessuto e ricamo policromo","description_en":"","description_fr":""},"A130":{"category_key":"sculptures","title_it":"Giuseppe Renda – Giovane figura maschile con copricapo","title_en":"Bronze Figure of a Young Man with Flower, Signed F. Renda","title_fr":"Sculpture en bronze, jeune homme à la fleur, signée F. Renda","category_it":"Sculture","category_en":"Sculptures","category_fr":"Sculptures","dimensions":"H 39 × L 15 × P 7 cm","description_it":"Scultura in bronzo patinato di Giuseppe Renda (1859–1939), raffigurante una giovane figura maschile stante, colta in posa dinamica con un braccio sollevato e l'altro appoggiato al fianco. Il personaggio indossa un ampio copricapo modellato con forte resa plastica e un essenziale drappeggio ai fianchi.\n\nLa figura presenta superfici levigate nel corpo, contrapposte alla modellazione più materica del copricapo e della base irregolare. Firma “G. RENDA” impressa sulla base + iscrizione relativa ai diritti d'autore.","description_en":"Patinated bronze figure of a standing young man raising a flower in one hand. The elongated, animated figure rests on a rectangular naturalistic base bearing the signature “F. Renda” and a “Scultura d’autore” foundry mark.","description_fr":"Figure en bronze patiné représentant un jeune homme debout levant une fleur. La silhouette élancée repose sur une base naturaliste rectangulaire portant la signature « F. Renda » et la marque « Scultura d’autore ».","images":["assets/images/A130/A130-01.webp","assets/images/A130/A130-02.webp","assets/images/A130/A130-03.webp","assets/images/A130/A130-04.webp","assets/images/A130/A130-05.webp","assets/images/A130/A130-06.webp","assets/images/A130/A130-07.webp","assets/images/A130/A130-08.webp","assets/images/A130/A130-09.webp","assets/images/A130/A130-10.webp","assets/images/A130/A130-11.webp"],"status":"available","epoch_it":"XX secolo","material_it":"bronzo patinato","specs_it":[{"label":"Autore","value":"F. Renda"},{"label":"Epoca","value":"XX secolo"},{"label":"Materiale","value":"bronzo patinato"},{"label":"Soggetto","value":"giovane con fiore"},{"label":"Dimensioni","value":"H 39 × L 15 × P 7 cm"}]},"A131":{"category_key":"furniture","title_it":"Grande libreria in stile Impero – XIX secolo","title_en":"Large Empire Style Open Bookcase with Columns","title_fr":"Grande bibliothèque ouverte de style Empire à colonnes","category_it":"Mobili","category_en":"Furniture","category_fr":"Mobilier","dimensions":"Da misurare","description_it":"Grande libreria a giorno in legno, articolata in tre vani con ripiani regolabili, scanditi da quattro colonne tornite con capitelli intagliati a motivo fogliato. Ampia cornice superiore modanata, schienale in tavole e base sagomata. Struttura architettonica di gusto Impero, dalle proporzioni monumentali.","description_en":"Large open wooden bookcase of architectural Empire inspiration. Four turned columns divide the façade into three vertical bays fitted with removable shelves, beneath a strongly projecting cornice and above a moulded plinth.","description_fr":"Grande bibliothèque ouverte en bois d’inspiration architecturale Empire. Quatre colonnes tournées divisent la façade en trois travées munies de tablettes amovibles, sous une corniche saillante et au-dessus d’une base moulurée.","images":["assets/images/A131/A131-01.webp","assets/images/A131/A131-02.webp","assets/images/A131/A131-03.webp"],"status":"available","epoch_it":"XIX secolo","style_it":"Impero","material_it":"legno","specs_it":[{"label":"Epoca","value":"XIX secolo"},{"label":"Stile","value":"Impero"},{"label":"Materiale","value":"legno"},{"label":"Struttura","value":"tre vani con ripiani mobili"}]},"A132":{"category_key":"seating","title_it":"Set di sei sedie intarsiate","title_en":"Set of Six Italian Neoclassical Inlaid Wood Chairs","title_fr":"Suite de six chaises italiennes néoclassiques en bois marqueté","category_it":"Sedute e salotti","category_en":"Seating","category_fr":"Sièges","dimensions":"Da misurare","description_it":"Set di sei sedie in legno, caratterizzate da schienale a giorno con elemento centrale sagomato e fascia superiore decorata da intarsio a motivo floreale. Gambe anteriori rastremate e struttura dalle linee sobrie di gusto neoclassico.\n\nSedute rivestite in tessuto bianco.","description_en":"Set of six Italian Neoclassical chairs in wood, with open rectangular backs centred by shaped splats and upper rails decorated with floral inlay. Tapered front legs and white upholstered seats complete the restrained design.","description_fr":"Suite de six chaises italiennes néoclassiques en bois, à dossiers ajourés ornés d’un élément central découpé et d’une traverse supérieure à décor floral marqueté. Les pieds antérieurs fuselés et les assises garnies de tissu blanc complètent cet ensemble aux lignes sobres.","images":["assets/images/A132/A132-01.webp","assets/images/A132/A132-02.webp"],"status":"available","epoch_it":"XIX secolo","style_it":"Neoclassico","material_it":"legno intagliato e tessuto","specs_it":[{"label":"Composizione","value":"sei sedie"},{"label":"Epoca","value":"XIX secolo"},{"label":"Stile","value":"Neoclassico"},{"label":"Materiali","value":"legno intagliato, imbottitura e tessuto"}]}};
